package com.eggscape;

import java.util.function.ToLongFunction;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * One-off goals with an egg reward. Goals you can keep levelling are {@link AchievementTrack}s.
 * Completed achievements are saved by enum name, so never rename these constants.
 */
@Getter
@RequiredArgsConstructor
public enum Achievement
{
	FIRST_CLUCK("First Cluck", "Hatch your first chicken", 1, 5,
		f -> f.getState().hatchedTotal),
	DOUBLE_TROUBLE("Double Trouble", "Hatch twins", 1, 25,
		f -> f.getState().twinsHatched),
	RAINBOW("Taste the Rainbow", "Get a green, a blue and a red egg", 3, 50,
		f -> f.colouredEggTypesObtained()),
	FULLY_UPGRADED("Fully Upgraded", "Max out any upgrade", 1, 100,
		FarmManager::maxedUpgrades),
	GOLDEN_TOUCH("Golden Touch", "Get a Golden hen", 1, 150,
		f -> f.getState().hensObtained[HenType.GOLDEN.ordinal()]),
	SHINY("Ooh, Shiny!", "Get a shiny chicken", 1, 200,
		FarmManager::shiniesObtained),
	BORN_AGAIN("Born Again", "Sell your farm for Golden Feathers", 1, 250,
		f -> f.getState().prestiges),
	HAPPY_EASTER("Happy Easter!", "Get a super rare Easter egg", 1, 300,
		f -> f.getState().eggsObtained[EggType.EASTER.ordinal()]),
	LIVING_HEN("Night of the Living Hen", "Get an Undead hen", 1, 200,
		f -> f.getState().hensObtained[HenType.UNDEAD.ordinal()]),
	COLLECTOR("Collector", "Complete the collection log", FarmManager.COLLECTION_SIZE, 500,
		FarmManager::collectionProgress);

	private final String displayName;
	private final String description;
	private final long target;
	private final int reward;
	private final ToLongFunction<FarmManager> progress;

	long progress(FarmManager farm)
	{
		return Math.min(target, progress.applyAsLong(farm));
	}
}

package com.eggscape;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * The OSRS metals, used as the tiers of an {@link AchievementTrack}.
 */
@Getter
@RequiredArgsConstructor
public enum AchievementTier
{
	BRONZE("Bronze", new Color(160, 104, 56), 25, 100),
	IRON("Iron", new Color(120, 116, 112), 50, 150),
	STEEL("Steel", new Color(176, 176, 186), 100, 250),
	MITHRIL("Mithril", new Color(84, 84, 170), 200, 400),
	ADAMANT("Adamant", new Color(72, 132, 72), 400, 600),
	RUNE("Rune", new Color(72, 172, 196), 800, 900),
	DRAGON("Dragon", new Color(190, 34, 30), 2000, 1500);

	private final String displayName;
	private final Color color;
	private final int rewardEggs;
	private final int rewardXp;
}

package com.eggscape;

import java.util.function.ToLongFunction;
import lombok.Getter;
import net.runelite.client.util.QuantityFormatter;

/**
 * Achievements you keep levelling, from Bronze up to Dragon. Progress is saved by enum name, so never rename these.
 */
@Getter
public enum AchievementTrack
{
	FARMER("Farmer", "Reach Farm level %s",
		new long[]{10, 25, 40, 55, 70, 85, 99}, FarmManager::farmLevel,
		"GREEN_THUMB", 10, "MASTER_FARMER", 50),
	EGG_HUNTER("Egg Hunter", "Find %s eggs while playing",
		new long[]{100, 500, 2_500, 10_000, 25_000, 50_000, 100_000}, f -> f.getState().eggsFound,
		"EGG_HUNTER", 100, "EGG_HOARDER", 1000),
	HATCHERY("Hatchery", "Hatch %s chickens",
		new long[]{10, 100, 500, 1_500, 4_000, 10_000, 25_000}, f -> f.getState().hatchedTotal,
		"HATCHERY", 100),
	HEN_PARTY("Hen Party", "Own %s hens at the same time",
		new long[]{10, 20, 30, 45, 60, 75, 86}, FarmManager::henCount,
		"FLOCK_OF_TEN", 10, "HEN_PARTY", 30),
	POULTRY_SLAYER("Poultry Slayer", "Kill %s chickens in-game",
		new long[]{25, 100, 250, 500, 1_000, 2_500, 5_000}, f -> f.getState().chickensKilled,
		"POULTRY_SLAYER", 25),
	UNINVITED_GUESTS("Uninvited Guests", "Complete %s farm events",
		new long[]{10, 25, 50, 100, 250, 500, 1_000}, FarmManager::eventsCompleted,
		"UNINVITED_GUESTS", 10),
	FOWL_PLAY("Fowl Play", "Chase off the Evil Chicken %s times",
		new long[]{5, 15, 30, 60, 100, 200, 400}, f -> f.getState().eventWins[FarmEvent.EVIL_CHICKEN.ordinal()],
		"FOWL_PLAY", 5),
	TASK_MASTER("Task Master", "Complete %s daily tasks",
		new long[]{20, 50, 100, 200, 365, 600, 1_000}, f -> f.getState().tasksCompleted,
		"TASK_MASTER", 20),
	LOYAL_FARMER("Loyal Farmer", "Reach a %s day login streak",
		new long[]{7, 14, 30, 60, 100, 200, 365}, f -> f.getState().bestStreak,
		"LOYAL_FARMER", 7);

	private final String displayName;
	private final String format;
	/**
	 * Target per {@link AchievementTier}, Bronze first.
	 */
	private final long[] targets;
	private final ToLongFunction<FarmManager> progress;
	/**
	 * Old one-off achievements this track replaced, as name/target pairs, so their rewards aren't paid twice.
	 */
	private final Object[] legacy;

	AchievementTrack(String displayName, String format, long[] targets, ToLongFunction<FarmManager> progress, Object... legacy)
	{
		this.displayName = displayName;
		this.format = format;
		this.targets = targets;
		this.progress = progress;
		this.legacy = legacy;
	}

	long progress(FarmManager farm)
	{
		return progress.applyAsLong(farm);
	}

	String describe(AchievementTier tier)
	{
		return String.format(format, QuantityFormatter.formatNumber(targets[tier.ordinal()]));
	}

	/**
	 * Same as {@link #describe} but with short numbers (100K) for tight spaces.
	 */
	String describeShort(AchievementTier tier)
	{
		return String.format(format, QuantityFormatter.quantityToStackSize(targets[tier.ordinal()]));
	}
}

package com.eggscape;

import static com.eggscape.FarmManager.EGG_COLOR;
import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Random;

/**
 * The daily login reward (with its streak) and the three daily tasks with their bonus chest.
 * Runs on the client thread.
 */
class DailyRewards
{
	private static final int TASK_XP = 100;
	private static final int CHEST_XP = 250;
	private static final int DAILY_XP = 50;
	private static final double EASTER_IN_CHEST_CHANCE = 0.03;

	private final FarmManager farm;
	private final Random random = new Random();
	/**
	 * Today's reward card is waiting to be claimed; don't queue another one.
	 */
	private boolean rewardQueued;

	DailyRewards(FarmManager farm)
	{
		this.farm = farm;
	}

	void reset()
	{
		rewardQueued = false;
	}

	/**
	 * Hands out today's reward card and today's tasks, once per day.
	 */
	void checkNewDay(FarmState state)
	{
		long today = LocalDate.now().toEpochDay();
		if (state.lastDailyDay < today && !rewardQueued)
		{
			queueReward(state, today);
		}
		if (farm.farmLevel() >= FarmManager.LEVEL_DAILY_TASKS && state.taskDay != today)
		{
			generateTasks(state, today);
		}
	}

	// ---------------------------------------------------------------- login reward

	private void queueReward(FarmState state, long today)
	{
		final int streak = state.lastDailyDay == today - 1 ? state.streak + 1 : 1;
		final long eggs = dailyEggs(streak);
		final EggType bonus = dailyBonusEgg(streak);

		List<String> lines = new ArrayList<>();
		lines.add("Day " + streak + " in a row!");
		lines.add(eggs + " eggs" + (bonus != null ? " and a " + bonus.getDisplayName().toLowerCase() : "") + ".");
		if (streak == 1 && state.streak > 1)
		{
			lines.add("Your " + state.streak + " day streak was lost.");
		}
		rewardQueued = true;
		farm.showDialog(new FarmManager.Dialog("Daily reward", lines, "Claim", null, () -> claimReward(today, streak, eggs, bonus)));
	}

	private void claimReward(long today, int streak, long eggs, EggType bonus)
	{
		rewardQueued = false;
		FarmState state = farm.getState();
		if (state == null || state.lastDailyDay >= today)
		{
			return;
		}
		state.lastDailyDay = today;
		state.streak = streak;
		state.bestStreak = Math.max(state.bestStreak, streak);
		farm.giveEgg(EggType.PLAIN, eggs);
		farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.EGG_BAR, EggType.PLAIN.ordinal());
		if (bonus != null)
		{
			farm.giveEgg(bonus, 1);
			farm.popup("+1", bonus.getColor(), FarmManager.Anchor.EGG_BAR, bonus.ordinal());
		}
		farm.addFarmXp(DAILY_XP, true);
		farm.save();
	}

	/**
	 * A 7 day cycle that grows by 50% every week you keep the streak going.
	 */
	static long dailyEggs(int streak)
	{
		int[] cycle = {10, 20, 20, 40, 30, 60, 100};
		int day = (streak - 1) % cycle.length;
		int week = (streak - 1) / cycle.length;
		return Math.round(cycle[day] * (1 + 0.5 * week));
	}

	static EggType dailyBonusEgg(int streak)
	{
		switch ((streak - 1) % 7 + 1)
		{
			case 3:
				return EggType.GREEN;
			case 5:
				return EggType.BLUE;
			case 7:
				return EggType.RED;
			default:
				return null;
		}
	}

	static long secondsUntilReset()
	{
		LocalDateTime now = LocalDateTime.now();
		return Duration.between(now, now.toLocalDate().plusDays(1).atStartOfDay()).getSeconds();
	}

	// ---------------------------------------------------------------- tasks

	private void generateTasks(FarmState state, long today)
	{
		List<TaskType> pool = new ArrayList<>(Arrays.asList(TaskType.values()));
		Collections.shuffle(pool, random);
		state.tasks.clear();
		for (int i = 0; i < FarmState.TASKS_PER_DAY; i++)
		{
			FarmState.DailyTask task = new FarmState.DailyTask();
			task.type = pool.get(i).ordinal();
			task.target = pool.get(i).rollTarget(random);
			state.tasks.add(task);
		}
		state.taskDay = today;
		state.taskChestClaimed = false;
	}

	/**
	 * Counts something the player did towards today's tasks.
	 */
	void progress(TaskType type, long amount)
	{
		FarmState state = farm.getState();
		if (state == null || state.tasks.isEmpty() || farm.farmLevel() < FarmManager.LEVEL_DAILY_TASKS)
		{
			return;
		}
		for (FarmState.DailyTask task : state.tasks)
		{
			if (task.type != type.ordinal() || task.claimed || task.isComplete())
			{
				continue;
			}
			task.progress = Math.min(task.target, task.progress + amount);
			if (task.isComplete())
			{
				farm.showToast("Task done!");
			}
		}
	}

	long taskRewardEggs()
	{
		return 25 + 2L * farm.farmLevel();
	}

	void claimTask(int index)
	{
		FarmState state = farm.getState();
		if (state == null || index < 0 || index >= state.tasks.size())
		{
			return;
		}
		FarmState.DailyTask task = state.tasks.get(index);
		if (task.claimed || !task.isComplete())
		{
			return;
		}
		task.claimed = true;
		state.tasksCompleted++;
		long eggs = taskRewardEggs();
		farm.giveEgg(EggType.PLAIN, eggs);
		farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.EGG_BAR, EggType.PLAIN.ordinal());
		farm.addFarmXp(TASK_XP, true);
		farm.save();
	}

	boolean isChestClaimable()
	{
		FarmState state = farm.getState();
		if (state == null || state.tasks.isEmpty() || state.taskChestClaimed)
		{
			return false;
		}
		for (FarmState.DailyTask task : state.tasks)
		{
			if (!task.claimed)
			{
				return false;
			}
		}
		return true;
	}

	void claimChest()
	{
		if (!isChestClaimable())
		{
			return;
		}
		FarmState state = farm.getState();
		state.taskChestClaimed = true;
		long eggs = 50 + 5L * farm.farmLevel();
		EggType bonus = random.nextDouble() < EASTER_IN_CHEST_CHANCE ? EggType.EASTER : farm.rollColouredEgg(0.1, 0.3);
		farm.giveEgg(EggType.PLAIN, eggs);
		farm.giveEgg(bonus, 1);
		farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.EGG_BAR, EggType.PLAIN.ordinal());
		farm.popup("+1", bonus.getColor(), FarmManager.Anchor.EGG_BAR, bonus.ordinal());
		farm.addFarmXp(CHEST_XP, true);
		if (bonus == EggType.EASTER)
		{
			farm.gotEasterEgg("in your bonus chest");
		}
		farm.save();
	}

	boolean hasClaimable()
	{
		FarmState state = farm.getState();
		if (state == null)
		{
			return false;
		}
		for (FarmState.DailyTask task : state.tasks)
		{
			if (!task.claimed && task.isComplete())
			{
				return true;
			}
		}
		return isChestClaimable();
	}
}

package com.eggscape;

import static com.eggscape.Layout.CONTENT;
import static com.eggscape.Layout.WIDTH;
import static com.eggscape.Ui.BUY;
import static com.eggscape.Ui.BUY_HOVER;
import static com.eggscape.Ui.GOLD_DARK;
import static com.eggscape.Ui.PANEL_EDGE;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TITLE;
import static com.eggscape.Ui.button;
import static com.eggscape.Ui.buttonLabel;
import static com.eggscape.Ui.centeredAt;
import static com.eggscape.Ui.sparkles;
import static com.eggscape.Ui.wrap;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Message cards (daily reward, unlocks, rare drops), told by the farmer like an NPC chat in game.
 */
@Singleton
class DialogView extends PanelPart
{
	@Inject
	DialogView(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	void render(Graphics2D g, FarmManager.Dialog dialog, Point mouse, List<HitBox> boxes)
	{
		g.setColor(new Color(0, 0, 0, 130));
		g.fillRect(2, CONTENT.y, WIDTH - 4, CONTENT.height - 2);
		Rectangle box = new Rectangle(10, 28, WIDTH - 20, 124);
		g.setColor(new Color(48, 40, 30, 250));
		g.fill(box);
		g.setColor(GOLD_DARK);
		g.drawRect(box.x, box.y, box.width - 1, box.height - 1);
		g.setColor(PANEL_EDGE);
		g.drawRect(box.x + 1, box.y + 1, box.width - 3, box.height - 3);

		BufferedImage picture = sprites.dialogImage(dialog.image);
		if (picture != null)
		{
			// A prize or pet instead of the farmer, with a little glow
			int px = box.x + 4 + (36 - picture.getWidth()) / 2;
			int py = box.y + (box.height - 24 - picture.getHeight()) / 2 + 4;
			g.setColor(new Color(1f, 0.95f, 0.5f, 0.25f));
			g.fillOval(px - 4, py - 2, picture.getWidth() + 8, picture.getHeight() + 6);
			g.drawImage(picture, px, py, null);
			sparkles(g, px + picture.getWidth() / 2, py + picture.getHeight() / 2, 18, 2);
		}
		else
		{
			BufferedImage farmer = sprites.farmer();
			g.drawImage(farmer, box.x + 5, box.y + box.height - farmer.getHeight() - 26, null);
		}
		int textCenter = box.x + 38 + (box.width - 42) / 2;
		int textWidth = box.width - 46;

		g.setFont(FontManager.getRunescapeBoldFont());
		centeredAt(g, dialog.title, textCenter, box.y + 17, TITLE);
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		int y = box.y + 33;
		for (String line : dialog.lines)
		{
			for (String wrapped : wrap(line, fm, textWidth))
			{
				if (y > box.y + box.height - 28)
				{
					break;
				}
				centeredAt(g, wrapped, textCenter, y, TEXT);
				y += 12;
			}
		}

		// Everything under the dialog is blocked; only its buttons work
		boxes.add(0, new HitBox(CONTENT, () ->
		{
		}));
		int by = box.y + box.height - 22;
		if (dialog.cancel != null)
		{
			Rectangle cancel = new Rectangle(box.x + box.width - 90, by, 76, 16);
			button(g, cancel, dialog.cancel, false, cancel.contains(mouse), true);
			boxes.add(0, new HitBox(cancel, farm::cancelDialog));
			Rectangle confirm = new Rectangle(box.x + 14, by, 76, 16);
			confirmButton(g, confirm, dialog.confirm, confirm.contains(mouse));
			boxes.add(0, new HitBox(confirm, farm::confirmDialog));
		}
		else
		{
			Rectangle confirm = new Rectangle(box.x + (box.width - 80) / 2, by, 80, 16);
			confirmButton(g, confirm, dialog.confirm, confirm.contains(mouse));
			boxes.add(0, new HitBox(confirm, farm::confirmDialog));
		}
	}

	private static void confirmButton(Graphics2D g, Rectangle r, String label, boolean hover)
	{
		g.setColor(hover ? BUY_HOVER : BUY);
		g.fill(r);
		g.setColor(PANEL_EDGE);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		buttonLabel(g, r, label, TEXT);
	}
}

package com.eggscape;

import static com.eggscape.Layout.FIELD;
import static com.eggscape.Layout.NEST;
import static com.eggscape.Layout.PET;
import static com.eggscape.Layout.WIDTH;
import static com.eggscape.Layout.slotRect;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.blend;
import static com.eggscape.Ui.centered;
import static com.eggscape.Ui.outlined;
import static com.eggscape.Ui.sparkles;
import static com.eggscape.Ui.text;
import static com.eggscape.Ui.withAlpha;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.Iterator;
import java.util.Random;
import java.util.function.IntFunction;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * Short-lived feedback drawn over the panel: level-up fireworks, trophies, floating "+5" texts and XP drops.
 */
@Singleton
class Effects extends PanelPart
{
	private static final long POPUP_MS = 1300;
	private static final long XP_DROP_MS = 2200;
	private static final Color[] FIREWORK = {
		new Color(255, 230, 80), new Color(255, 120, 60), new Color(255, 90, 180), new Color(110, 220, 255), new Color(140, 255, 120)
	};

	@Inject
	Effects(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	/**
	 * Level-up or a new trophy, over the field. Level-ups win when both happen at once.
	 */
	void renderCelebration(Graphics2D g)
	{
		if (farm.isPrestigeVisible())
		{
			renderPrestige(g);
		}
		else if (farm.isLevelUpVisible())
		{
			renderLevelUp(g);
		}
		else if (farm.isTrophyVisible())
		{
			renderTrophy(g);
		}
	}

	private void renderLevelUp(Graphics2D g)
	{
		long age = farm.levelUpAgeMillis();
		int level = farm.getLevelUpLevel();
		Shape oldClip = g.getClip();
		g.clip(FIELD);
		g.setColor(new Color(0, 0, 0, 150));
		g.fill(FIELD);

		// Fireworks: a few bursts at fixed spots per level
		for (int b = 0; b < 5; b++)
		{
			long local = age - b * 350L;
			if (local < 0)
			{
				continue;
			}
			local %= 1400;
			Random seeded = new Random(level * 31L + b);
			int cx = FIELD.x + 20 + seeded.nextInt(FIELD.width - 40);
			int cy = FIELD.y + 12 + seeded.nextInt(FIELD.height - 24);
			double t = local / 1400.0;
			int radius = (int) (4 + t * 20);
			g.setColor(withAlpha(FIREWORK[b % FIREWORK.length], (float) (1 - t)));
			for (int j = 0; j < 10; j++)
			{
				double a = j * Math.PI / 5;
				g.fillRect(cx + (int) (Math.cos(a) * radius), cy + (int) (Math.sin(a) * radius + t * 6), 2, 2);
			}
		}

		g.setFont(FontManager.getRunescapeBoldFont());
		centered(g, "Level up!", FIELD.y + FIELD.height / 2 - 2, YELLOW);
		g.setFont(FontManager.getRunescapeSmallFont());
		centered(g, "Farm level " + level + "   +" + farm.getLevelUpReward() + " eggs", FIELD.y + FIELD.height / 2 + 12, TEXT);
		g.setClip(oldClip);
	}

	/**
	 * Selling the farm: Golden Feathers drift down over the field.
	 */
	private void renderPrestige(Graphics2D g)
	{
		long age = farm.prestigeAgeMillis();
		Shape oldClip = g.getClip();
		g.clip(FIELD);
		g.setColor(new Color(0, 0, 0, 205));
		g.fill(FIELD);

		BufferedImage feather = sprites.feather();
		for (int i = 0; i < 14; i++)
		{
			Random seeded = new Random(i * 97L);
			int x = FIELD.x + seeded.nextInt(FIELD.width - feather.getWidth());
			int speed = 18 + seeded.nextInt(14);
			// Each feather starts above the field at its own time and sways as it falls
			int y = FIELD.y - feather.getHeight() + (int) ((age * speed / 1000 + seeded.nextInt(FIELD.height + 20)) % (FIELD.height + 20)) - 10;
			int sway = (int) (Math.sin(age / 300.0 + i) * 4);
			g.drawImage(feather, x + sway, y, null);
		}
		sparkles(g, FIELD.x + FIELD.width / 2, FIELD.y + 18, 40, 3);

		int gain = farm.getPrestigeGain();
		g.setFont(FontManager.getRunescapeBoldFont());
		centered(g, "Farm sold!", FIELD.y + 22, YELLOW);
		g.setFont(FontManager.getRunescapeSmallFont());
		centered(g, "+" + gain + " Golden Feather" + (gain == 1 ? "" : "s"), FIELD.y + 37, TEXT);
		centered(g, "Everything 2x as fast for 1 hour", FIELD.y + 50, TEXT);
		FarmTheme theme = farm.getPrestigeTheme();
		if (theme != null)
		{
			centered(g, "New look: " + theme.getDisplayName(), FIELD.y + 63, TEXT_DIM);
		}
		g.setClip(oldClip);
	}

	/**
	 * A new achievement tier: the trophy rises into view with its metal's glow.
	 */
	private void renderTrophy(Graphics2D g)
	{
		AchievementTier tier = farm.getTrophyTier();
		long age = farm.trophyAgeMillis();
		Shape oldClip = g.getClip();
		g.clip(FIELD);
		g.setColor(new Color(0, 0, 0, 160));
		g.fill(FIELD);

		BufferedImage trophy = sprites.bigTrophy(tier);
		int rise = (int) Math.max(0, 14 - age / 25);
		int tx = FIELD.x + 12;
		int ty = FIELD.y + (FIELD.height - trophy.getHeight()) / 2 + rise;
		float pulse = (float) (0.35 + 0.2 * Math.sin(age / 180.0));
		g.setColor(withAlpha(tier.getColor(), pulse));
		g.fillOval(tx - 10, ty - 4, trophy.getWidth() + 20, trophy.getHeight() + 8);
		g.drawImage(trophy, tx, ty, null);
		sparkles(g, tx + trophy.getWidth() / 2, ty + trophy.getHeight() / 2, 20, tier.ordinal());

		int textX = tx + trophy.getWidth() + 14;
		g.setFont(FontManager.getRunescapeBoldFont());
		outlined(g, tier.getDisplayName() + " trophy!", textX, FIELD.y + 26, blend(tier.getColor(), Color.WHITE, 0.35f));
		g.setFont(FontManager.getRunescapeSmallFont());
		text(g, farm.getTrophyTrack().getDisplayName(), textX, FIELD.y + 42, TEXT);
		text(g, farm.getTrophyTrack().describeShort(tier), textX, FIELD.y + 54, TEXT_DIM);
		text(g, "+" + tier.getRewardEggs() + " eggs", textX, FIELD.y + 66, YELLOW);
		g.setClip(oldClip);
	}

	/**
	 * Floating "+5" texts. They are always aged and cleaned up, but only drawn when the panel is open.
	 *
	 * @param eggCell where an egg type's cell is in the egg bar (null if that egg isn't shown)
	 * @param onFarmTab whether field, nest and incubator popups have something to sit on
	 */
	void renderPopups(Graphics2D g, boolean draw, boolean onFarmTab, IntFunction<Rectangle> eggCell)
	{
		long now = System.currentTimeMillis();
		Iterator<FarmManager.Popup> it = farm.getPopups().iterator();
		Composite old = g.getComposite();
		while (it.hasNext())
		{
			FarmManager.Popup p = it.next();
			long age = now - p.start;
			if (age > POPUP_MS)
			{
				it.remove();
				continue;
			}
			Point at = draw ? anchor(p, onFarmTab, eggCell) : null;
			if (at == null)
			{
				continue;
			}
			float t = age / (float) POPUP_MS;

			if (p.anchor == FarmManager.Anchor.SLOT && age < 500)
			{
				// Shell pieces flying out of a hatched egg
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1 - age / 500f));
				g.setColor(new Color(240, 225, 195));
				for (int k = 0; k < 6; k++)
				{
					double a = k * Math.PI / 3 + 0.4;
					int d = (int) (age / 500.0 * 16);
					g.fillRect(at.x + (int) (Math.cos(a) * d), at.y + 8 + (int) (Math.sin(a) * d), 3, 3);
				}
			}

			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, 1 - t * t)));
			g.setFont(FontManager.getRunescapeBoldFont());
			int w = g.getFontMetrics().stringWidth(p.text);
			int y = at.y - (int) (t * 16);
			text(g, p.text, Math.max(2, Math.min(WIDTH - w - 2, at.x - w / 2)), y, p.color);
		}
		g.setComposite(old);
	}

	private static Point anchor(FarmManager.Popup p, boolean onFarmTab, IntFunction<Rectangle> eggCell)
	{
		switch (p.anchor)
		{
			case EGG_BAR:
			{
				Rectangle cell = eggCell.apply(p.index);
				return cell == null ? null : new Point(cell.x + cell.width - 12, cell.y + 14);
			}
			case FIELD:
				return onFarmTab ? new Point(FIELD.x + FIELD.width / 2 - 20, FIELD.y + FIELD.height / 2) : null;
			case NEST:
				return onFarmTab ? new Point(NEST.x + NEST.width / 2, NEST.y - 4) : null;
			case PET:
				return onFarmTab ? new Point(PET.x + PET.width / 2, PET.y - 2) : null;
			case SLOT:
			{
				if (!onFarmTab)
				{
					return null;
				}
				Rectangle slot = slotRect(p.index);
				return new Point(slot.x + slot.width / 2, slot.y + 10);
			}
			default:
				return null;
		}
	}

	/**
	 * OSRS style XP drops: a small egg icon and a white number that float up out of the panel, above the level.
	 *
	 * @param baseY y of the panel's top edge
	 */
	void renderXpDrops(Graphics2D g, int baseY)
	{
		long now = System.currentTimeMillis();
		Iterator<FarmManager.XpDrop> it = farm.getXpDrops().iterator();
		g.setFont(FontManager.getRunescapeSmallFont());
		Composite old = g.getComposite();
		while (it.hasNext())
		{
			FarmManager.XpDrop drop = it.next();
			long age = now - drop.start;
			if (age > XP_DROP_MS)
			{
				it.remove();
				continue;
			}
			float t = age / (float) XP_DROP_MS;
			// Fade in, rise steadily above the panel, fade out over the last third
			float alpha = t < 0.08f ? t / 0.08f : t < 0.66f ? 1f : Math.max(0, 1 - (t - 0.66f) / 0.34f);
			int y = baseY - 3 - (int) (t * 24);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			g.drawImage(sprites.smallEgg(EggType.PLAIN), 6, y - 10, 8, 11, null);
			text(g, "+" + QuantityFormatter.formatNumber(drop.amount), 17, y, TEXT);
		}
		g.setComposite(old);
	}
}

package com.eggscape;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Saved by ordinal, so only ever add new eggs at the end.
 */
@Getter
@RequiredArgsConstructor
public enum EggType
{
	PLAIN("Egg", 5 * 60, "egg_plain.png", new Color(0xE0A46A), HenType.BROWN),
	GREEN("Green egg", 15 * 60, "egg_green.png", new Color(0x7FD07A), HenType.CREAM),
	BLUE("Blue egg", 45 * 60, "egg_blue.png", new Color(0x8C8CE8), HenType.DARK),
	RED("Red egg", 2 * 60 * 60, "egg_red.png", new Color(0xFF4A3A), HenType.GOLDEN),
	// Super rare: only found while playing, from golden eggs, Easter baskets and bonus chests
	EASTER("Easter egg", 4 * 60 * 60, "egg_easter.png", new Color(0xFF8AD8), HenType.EASTER),
	// Dropped by Undead chickens in game and by the night-time farm event
	CURSED("Cursed egg", 60 * 60, "egg_cursed.png", new Color(0x9A7FC0), HenType.UNDEAD);

	/**
	 * Eggs as shown to the player: most common first. (The enum order is the save order and can't change.)
	 */
	private static final EggType[] DISPLAY_ORDER = {PLAIN, GREEN, BLUE, RED, CURSED, EASTER};

	private final String displayName;
	/**
	 * Base hatch time in seconds of logged-in play, before Heat lamp upgrades.
	 */
	private final int hatchSeconds;
	private final String sprite;
	private final Color color;
	/**
	 * The hen this egg hatches into (with a small chance of a better one).
	 */
	private final HenType hen;

	static EggType[] inDisplayOrder()
	{
		return DISPLAY_ORDER.clone();
	}

	/**
	 * Position of this egg in {@link #inDisplayOrder()}.
	 */
	int displayIndex()
	{
		for (int i = 0; i < DISPLAY_ORDER.length; i++)
		{
			if (DISPLAY_ORDER[i] == this)
			{
				return i;
			}
		}
		return ordinal();
	}
}

