package com.eggscape;

import static com.eggscape.Layout.HEIGHT;
import static com.eggscape.Layout.WIDTH;
import static com.eggscape.Ui.BUTTON;
import static com.eggscape.Ui.BUTTON_ACTIVE;
import static com.eggscape.Ui.BUTTON_HOVER;
import static com.eggscape.Ui.INSET;
import static com.eggscape.Ui.PANEL_EDGE;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.TITLE;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.baselineCentredOn;
import static com.eggscape.Ui.blend;
import static com.eggscape.Ui.blink;
import static com.eggscape.Ui.button;
import static com.eggscape.Ui.compact;
import static com.eggscape.Ui.dot;
import static com.eggscape.Ui.panel;
import static com.eggscape.Ui.sparkles;
import static com.eggscape.Ui.text;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.QuantityFormatter;

/**
 * The farm panel drawn over the game view (bottom right, above the inventory). This class is the frame:
 * header, egg bar, tabs and mouse input; each tab draws itself.
 */
class EggscapeOverlay extends Overlay
{
	private static final int COLLAPSED_WIDTH = 116;
	private static final int COLLAPSED_HEIGHT = 22;
	/**
	 * Breathing room above the header; everything inside the panel is drawn shifted down by this.
	 */
	private static final int TOP_PAD = 3;
	/**
	 * Room between the XP bar and the egg bar.
	 */
	private static final int CONTENT_SHIFT = 5;
	private static final int FULL_HEIGHT = HEIGHT + TOP_PAD + CONTENT_SHIFT;
	/**
	 * The egg bar always has room for every egg type, so cells keep their size as new eggs show up.
	 */
	private static final int EGG_CELLS = EggType.values().length;

	private final Client client;
	private final ClientThread clientThread;
	private final FarmManager farm;
	private final EggscapeConfig config;
	private final TooltipManager tooltipManager;
	private final Sprites sprites;
	private final FarmView farmView;
	private final ShopTab shopTab;
	private final TasksTab tasksTab;
	private final LogTab logTab;
	private final GoalsTab goalsTab;
	private final Effects effects;
	private final DialogView dialogView;

	private Tab tab = Tab.FARM;
	/**
	 * What the player could buy the last time the Shop was open; the Shop tab only gets a red dot for something new.
	 */
	private Set<String> shopSeen = new HashSet<>();
	private volatile List<HitBox> hitBoxes = Collections.emptyList();
	private volatile long lastRenderMillis;
	private volatile Rectangle activeArea = new Rectangle();

	@RequiredArgsConstructor
	enum Tab
	{
		FARM("Farm"),
		SHOP("Shop"),
		TASKS("Daily tasks"),
		LOG("Collection log"),
		GOALS("Achievements");

		private final String title;
	}

	@Inject
	EggscapeOverlay(Client client, ClientThread clientThread, FarmManager farm, EggscapeConfig config,
		TooltipManager tooltipManager, Sprites sprites, FarmView farmView, ShopTab shopTab, TasksTab tasksTab,
		LogTab logTab, GoalsTab goalsTab, Effects effects, DialogView dialogView)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.farm = farm;
		this.config = config;
		this.tooltipManager = tooltipManager;
		this.sprites = sprites;
		this.farmView = farmView;
		this.shopTab = shopTab;
		this.tasksTab = tasksTab;
		this.logTab = logTab;
		this.goalsTab = goalsTab;
		this.effects = effects;
		this.dialogView = dialogView;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);

		farmView.setOpenShop(() ->
		{
			if (farm.isTabUnlocked(Tab.SHOP))
			{
				openTab(Tab.SHOP);
				shopTab.showUpgrades();
			}
		});
	}

	// ---------------------------------------------------------------- mouse input (AWT thread)

	/**
	 * @return true when the click landed on the farm and must not reach the game
	 */
	boolean handleClick(MouseEvent e, boolean perform)
	{
		if (e.getButton() != MouseEvent.BUTTON1 || e.isAltDown())
		{
			// Alt + drag is RuneLite's way of moving overlays
			return false;
		}
		if (System.currentTimeMillis() - lastRenderMillis > 250)
		{
			return false;
		}
		Rectangle bounds = getBounds();
		if (bounds == null)
		{
			return false;
		}
		// Only the drawn part counts: when minimised, the rest of the overlay is see-through and click-through
		Point p = new Point(e.getX() - bounds.x, e.getY() - bounds.y);
		if (!activeArea.contains(p))
		{
			return false;
		}
		if (perform)
		{
			for (HitBox box : hitBoxes)
			{
				if (box.bounds.contains(p))
				{
					clientThread.invokeLater(box.action);
					break;
				}
			}
		}
		return true;
	}

	// ---------------------------------------------------------------- rendering (client thread)

	@Override
	public Dimension render(Graphics2D g)
	{
		FarmState state = farm.getState();
		if (!config.showOverlay() || state == null)
		{
			hitBoxes = Collections.emptyList();
			return null;
		}
		lastRenderMillis = System.currentTimeMillis();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		// Keeps a running challenge's clock going on every tab
		farm.updateChallenge();
		if (!farm.isTabUnlocked(tab))
		{
			tab = Tab.FARM;
		}

		List<HitBox> boxes = new ArrayList<>();
		Point mouse = relativeMouse();
		// The overlay always keeps its full size so it stays anchored: minimising shrinks it
		// into the bottom-right corner instead of jumping to the top-left.
		int ox = state.collapsed ? WIDTH - COLLAPSED_WIDTH : 0;
		int oy = state.collapsed ? FULL_HEIGHT - COLLAPSED_HEIGHT : TOP_PAD;
		if (!state.collapsed)
		{
			panel(g, new Rectangle(0, 0, WIDTH, FULL_HEIGHT));
		}
		Graphics2D inner = (Graphics2D) g.create();
		inner.translate(ox, oy);
		Point innerMouse = new Point(mouse.x - ox, mouse.y - oy);
		if (state.collapsed)
		{
			renderCollapsed(inner, state, innerMouse, boxes);
			activeArea = new Rectangle(ox, oy, COLLAPSED_WIDTH, COLLAPSED_HEIGHT);
		}
		else
		{
			renderFull(inner, state, innerMouse, boxes);
			activeArea = new Rectangle(0, 0, WIDTH, FULL_HEIGHT);
		}
		inner.dispose();

		List<HitBox> shifted = new ArrayList<>(boxes.size());
		for (HitBox box : boxes)
		{
			shifted.add(box.moved(ox, oy));
		}
		hitBoxes = shifted;
		return new Dimension(WIDTH, FULL_HEIGHT);
	}

	private Point relativeMouse()
	{
		net.runelite.api.Point m = client.getMouseCanvasPosition();
		Rectangle b = getBounds();
		if (m == null || b == null)
		{
			return new Point(-1, -1);
		}
		return new Point(m.getX() - b.x, m.getY() - b.y);
	}

	private void renderCollapsed(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		Rectangle all = new Rectangle(0, 0, COLLAPSED_WIDTH, COLLAPSED_HEIGHT);
		panel(g, all);
		g.setFont(FontManager.getRunescapeSmallFont());
		g.drawImage(sprites.smallEgg(EggType.PLAIN), 5, 4, null);
		text(g, QuantityFormatter.quantityToStackSize(s.eggs[EggType.PLAIN.ordinal()]), 19, 15, TEXT);
		g.drawImage(sprites.smallHen(), 52, 3, null);
		text(g, String.valueOf(farm.henCount()), 67, 15, TEXT);
		boolean attention = farm.needsAttention();
		if (attention)
		{
			if (blink())
			{
				text(g, "!", 88, 15, new Color(255, 80, 60));
			}
		}
		else if (farm.nestCount() >= farm.nestCapacity())
		{
			text(g, "!", 88, 15, YELLOW);
		}
		button(g, new Rectangle(COLLAPSED_WIDTH - 20, 4, 16, 14), "+", false, all.contains(mouse), true);

		boxes.add(new HitBox(all, () ->
		{
			farm.setCollapsed(false);
			if (farm.getActiveEvent() != null)
			{
				tab = Tab.FARM;
			}
		}));
		if (all.contains(mouse))
		{
			FarmVisitors.ActiveEvent event = farm.getActiveEvent();
			tooltip(event != null ? event.type.getDisplayName() + "!" : "Open your farm");
		}
		// Popups still age while minimised, they just aren't drawn
		effects.renderPopups(g, false, false, i -> null);
	}

	private void renderFull(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		renderHeader(g, s, mouse, boxes);
		effects.renderXpDrops(g, -TOP_PAD);

		// Everything under the header is drawn a little lower, leaving room under the XP bar
		Graphics2D content = (Graphics2D) g.create();
		content.translate(0, CONTENT_SHIFT);
		List<HitBox> contentBoxes = new ArrayList<>();
		renderContent(content, s, new Point(mouse.x, mouse.y - CONTENT_SHIFT), contentBoxes);
		content.dispose();
		// Content (dialogs, events) goes first, in its own order, so it wins over the header
		List<HitBox> merged = new ArrayList<>();
		for (HitBox box : contentBoxes)
		{
			merged.add(box.moved(0, CONTENT_SHIFT));
		}
		merged.addAll(boxes);
		boxes.clear();
		boxes.addAll(merged);
	}

	private void renderContent(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		if (farm.takeShowFarm())
		{
			tab = Tab.FARM;
		}
		List<EggType> eggs = shownEggs(s);
		renderEggBar(g, s, eggs, mouse, boxes);
		switch (tab)
		{
			case FARM:
				farmView.render(g, s, mouse, boxes);
				break;
			case SHOP:
				shopTab.render(g, s, mouse, boxes);
				break;
			case TASKS:
				tasksTab.render(g, s, mouse, boxes);
				break;
			case LOG:
				logTab.render(g, s, mouse, boxes);
				break;
			case GOALS:
				goalsTab.render(g, mouse, boxes);
				break;
		}
		effects.renderCelebration(g);
		effects.renderPopups(g, true, tab == Tab.FARM, ordinal ->
		{
			int index = eggs.indexOf(EggType.values()[ordinal]);
			return index < 0 ? null : Layout.eggCell(index, EGG_CELLS);
		});
		FarmManager.Dialog dialog = farm.currentDialog();
		if (dialog != null)
		{
			dialogView.render(g, dialog, mouse, boxes);
		}
	}

	// ---------------------------------------------------------------- header

	private void renderHeader(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		int level = farm.farmLevel();
		g.setFont(FontManager.getRunescapeBoldFont());
		// Vertically centred on the tab buttons (y 4, height 15)
		FontMetrics bold = g.getFontMetrics();
		int baseline = 4 + (15 + bold.getAscent() - bold.getDescent()) / 2;
		text(g, "Lv " + level, 6, baseline, TITLE);

		// Golden Feather and prestige count next to the level, once the farm has been sold
		if (s.prestiges > 0)
		{
			int fx = 6 + bold.stringWidth("Lv " + level) + 5;
			g.drawImage(sprites.feather(), fx, 5, null);
			text(g, String.valueOf(s.prestiges), fx + 11, baseline, YELLOW);
			Rectangle prestige = new Rectangle(fx - 1, 3, 11 + bold.stringWidth(String.valueOf(s.prestiges)) + 2, 17);
			if (prestige.contains(mouse))
			{
				tooltip("Farms sold: " + s.prestiges + "</br>Golden Feathers earned: " + s.feathersEarned
					+ "</br>Hens lay +" + s.feathersEarned * 10 + "% forever");
			}
		}

		// Progress to the next farm level, edge to edge; it lights up on XP gains
		Rectangle bar = new Rectangle(5, 22, WIDTH - 10, 3);
		long base = farm.xpForLevel(level);
		long next = farm.xpForLevel(level + 1);
		double pct = level >= 99 || next <= base ? 1 : (s.farmXp - base) / (double) (next - base);
		long sinceXp = System.currentTimeMillis() - farm.getLastXpMillis();
		float flash = sinceXp < 600 ? 1 - sinceXp / 600f : 0;
		g.setColor(PANEL_EDGE);
		g.drawRect(bar.x - 1, bar.y - 1, bar.width + 1, bar.height + 1);
		g.setColor(new Color(20, 16, 12));
		g.fill(bar);
		int filled = (int) (bar.width * Math.max(0, Math.min(1, pct)));
		g.setColor(blend(new Color(40, 120, 170), Color.WHITE, flash));
		g.fillRect(bar.x, bar.y, filled, bar.height);
		g.setColor(blend(FarmManager.XP_COLOR, Color.WHITE, flash));
		g.fillRect(bar.x, bar.y, filled, 1);

		Rectangle badge = new Rectangle(2, 2, bold.stringWidth("Lv " + level) + 8, 19);
		if (badge.contains(mouse) || new Rectangle(bar.x, bar.y - 1, bar.width, bar.height + 2).contains(mouse))
		{
			long rate = farm.xpPerHour();
			int unlock = farm.nextUnlockLevel();
			tooltip("Farm level " + level
				+ (level < 99 ? "</br>" + QuantityFormatter.formatNumber(Math.max(0, next - s.farmXp)) + " xp to level " + (level + 1) : "")
				+ (rate > 0 ? "</br>" + QuantityFormatter.formatNumber(rate) + " xp/hour" : "")
				+ (unlock > 0 ? "</br>Level " + unlock + ": " + FarmManager.unlockName(unlock) : ""));
		}

		// Tabs appear one by one as they unlock; with only the farm there are no tabs at all
		List<Tab> tabs = new ArrayList<>();
		for (Tab t : Tab.values())
		{
			if (farm.isTabUnlocked(t))
			{
				tabs.add(t);
			}
		}
		if (tabs.size() > 1)
		{
			int x = WIDTH - 22 - tabs.size() * 24;
			for (Tab t : tabs)
			{
				renderTab(g, new Rectangle(x, 4, 22, 15), t, mouse, boxes);
				x += 24;
			}
		}
		Rectangle minimise = new Rectangle(WIDTH - 20, 4, 16, 15);
		button(g, minimise, "-", false, minimise.contains(mouse), true);
		boxes.add(new HitBox(minimise, () -> farm.setCollapsed(true)));
	}

	private void renderTab(Graphics2D g, Rectangle r, Tab t, Point mouse, List<HitBox> boxes)
	{
		boolean active = tab == t;
		boolean fresh = !farm.isTabSeen(t.name());
		g.setColor(active ? BUTTON_ACTIVE : r.contains(mouse) ? BUTTON_HOVER : BUTTON);
		g.fill(r);
		g.setColor(fresh && blink() ? YELLOW : PANEL_EDGE);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		tabIcon(g, t, r.x + r.width / 2, r.y + r.height / 2);

		// Red dot: something to claim, or something new to buy; a blinking yellow frame: this tab is new
		boolean eventWaiting = t == Tab.FARM && tab != Tab.FARM && farm.getActiveEvent() != null;
		boolean newInShop = false;
		if (t == Tab.SHOP)
		{
			Set<String> affordable = farm.affordable();
			if (tab == Tab.SHOP)
			{
				shopSeen = affordable;
			}
			newInShop = !shopSeen.containsAll(affordable);
		}
		if (newInShop || (t == Tab.TASKS && farm.hasClaimableTask()) || (eventWaiting && blink()))
		{
			dot(g, r);
		}
		boxes.add(new HitBox(r, () -> openTab(t)));
		if (r.contains(mouse))
		{
			tooltip(t.title);
		}
	}

	private void openTab(Tab t)
	{
		tab = t;
		farm.markTabSeen(t.name());
	}

	/**
	 * Small pictures instead of words on the tabs, centred on cx, cy.
	 */
	private void tabIcon(Graphics2D g, Tab t, int cx, int cy)
	{
		BufferedImage icon = sprites.tabIcon(t);
		g.drawImage(icon, cx - icon.getWidth() / 2, cy - icon.getHeight() / 2, null);
	}

	// ---------------------------------------------------------------- egg bar

	/**
	 * Only eggs you have ever had are shown, most common first; new players just see the plain egg.
	 */
	private static List<EggType> shownEggs(FarmState s)
	{
		List<EggType> eggs = new ArrayList<>();
		for (EggType egg : EggType.inDisplayOrder())
		{
			if (egg == EggType.PLAIN || s.eggs[egg.ordinal()] > 0 || s.eggsObtained[egg.ordinal()] > 0)
			{
				eggs.add(egg);
			}
		}
		return eggs;
	}

	private void renderEggBar(Graphics2D g, FarmState s, List<EggType> eggs, Point mouse, List<HitBox> boxes)
	{
		for (int i = 0; i < eggs.size(); i++)
		{
			EggType egg = eggs.get(i);
			Rectangle cell = Layout.eggCell(i, EGG_CELLS);
			boolean selected = s.selectedEgg == egg.ordinal();
			boolean hover = cell.contains(mouse);
			g.setColor(hover ? BUTTON_HOVER : INSET);
			g.fill(cell);
			// Only show which egg is selected once there is a choice
			g.setColor(selected && eggs.size() > 1 ? YELLOW : PANEL_EDGE);
			g.drawRect(cell.x, cell.y, cell.width - 1, cell.height - 1);
			BufferedImage eggImg = sprites.smallEgg(egg);
			int eggY = cell.y + (cell.height - eggImg.getHeight()) / 2;
			g.drawImage(eggImg, cell.x + 2, eggY, null);
			// Count centred on the egg's middle, using the digits' real height
			g.setFont(FontManager.getRunescapeSmallFont());
			String count = compact(s.eggs[egg.ordinal()]);
			if (g.getFontMetrics().stringWidth(count) > cell.width - 17)
			{
				count = Ui.compactShort(s.eggs[egg.ordinal()]);
			}
			text(g, count, cell.x + 15, baselineCentredOn(g, count, eggY + eggImg.getHeight() / 2.0),
				s.eggs[egg.ordinal()] > 0 ? TEXT : TEXT_DIM);
			if (egg == EggType.EASTER && s.eggs[egg.ordinal()] > 0)
			{
				sparkles(g, cell.x + 8, cell.y + 9, 7, 0);
			}

			boxes.add(new HitBox(cell, () -> farm.selectEgg(egg)));
			if (hover)
			{
				tooltip(egg.getDisplayName() + "</br>Hatches into a " + egg.getHen().getDisplayName()
					+ " (" + FarmManager.formatDuration((long) Math.ceil(egg.getHatchSeconds() / farm.hatchSpeedMultiplier())) + ")");
			}
		}
	}

	private void tooltip(String text)
	{
		tooltipManager.add(new Tooltip(text));
	}
}

package com.eggscape;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.awt.event.MouseEvent;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Named;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.CommandExecuted;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Skill;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ClientShutdown;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Eggscape",
	description = "An idle chicken farm: find eggs while you play, hatch them and grow your flock",
	tags = {"idle", "chicken", "egg", "farm", "minigame", "game"}
)
public class EggscapePlugin extends Plugin
{
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private MouseManager mouseManager;
	@Inject
	private EggscapeOverlay overlay;
	@Inject
	private FarmManager farm;
	@Inject
	@Named("developerMode")
	private boolean developerMode;

	/**
	 * Last known XP per skill. Empty after login so the initial stat burst doesn't count as gains.
	 */
	private final Map<Skill, Integer> lastXp = new EnumMap<>(Skill.class);

	/**
	 * Regular chickens: Lumbridge and elsewhere, Falador farm, Tutorial Island, Miscellania and Gordon and Mary's farm.
	 */
	private static final Set<Integer> CHICKEN_IDS = ImmutableSet.of(
		1173, 1174, 9488,
		2804, 2805, 2806,
		3316,
		3661, 3662,
		10494, 10495, 10496, 10497
	);

	/**
	 * NPCs the local player has hit, so their deaths count as our kills.
	 */
	private final Set<NPC> damagedNpcs = new HashSet<>();

	private final MouseAdapter mouseListener = new MouseAdapter()
	{
		@Override
		public MouseEvent mousePressed(MouseEvent e)
		{
			if (overlay.handleClick(e, true))
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseReleased(MouseEvent e)
		{
			if (overlay.handleClick(e, false))
			{
				e.consume();
			}
			return e;
		}

		@Override
		public MouseEvent mouseClicked(MouseEvent e)
		{
			if (overlay.handleClick(e, false))
			{
				e.consume();
			}
			return e;
		}
	};

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		mouseManager.registerMouseListener(mouseListener);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				farm.load();
				farm.requestOfflineCatchUp();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		mouseManager.unregisterMouseListener(mouseListener);
		clientThread.invoke(() ->
		{
			farm.save();
			farm.unload();
		});
		lastXp.clear();
		damagedNpcs.clear();
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGED_IN:
				farm.load();
				farm.requestOfflineCatchUp();
				break;
			case LOGIN_SCREEN:
				farm.clearEvent();
				farm.save();
				lastXp.clear();
				damagedNpcs.clear();
				break;
			case HOPPING:
			case LOGGING_IN:
				lastXp.clear();
				damagedNpcs.clear();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Switching accounts: the previous farm was saved a few ticks ago, so just swap it out
		farm.unload();
		farm.load();
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		farm.save();
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		farm.onGameTick();
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer previous = lastXp.put(event.getSkill(), event.getXp());
		if (previous != null && event.getXp() > previous)
		{
			farm.onXpGained(event.getXp() - previous);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		// Remember every NPC we damaged; by the time it dies its interaction target is already reset
		if (event.getActor() instanceof NPC && event.getHitsplat().isMine())
		{
			damagedNpcs.add((NPC) event.getActor());
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (event.getActor() instanceof NPC)
		{
			onNpcDied((NPC) event.getActor());
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc.isDead())
		{
			// Fallback for deaths where ActorDeath didn't fire
			onNpcDied(npc);
		}
		damagedNpcs.remove(npc);
	}

	private void onNpcDied(NPC npc)
	{
		// remove() makes sure a kill is only counted once
		if (damagedNpcs.remove(npc))
		{
			farm.onNpcKilled(kindOf(npc));
		}
	}

	private static FarmManager.NpcKind kindOf(NPC npc)
	{
		String name = npc.getName();
		if (name != null && name.equalsIgnoreCase("Undead chicken"))
		{
			return FarmManager.NpcKind.UNDEAD_CHICKEN;
		}
		if (CHICKEN_IDS.contains(npc.getId()) || (name != null && name.equalsIgnoreCase("Chicken")))
		{
			return FarmManager.NpcKind.CHICKEN;
		}
		return FarmManager.NpcKind.OTHER;
	}

	/**
	 * Test commands, only in a developer-mode client (never in a normal RuneLite):
	 * ::eggscape event &lt;name&gt; starts a farm event (e.g. bunny, evil, golden), ::eggscape pet toggles the pet.
	 */
	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		if (!developerMode || !"eggscape".equalsIgnoreCase(event.getCommand()))
		{
			return;
		}
		String[] args = event.getArguments();
		if (args.length >= 1 && args[0].equalsIgnoreCase("pet"))
		{
			farm.debugTogglePet();
			return;
		}
		if (args.length >= 2 && args[0].equalsIgnoreCase("event"))
		{
			FarmEvent type = findEvent(args[1]);
			if (type != null)
			{
				farm.debugSpawnEvent(type);
				return;
			}
		}
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
			"Eggscape test commands: ::eggscape pet, ::eggscape event <bunny|evil|golden|basket|easter|rooster|undead>", null);
	}

	private static FarmEvent findEvent(String name)
	{
		String n = name.toLowerCase();
		for (FarmEvent type : FarmEvent.values())
		{
			// Matches on any part of the name, so "bunny", "evil" and "easter_bunny" all work
			if (type.name().toLowerCase().contains(n) || type.getDisplayName().toLowerCase().contains(n))
			{
				return type;
			}
		}
		return null;
	}

	@Provides
	EggscapeConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(EggscapeConfig.class);
	}
}

package com.eggscape;

import static com.eggscape.Layout.BUSHES;
import static com.eggscape.Layout.FIELD;
import static com.eggscape.Layout.NEST;
import static com.eggscape.Layout.minX;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.centeredAt;
import static com.eggscape.Ui.outlined;
import static com.eggscape.Ui.sparkles;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Visitors on the farm, including the two challenges (Easter Bunny hunt and Evil Chicken fight).
 */
@Singleton
class EventView extends PanelPart
{
	@Inject
	EventView(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	void render(Graphics2D g, Point mouse, List<HitBox> boxes)
	{
		farm.updateChallenge();
		FarmVisitors.ActiveEvent event = farm.getActiveEvent();
		if (event == null)
		{
			return;
		}
		if (event.hunt != null)
		{
			renderHunt(g, event, mouse, boxes);
			return;
		}

		long now = System.currentTimeMillis();
		boolean facingRight = event.x < 0.5f;
		BufferedImage img = sprite(event.type, facingRight);
		int w = img.getWidth();
		int h = img.getHeight();
		int x = Math.round(minX() + event.x * (NEST.x - w - 2 - minX()));
		int y = Math.round(FIELD.y + 4 + event.y * (FIELD.height - h - 8));
		Rectangle hit = new Rectangle(x - 2, y - 2, w + 4, h + 4);

		// Glow around the whole visitor so it stands out from the flock (the Evil Chicken looks a lot like a hen)
		float pulse = (float) (0.3 + 0.15 * Math.sin(now / 200.0));
		g.setColor(event.type == FarmEvent.EVIL_CHICKEN ? new Color(1f, 0.1f, 0.1f, pulse)
			: event.type == FarmEvent.UNDEAD_CHICKEN ? new Color(0.6f, 0.4f, 1f, pulse)
			: new Color(1f, 0.95f, 0.4f, pulse));
		g.fillOval(x - 5, y - 3, w + 10, h + 8);
		drawVisitor(g, event, img, x, y, now);

		// Visitors sit on top of the flock and nest, so they get clicked first
		boxes.add(0, new HitBox(hit, farm::clickEvent));

		if (event.isEngaged())
		{
			// The Evil Chicken fight: intro card first, then hits and time at the top
			if (event.inIntro(now))
			{
				renderIntroCard(g, "Evil Chicken attack!", "Hit it " + FarmVisitors.EVIL_CHICKEN_HP + " times in "
					+ FarmVisitors.EVIL_FIGHT_MS / 1000 + " seconds!", event.playStart() - now);
				return;
			}
			double left = 1 - (now - event.playStart()) / (double) FarmVisitors.EVIL_FIGHT_MS;
			int hits = FarmVisitors.EVIL_CHICKEN_HP - event.hp;
			renderChallengeHud(g, "Hits " + hits + "/" + FarmVisitors.EVIL_CHICKEN_HP, left);
			renderGo(g, now - event.playStart());
			return;
		}

		// Time left before the visitor leaves
		double left = event.ticksLeft / (double) Math.max(1, event.duration);
		g.setColor(new Color(0, 0, 0, 160));
		g.fillRect(x, y + h + 1, w, 3);
		g.setColor(left < 0.3 ? new Color(230, 60, 40) : YELLOW);
		g.fillRect(x, y + h + 1, (int) (w * left), 3);
		if (hit.contains(mouse))
		{
			tooltip(tooltipFor(event));
		}
	}

	private BufferedImage sprite(FarmEvent type, boolean facingRight)
	{
		switch (type)
		{
			case GOLDEN_EGG:
				return sprites.goldenEgg(true);
			case ROOSTER:
				return sprites.rooster(facingRight);
			case EVIL_CHICKEN:
				return sprites.evilChicken(facingRight);
			case EASTER_BASKET:
				return sprites.easterBasket();
			case UNDEAD_CHICKEN:
				return sprites.undeadChicken(facingRight);
			case EASTER_BUNNY:
				return sprites.bunny(facingRight);
			case EGG_BASKET:
			default:
				return sprites.basket();
		}
	}

	/**
	 * Each visitor has its own little animation.
	 */
	private void drawVisitor(Graphics2D g, FarmVisitors.ActiveEvent event, BufferedImage img, int x, int y, long now)
	{
		int w = img.getWidth();
		int h = img.getHeight();
		switch (event.type)
		{
			case GOLDEN_EGG:
				g.drawImage(img, x + (int) (Math.sin(now / 150.0) * 2), y, null);
				sparkles(g, x + w / 2, y + h / 2, 12, 0);
				break;
			case EGG_BASKET:
				// Eggs peeking out between the handle, then the basket in front of them
				for (int i = 0; i < 2; i++)
				{
					g.drawImage(sprites.smallEgg(EggType.PLAIN), x + 2 + i * 8, y + 8, null);
				}
				g.drawImage(img, x, y, null);
				break;
			case EASTER_BASKET:
				g.drawImage(img, x, y - ((now / 250) % 2 == 0 ? 0 : 1), null);
				sparkles(g, x + w / 2, y + h / 2, 14, 3);
				break;
			case ROOSTER:
				g.drawImage(img, x, y + ((now / 300) % 2 == 0 ? 0 : 1), null);
				break;
			case EASTER_BUNNY:
				// Little hops on the spot
				g.drawImage(img, x, y - (int) Math.abs(Math.sin(now / 160.0) * 3), null);
				break;
			case UNDEAD_CHICKEN:
			{
				// Ghostly: floats and flickers a little
				Composite old = g.getComposite();
				float ghost = (float) (0.75 + 0.2 * Math.sin(now / 180.0));
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, ghost));
				g.drawImage(img, x, y + (int) Math.round(Math.sin(now / 300.0) * 2), null);
				g.setComposite(old);
				break;
			}
			case EVIL_CHICKEN:
				g.drawImage(img, x + (int) (Math.sin(now / 40.0) * 1.5), y, null);
				// Health pips
				for (int i = 0; i < event.hp; i++)
				{
					g.setColor(Color.BLACK);
					g.fillRect(x + 6 + i * 7, y - 5, 6, 4);
					g.setColor(new Color(220, 30, 30));
					g.fillRect(x + 7 + i * 7, y - 4, 4, 2);
				}
				break;
			default:
				g.drawImage(img, x, y, null);
				break;
		}
	}

	private static String tooltipFor(FarmVisitors.ActiveEvent event)
	{
		switch (event.type)
		{
			case GOLDEN_EGG:
				return "Golden egg</br>Click to crack it open!";
			case EGG_BASKET:
				return "Egg basket</br>Click to take the eggs";
			case ROOSTER:
				return "Wandering rooster</br>Click to say hello";
			case EVIL_CHICKEN:
				return "Evil Chicken</br>Click to fight it, or it steals eggs!";
			case EASTER_BASKET:
				return "Easter basket</br>Click to grab it!";
			case UNDEAD_CHICKEN:
				return "Undead chicken</br>Click to lay it to rest";
			case EASTER_BUNNY:
				return "Easter Bunny</br>Click to start the hunt!";
			default:
				return event.type.getDisplayName();
		}
	}

	// ---------------------------------------------------------------- Easter Bunny hunt

	/**
	 * The bunny pops out of one bush at a time; click it before it ducks away.
	 */
	private void renderHunt(Graphics2D g, FarmVisitors.ActiveEvent event, Point mouse, List<HitBox> boxes)
	{
		FarmVisitors.Hunt hunt = event.hunt;
		long now = System.currentTimeMillis();
		BufferedImage bunny = sprites.bunny(false);

		for (int i = 0; i < BUSHES.length; i++)
		{
			int bx = BUSHES[i][0];
			int by = BUSHES[i][1];
			Rectangle hit = new Rectangle(bx - 16, by - 54, 32, 56);

			if (hunt.peekBush == i)
			{
				// Pop up fast, stay a moment, duck back down
				double p = (now - hunt.peekStart) / (double) hunt.peekMs;
				double up = p < 0.2 ? p / 0.2 : p > 0.8 ? (1 - p) / 0.2 : 1;
				// Most of the bunny rises above the bush; its feet stay hidden behind it
				int shown = (int) (up * bunny.getHeight());
				Shape oldClip = g.getClip();
				g.clip(new Rectangle(bx - 20, FIELD.y, 40, by - 18 - FIELD.y));
				g.drawImage(sprites.bunny(i % 2 == 0), bx - bunny.getWidth() / 2, by - 18 - shown, null);
				g.setClip(oldClip);
			}
			drawBush(g, bx, by, hit.contains(mouse));
			final int bush = i;
			boxes.add(0, new HitBox(hit, () -> farm.clickBush(bush)));
		}

		if (event.inIntro(now))
		{
			renderIntroCard(g, "Easter Bunny Hunt!", "Catch it " + FarmVisitors.HUNT_CATCHES + " times in "
				+ FarmVisitors.HUNT_MS / 1000 + " seconds!", event.playStart() - now);
			return;
		}
		double left = 1 - (now - hunt.start) / (double) FarmVisitors.HUNT_MS;
		renderChallengeHud(g, "Bunny caught " + hunt.catches + "/" + FarmVisitors.HUNT_CATCHES, left);
		renderGo(g, now - event.playStart());
	}

	/**
	 * A bush standing with its bottom centre on x, y.
	 */
	private void drawBush(Graphics2D g, int x, int y, boolean hover)
	{
		BufferedImage bush = sprites.bush(hover);
		g.setColor(new Color(0, 0, 0, 50));
		g.fillOval(x - bush.getWidth() / 2, y - 4, bush.getWidth(), 7);
		g.drawImage(bush, x - bush.getWidth() / 2, y - bush.getHeight(), null);
	}

	// ---------------------------------------------------------------- challenge framing

	/**
	 * The "cutscene" before a challenge: title, what to do and a 3-2-1 countdown, centred on the field.
	 */
	private static void renderIntroCard(Graphics2D g, String title, String subtitle, long msLeft)
	{
		g.setColor(new Color(0, 0, 0, 165));
		g.fill(FIELD);
		int cx = FIELD.x + FIELD.width / 2;
		int cy = FIELD.y + FIELD.height / 2;
		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics bold = g.getFontMetrics();
		outlined(g, title, cx - bold.stringWidth(title) / 2, cy - 12, YELLOW);
		g.setFont(FontManager.getRunescapeSmallFont());
		centeredAt(g, subtitle, cx, cy + 2, TEXT);

		// Countdown number that shrinks a little as each second passes
		int count = (int) Math.ceil(msLeft / 1000.0);
		float within = (msLeft % 1000) / 1000f;
		Font big = FontManager.getRunescapeBoldFont().deriveFont(16f + 8f * within);
		g.setFont(big);
		String n = String.valueOf(Math.max(1, count));
		outlined(g, n, cx - g.getFontMetrics().stringWidth(n) / 2, cy + 28, TEXT);
	}

	/**
	 * Score and a time bar at the top of the field while a challenge runs.
	 */
	private static void renderChallengeHud(Graphics2D g, String label, double timeLeft)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		int w = Math.max(90, g.getFontMetrics().stringWidth(label) + 14);
		int x = FIELD.x + (FIELD.width - w) / 2;
		g.setColor(new Color(0, 0, 0, 170));
		g.fillRoundRect(x, FIELD.y + 1, w, 16, 6, 6);
		centeredAt(g, label, FIELD.x + FIELD.width / 2, FIELD.y + 11, YELLOW);
		g.setColor(new Color(40, 34, 26));
		g.fillRect(x + 4, FIELD.y + 13, w - 8, 2);
		g.setColor(timeLeft < 0.3 ? new Color(230, 60, 40) : new Color(120, 220, 90));
		g.fillRect(x + 4, FIELD.y + 13, (int) ((w - 8) * Math.max(0, Math.min(1, timeLeft))), 2);
	}

	/**
	 * A big "GO!" that fades out right after the countdown.
	 */
	private static void renderGo(Graphics2D g, long sinceStart)
	{
		if (sinceStart < 0 || sinceStart > 700)
		{
			return;
		}
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 1 - sinceStart / 700f));
		g.setFont(FontManager.getRunescapeBoldFont().deriveFont(24f));
		String go = "GO!";
		outlined(g, go, FIELD.x + (FIELD.width - g.getFontMetrics().stringWidth(go)) / 2, FIELD.y + FIELD.height / 2 + 8,
			new Color(120, 230, 90));
		g.setComposite(old);
	}
}

