package com.eggscape;

import java.util.Random;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Random events that visit the farm while you play. They need a click before they leave.
 */
@Getter
@RequiredArgsConstructor
public enum FarmEvent
{
	GOLDEN_EGG("Golden egg", 30, 75,
		"A golden egg rolled onto your farm! Click it before it rolls away."),
	EGG_BASKET("Egg basket", 30, 100,
		"A villager left a basket of eggs at your farm gate!"),
	ROOSTER("Wandering rooster", 20, 100,
		"A rooster is strutting around your farm. Say hello!"),
	EVIL_CHICKEN("Evil Chicken", 20, 80,
		"The Evil Chicken is raiding your nest box! Click it to chase it off."),
	EASTER_BASKET("Easter basket", 4, 80,
		"A rare Easter basket appeared on your farm! Grab it quick!"),
	// Only shows up at night (local time), see roll()
	UNDEAD_CHICKEN("Undead chicken", 18, 90,
		"An Undead chicken is haunting your farm! Click it to lay it to rest."),
	// A little minigame: catch the bunny as it pops out of the bushes
	EASTER_BUNNY("Easter Bunny", 7, 100,
		"The Easter Bunny is hiding on your farm! Click it to start the hunt.");

	private static final int NIGHT_START_HOUR = 22;
	private static final int NIGHT_END_HOUR = 6;

	private final String displayName;
	private final int weight;
	private final int durationTicks;
	private final String spawnMessage;

	static FarmEvent roll(Random random, int hourOfDay)
	{
		boolean night = hourOfDay >= NIGHT_START_HOUR || hourOfDay < NIGHT_END_HOUR;
		int total = 0;
		for (FarmEvent e : values())
		{
			total += e.canHappen(night) ? e.weight : 0;
		}
		int r = random.nextInt(total);
		for (FarmEvent e : values())
		{
			if (!e.canHappen(night))
			{
				continue;
			}
			r -= e.weight;
			if (r < 0)
			{
				return e;
			}
		}
		return GOLDEN_EGG;
	}

	private boolean canHappen(boolean night)
	{
		return this != UNDEAD_CHICKEN || night;
	}
}

