	// ---------------------------------------------------------------- persistence

	/**
	 * Loads the farm for the current RuneScape profile. No-op when that farm is already loaded.
	 */
	void load()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		if (state != null && key.equals(profileKey))
		{
			return;
		}

		FarmState loaded = null;
		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, STATE_KEY);
		if (json != null)
		{
			try
			{
				loaded = gson.fromJson(json, FarmState.class);
			}
			catch (JsonSyntaxException e)
			{
				log.warn("Unable to read Eggscape farm, starting a new one", e);
			}
		}

		boolean fresh = loaded == null;
		if (fresh)
		{
			loaded = FarmState.newFarm();
		}
		loaded.normalize();

		state = loaded;
		profileKey = key;
		offlinePending = !fresh;
		welcomePending = fresh;
		ticksSinceSave = 0;
		ticksSinceDayCheck = DAY_CHECK_TICKS;
		daily.reset();
		visitors.clear();
		dialogs.clear();
		popups.clear();
		xpDrops.clear();
		sessionXp = 0;
		sessionStartMillis = 0;

		if (!fresh && state.farmXp == 0)
		{
			grantRetroactiveXp();
		}
		else if (state.levelRewarded == 0)
		{
			// Saved before the Eggscape XP curve: rewards were given up to the old OSRS curve level.
			// The new curve is never steeper, so the next tick hands out any levels this jumps up.
			int xp = (int) Math.min(Integer.MAX_VALUE, state.farmXp);
			state.levelRewarded = Math.max(1, Math.min(MAX_LEVEL, Experience.getLevelForXp(xp)));
		}
	}

	/**
	 * Farms from before Farm levels existed get XP for what they already did.
	 */
	private void grantRetroactiveXp()
	{
		state.farmXp = state.hatchedTotal * 20 + state.eggsFound * FIND_XP
			+ eventsCompleted() * EVENT_XP + (long) state.achievements.size() * ACHIEVEMENT_XP;
		for (int level = 2; level <= farmLevel(); level++)
		{
			queueUnlock(level);
		}
		state.levelRewarded = farmLevel();
	}

	void save()
	{
		// Never write a farm into another account's profile after a profile switch
		if (state == null || profileKey == null || !profileKey.equals(configManager.getRSProfileKey()))
		{
			return;
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, STATE_KEY, gson.toJson(state));
	}

	void unload()
	{
		state = null;
		profileKey = null;
		visitors.clear();
		dialogs.clear();
		popups.clear();
		daily.reset();
	}

	/**
	 * Visitors leave when you log out; they are never saved.
	 */
	void clearEvent()
	{
		visitors.clear();
	}

	/**
	 * Called on login: time spent logged out is turned into (slower) progress on the next tick.
	 */
	void requestOfflineCatchUp()
	{
		if (state != null)
		{
			offlinePending = true;
		}
	}

	// ---------------------------------------------------------------- ticking

	void onGameTick()
	{
		if (state == null)
		{
			return;
		}

		if (welcomePending)
		{
			welcomePending = false;
			dialogs.add(new Dialog("Welcome to Eggscape!", Arrays.asList(
				"Play OSRS to find eggs.",
				"Click an incubator below to hatch one!"),
				"Let's go!", null, null));
		}
		if (offlinePending)
		{
			offlinePending = false;
			applyOfflineProgress();
		}

		advance(TICK_SECONDS, true);
		autoCollect(TICK_SECONDS);
		state.lastSeen = System.currentTimeMillis();
		if (state.blessingTicks > 0)
		{
			state.blessingTicks--;
		}
		if (state.freshStartTicks > 0)
		{
			state.freshStartTicks--;
		}
		visitors.tick(state);
		checkLevelUps();
		if (++ticksSinceDayCheck >= DAY_CHECK_TICKS)
		{
			ticksSinceDayCheck = 0;
			daily.checkNewDay(state);
		}
		checkAchievements();

		if (++ticksSinceSave >= SAVE_EVERY_TICKS)
		{
			ticksSinceSave = 0;
			save();
		}
	}

	private void applyOfflineProgress()
	{
		long now = System.currentTimeMillis();
		long elapsed = now - state.lastSeen;
		state.lastSeen = now;
		if (elapsed < OFFLINE_MIN_MS)
		{
			return;
		}
		elapsed = Math.min(elapsed, OFFLINE_CAP_MS);

		int nestBefore = nestCount();
		long hatchedBefore = state.hatchedTotal;
		boolean incubating = state.incubators.stream().anyMatch(inc -> inc.egg >= 0);
		double offlineSeconds = elapsed / 1000.0 * offlineRate();
		shiniesThisAdvance = 0;
		advance(offlineSeconds, false);
		// Undead hens never sleep: top them up to full speed for the time away
		double undeadExtra = henLayRate(HenType.UNDEAD) * elapsed / 3_600_000.0 * Math.max(0, 1 - offlineRate());
		lay(undeadExtra, HenType.UNDEAD);
		int laid = nestCount() - nestBefore;
		long hatched = state.hatchedTotal - hatchedBefore;
		if (laid <= 0 && hatched <= 0 && !incubating)
		{
			return;
		}

		List<String> lines = new ArrayList<>();
		lines.add("You were away for " + formatDuration(elapsed / 1000) + ".");
		lines.add("Your hens laid " + laid + (laid == 1 ? " egg." : " eggs."));
		if (hatched > 0)
		{
			lines.add(hatched + (hatched == 1 ? " chick hatched." : " chicks hatched."));
		}
		else if (incubating)
		{
			// Offline time counts at a lower rate, so say how much hatching it was worth
			lines.add("Incubators: " + formatDuration((long) (offlineSeconds * hatchSpeedMultiplier(false))) + " closer to hatching.");
		}
		if (shiniesThisAdvance > 0)
		{
			lines.add("A SHINY chick hatched while you were gone!");
		}
		if (nestCount() >= nestCapacity())
		{
			lines.add("Your nest box is full, go collect!");
		}
		dialogs.add(new Dialog("Welcome back!", lines, "Nice!", null, null));
		chat("While you were away your hens laid " + laid + " eggs" + (hatched > 0 ? " and " + hatched + " chicks hatched." : "."));
	}

	/**
	 * Moves the farm forward by {@code seconds} of game time.
	 */
	private void advance(double seconds, boolean online)
	{
		double hatchSeconds = seconds * hatchSpeedMultiplier(online);
		for (int i = 0; i < state.incubators.size(); i++)
		{
			FarmState.Incubator inc = state.incubators.get(i);
			if (inc.egg < 0)
			{
				continue;
			}
			inc.progress += hatchSeconds;
			if (inc.progress >= EggType.values()[inc.egg].getHatchSeconds())
			{
				hatch(i, online);
			}
		}

		lay(layRatePerHour(online) * seconds / 3600.0);
	}

	/**
	 * Adds {@code amount} eggs worth of laying progress, filling the nest box up to its capacity.
	 */
	private void lay(double amount)
	{
		lay(amount, null);
	}

	/**
	 * @param only when set, every egg is laid by this kind of hen (used for the Undead hens' night shift)
	 */
	private void lay(double amount, HenType only)
	{
		int cap = nestCapacity();
		if (nestCount() >= cap)
		{
			state.layProgress = Math.min(state.layProgress, 1);
			return;
		}
		state.layProgress += amount;
		while (state.layProgress >= 1 && nestCount() < cap)
		{
			state.layProgress -= 1;
			HenType hen = only != null ? only : pickLayingHen();
			if (hen == null)
			{
				break;
			}
			EggType egg = rollLaidEgg(hen);
			state.nest[egg.ordinal()]++;
			state.eggsObtained[egg.ordinal()]++;
			state.runEggs++;
			addMasteryEgg(hen);
		}
	}

	/**
	 * Picks which kind of hen laid the next egg, weighted by how fast each kind lays.
	 */
	private HenType pickLayingHen()
	{
		double total = 0;
		for (HenType hen : HenType.values())
		{
			total += henLayRate(hen);
		}
		if (total <= 0)
		{
			return null;
		}
		double r = random.nextDouble() * total;
		for (HenType hen : HenType.values())
		{
			r -= henLayRate(hen);
			if (r < 0)
			{
				return hen;
			}
		}
		return HenType.BROWN;
	}

	private void addMasteryEgg(HenType hen)
	{
		int before = mastery(hen);
		state.henEggsLaid[hen.ordinal()]++;
		int after = mastery(hen);
		if (after > before)
		{
			showToast(hen.getDisplayName() + " mastery " + after + "!");
			chat("Your " + hen.getDisplayName() + "s reached mastery " + after + "/" + MASTERY_EGGS.length
				+ ": they now lay " + after * MASTERY_BONUS_PERCENT + "% faster, forever.");
		}
	}

	/**
	 * Mastery level (0-10) of a kind of hen, from the eggs it has laid over all farms.
	 */
	int mastery(HenType hen)
	{
		long laid = state.henEggsLaid[hen.ordinal()];
		int level = 0;
		while (level < MASTERY_EGGS.length && laid >= MASTERY_EGGS[level])
		{
			level++;
		}
		return level;
	}

	/**
	 * Eggs needed for the next mastery level, or -1 at max.
	 */
	static long masteryTarget(int level)
	{
		return level < MASTERY_EGGS.length ? MASTERY_EGGS[level] : -1;
	}

	private void autoCollect(double seconds)
	{
		int level = level(Upgrade.AUTO_COLLECTOR);
		if (level == 0)
		{
			return;
		}
		if (nestCount() == 0)
		{
			state.autoCollectProgress = Math.min(state.autoCollectProgress, 1);
			return;
		}
		state.autoCollectProgress += level * AUTO_COLLECT_PER_LEVEL * seconds / 3600.0;
		int moved = 0;
		while (state.autoCollectProgress >= 1 && nestCount() > 0)
		{
			state.autoCollectProgress -= 1;
			for (int i = 0; i < state.nest.length; i++)
			{
				if (state.nest[i] > 0)
				{
					state.nest[i]--;
					state.eggs[i]++;
					break;
				}
			}
			moved++;
		}
		if (moved > 0)
		{
			addFarmXp(moved * COLLECT_XP, true);
		}
	}

	private EggType rollLaidEgg(HenType hen)
	{
		if (random.nextDouble() >= hen.getColouredChance())
		{
			return EggType.PLAIN;
		}
		double r = random.nextDouble();
		return r < 0.04 ? EggType.RED : r < 0.2 ? EggType.BLUE : EggType.GREEN;
	}

	/**
	 * Hens of a type, where a shiny counts as several because it lays faster.
	 */
	private double layingHens(HenType hen)
	{
		return state.hens[hen.ordinal()] + state.shiny[hen.ordinal()] * (SHINY_LAY_MULTIPLIER - 1);
	}

	private void hatch(int slot, boolean online)
	{
		FarmState.Incubator inc = state.incubators.get(slot);
		EggType egg = EggType.values()[inc.egg];
		inc.egg = -1;
		inc.progress = 0;

		int tier = egg.getHen().ordinal();
		while (tier < HenType.BEST_HATCHABLE.ordinal() && random.nextDouble() < betterHenChance())
		{
			tier++;
		}
		HenType hen = HenType.values()[tier];
		boolean twins = random.nextDouble() < twinChance();
		int count = twins ? 2 : 1;
		state.hatchedTotal += count;
		if (twins)
		{
			state.twinsHatched++;
		}
		daily.progress(TaskType.HATCH, count);

		StringBuilder msg = new StringBuilder("Your ").append(egg.getDisplayName().toLowerCase())
			.append(" hatched into ").append(twins ? "twin " + hen.getDisplayName() + "s" : "a " + hen.getDisplayName())
			.append('!');
		boolean anyShiny = false;
		for (int i = 0; i < count; i++)
		{
			boolean shiny = farmLevel() >= LEVEL_SHINY && random.nextDouble() < shinyChance();
			anyShiny |= shiny;
			String extra = addHen(hen, shiny);
			if (extra != null)
			{
				msg.append(' ').append(extra);
			}
		}
		addFarmXp(HATCH_XP[egg.ordinal()] * count, online);

		if (anyShiny)
		{
			shiniesThisAdvance++;
			announce("WOW! A shiny " + hen.getDisplayName() + " hatched! It lays " + SHINY_LAY_MULTIPLIER + "x as many eggs.");
			if (online)
			{
				dialogs.addFirst(new Dialog("Shiny chicken!", Arrays.asList(
					"A shiny " + hen.getDisplayName() + "!",
					"It lays " + SHINY_LAY_MULTIPLIER + "x as many eggs."),
					"Amazing!", null, null));
			}
		}

		if (online)
		{
			popup(twins ? "Twins!" : "+1 hen", EGG_COLOR, Anchor.SLOT, slot);
			showToast(twins ? "Twins! +2 " + hen.getDisplayName() : "+1 " + hen.getDisplayName());
			chat(msg.toString());
		}
	}

	/**
	 * Adds a hen, making room in a full coop by selling a weaker normal hen (or the new one if nothing is weaker).
	 *
	 * @return an explanation when the coop was full, otherwise null
	 */
	String addHen(HenType hen, boolean shiny)
	{
		int t = hen.ordinal();
		state.hensObtained[t]++;
		if (shiny)
		{
			state.shinyObtained[t]++;
		}
		if (henCount() < henCapacity())
		{
			state.hens[t]++;
			state.shiny[t] += shiny ? 1 : 0;
			return null;
		}

		// A shiny is worth more than a normal hen of its own kind too
		int limit = shiny ? t + 1 : t;
		for (HenType weaker : HenType.values())
		{
			int w = weaker.ordinal();
			if (w >= limit)
			{
				break;
			}
			if (state.hens[w] - state.shiny[w] > 0)
			{
				state.hens[w]--;
				state.hens[t]++;
				state.shiny[t] += shiny ? 1 : 0;
				state.eggs[EggType.PLAIN.ordinal()] += weaker.getSellValue();
				return "Coop full: sold a " + weaker.getDisplayName() + " for " + weaker.getSellValue() + " eggs to make room.";
			}
		}

		long value = (long) hen.getSellValue() * (shiny ? 3 : 1);
		state.eggs[EggType.PLAIN.ordinal()] += value;
		return "Coop full: sold it for " + value + " eggs.";
	}

	// ---------------------------------------------------------------- earning eggs while playing

	void onXpGained(int xp)
	{
		if (state == null || xp <= 0)
		{
			return;
		}
		daily.progress(TaskType.GAIN_XP, xp);
		state.xpPool += xp;
		while (state.xpPool >= XP_PER_EGG)
		{
			state.xpPool -= XP_PER_EGG;
			findEgg(1);
		}
	}

	void onNpcKilled(NpcKind kind)
	{
		if (state == null)
		{
			return;
		}
		daily.progress(TaskType.KILL_MONSTERS, 1);
		if (kind == NpcKind.UNDEAD_CHICKEN)
		{
			if (random.nextDouble() < CURSED_DROP_CHANCE)
			{
				giveEgg(EggType.CURSED, 1);
				popup("+1", EggType.CURSED.getColor(), Anchor.EGG_BAR, EggType.CURSED.ordinal());
				addFarmXp(FIND_XP * 10, true);
				showToast("The Undead chicken dropped a Cursed egg!");
				announce("The Undead chicken dropped a Cursed egg! Hatch it for an Undead hen.");
			}
			else
			{
				findEgg(1);
			}
		}
		else if (kind == NpcKind.CHICKEN)
		{
			state.chickensKilled++;
			rollPet();
			daily.progress(TaskType.KILL_CHICKENS, 1);
			// Fitting: real chickens always drop an egg, with better odds of a coloured one
			if (findEgg(3) == EggType.PLAIN)
			{
				showToast("The chicken dropped an egg!");
			}
		}
		else if (random.nextDouble() < KILL_EGG_CHANCE)
		{
			findEgg(1);
		}
	}

	private EggType findEgg(double luck)
	{
		double r = random.nextDouble();
		EggType egg;
		if (r < luck * EASTER_FIND_CHANCE)
		{
			egg = EggType.EASTER;
		}
		else if (r < luck / 500)
		{
			egg = EggType.RED;
		}
		else if (r < luck / 120)
		{
			egg = EggType.BLUE;
		}
		else if (r < luck / 25)
		{
			egg = EggType.GREEN;
		}
		else
		{
			egg = EggType.PLAIN;
		}

		giveEgg(egg, 1);
		state.eggsFound++;
		daily.progress(TaskType.FIND_EGGS, 1);
		popup("+1", egg == EggType.PLAIN ? EGG_COLOR : egg.getColor(), Anchor.EGG_BAR, egg.ordinal());
		if (egg == EggType.PLAIN)
		{
			addFarmXp(FIND_XP, true);
		}
		else if (egg == EggType.EASTER)
		{
			addFarmXp(FIND_XP * 50, true);
			gotEasterEgg("while playing");
		}
		else
		{
			addFarmXp(FIND_XP * 5, true);
			showToast("Found a " + egg.getDisplayName() + "!");
			announce("You found a " + egg.getDisplayName().toLowerCase() + "!");
		}
		return egg;
	}

	/**
	 * Big moment: always announced, whatever the chat settings.
	 */
	void gotEasterEgg(String how)
	{
		showToast("SUPER RARE: Easter egg!");
		popup("+1", EggType.EASTER.getColor(), Anchor.EGG_BAR, EggType.EASTER.ordinal());
		announce("SUPER RARE! You got an Easter egg " + how + "!");
		dialogs.addFirst(new Dialog("SUPER RARE!", Arrays.asList(
			"An Easter egg " + how + "!",
			"It hatches into the rarest hen of all."),
			"Amazing!", null, null));
	}

	EggType rollColouredEgg(double redChance, double blueChance)
	{
		double r = random.nextDouble();
		return r < redChance ? EggType.RED : r < redChance + blueChance ? EggType.BLUE : EggType.GREEN;
	}

	void giveEgg(EggType egg, long amount)
	{
		state.eggs[egg.ordinal()] += amount;
		state.eggsObtained[egg.ordinal()] += amount;
		state.runEggs += amount;
	}

	// ---------------------------------------------------------------- farm level

	/**
	 * XP needed for each level (index = level). Follows the OSRS curve early on, but from about level 33 grows
	 * slower so level 99 (~1.5M XP) is reachable in a few months instead of thousands of hours.
	 * It is never steeper than the OSRS curve, so nobody's level goes down.
	 */
	private static final long[] LEVEL_XP = new long[MAX_LEVEL + 2];

	static
	{
		double growth = Math.pow(25, 1 / 49.0);
		for (int level = 1; level <= MAX_LEVEL + 1; level++)
		{
			long osrs = Experience.getXpForLevel(Math.min(level, Experience.MAX_VIRT_LEVEL));
			long eggscape = Math.round(2500 * (Math.pow(growth, level - 1) - 1));
			LEVEL_XP[level] = Math.min(osrs, eggscape);
		}
	}

	int farmLevel()
	{
		int level = 1;
		while (level < MAX_LEVEL && state.farmXp >= LEVEL_XP[level + 1])
		{
			level++;
		}
		return level;
	}

	long xpForLevel(int level)
	{
		return LEVEL_XP[Math.max(1, Math.min(MAX_LEVEL + 1, level))];
	}

	/**
	 * @param online true for XP earned while playing: it shows an XP drop and counts towards XP/hour
	 */
	void addFarmXp(int xp, boolean online)
	{
		if (xp <= 0)
		{
			return;
		}
		state.farmXp += xp;
		if (online)
		{
			long now = System.currentTimeMillis();
			XpDrop last = xpDrops.isEmpty() ? null : xpDrops.get(xpDrops.size() - 1);
			if (last != null && now - last.start < XP_DROP_MERGE_MS)
			{
				last.amount += xp;
			}
			else
			{
				xpDrops.add(new XpDrop(xp, now));
				while (xpDrops.size() > MAX_XP_DROPS)
				{
					xpDrops.remove(0);
				}
			}
			lastXpMillis = now;
			if (sessionStartMillis == 0)
			{
				sessionStartMillis = now;
			}
			sessionXp += xp;
		}
		checkLevelUps();
	}

	/**
	 * Hands out the rewards for every level reached but not yet rewarded, in one go.
	 */
	private void checkLevelUps()
	{
		int level = farmLevel();
		int from = state.levelRewarded;
		if (from >= level)
		{
			return;
		}
		long reward = 0;
		for (int l = from + 1; l <= level; l++)
		{
			reward += l * 5L;
			queueUnlock(l);
			if (l == LEVEL_DAILY_TASKS)
			{
				ticksSinceDayCheck = DAY_CHECK_TICKS;
			}
		}
		state.levelRewarded = level;
		giveEgg(EggType.PLAIN, reward);
		levelUpLevel = level;
		levelUpReward = reward;
		levelUpUntil = System.currentTimeMillis() + LEVEL_BANNER_MS;
		announce(level - from == 1
			? "Congratulations, your Farm level is now " + level + "! (+" + reward + " eggs)"
			: "Congratulations, your Farm level went from " + from + " to " + level + "! (+" + reward + " eggs)");
	}

	private void queueUnlock(int level)
	{
		switch (level)
		{
			case LEVEL_DAILY_TASKS:
				dialogs.add(new Dialog("Unlocked: Daily tasks", Arrays.asList(
					"3 new tasks every day.",
					"Find them in the new scroll tab."), "OK", null, null));
				break;
			case LEVEL_AUTO_COLLECTOR:
				dialogs.add(new Dialog("Unlocked: Auto-collector", Arrays.asList(
					"It collects eggs for you.",
					"Find it in the Shop."), "OK", null, null));
				break;
			case LEVEL_SHINY:
				dialogs.add(new Dialog("Unlocked: Shiny chickens", Arrays.asList(
					"Chicks can now hatch shiny.",
					"Shinies lay " + SHINY_LAY_MULTIPLIER + "x as many eggs."), "OK", null, null));
				break;
			case LEVEL_PRESTIGE:
				dialogs.add(new Dialog("Unlocked: Golden Feathers", Arrays.asList(
					"Start over for Golden Feathers:",
					"+10% laying each, forever. See the Shop."), "OK", null, null));
				break;
			default:
				break;
		}
		for (FarmTheme theme : FarmTheme.values())
		{
			if (theme.getFarmLevel() == level)
			{
				queueThemeUnlock(theme);
			}
		}
	}

	private void queueThemeUnlock(FarmTheme theme)
	{
		dialogs.add(new Dialog("New farm look!", Arrays.asList(
			theme.getDisplayName(),
			"Pick it in the Shop."), "OK", null, null));
	}

	/**
	 * @return the next level that unlocks something, or -1 when everything is unlocked
	 */
	int nextUnlockLevel()
	{
		int level = farmLevel();
		for (int unlock : new int[]{LEVEL_ACHIEVEMENTS, LEVEL_COLLECTION_LOG, LEVEL_DAILY_TASKS, LEVEL_AUTO_COLLECTOR, LEVEL_SHINY,
			LEVEL_PRESTIGE})
		{
			if (level < unlock)
			{
				return unlock;
			}
		}
		return -1;
	}

	static String unlockName(int level)
	{
		switch (level)
		{
			case LEVEL_ACHIEVEMENTS:
				return "Achievements";
			case LEVEL_COLLECTION_LOG:
				return "Collection log";
			case LEVEL_DAILY_TASKS:
				return "Daily tasks";
			case LEVEL_AUTO_COLLECTOR:
				return "Auto-collector";
			case LEVEL_SHINY:
				return "Shiny chickens";
			case LEVEL_PRESTIGE:
				return "Golden Feathers";
			default:
				return "";
		}
	}

	/**
	 * Farm XP per hour this session (measured over at least 5 minutes so it doesn't spike at the start).
	 */
	long xpPerHour()
	{
		if (sessionStartMillis == 0)
		{
			return 0;
		}
		long elapsed = Math.max(MIN_RATE_WINDOW_MS, System.currentTimeMillis() - sessionStartMillis);
		return sessionXp * 3_600_000L / elapsed;
	}

