	}

	boolean isLevelUpVisible()
	{
		return System.currentTimeMillis() < levelUpUntil;
	}

	long levelUpAgeMillis()
	{
		return System.currentTimeMillis() - (levelUpUntil - LEVEL_BANNER_MS);
	}

	/**
	 * Gives the Rubber chicken pet, or takes it away again so the drop can be tested twice.
	 */
	void debugTogglePet()
	{
