	// ---------------------------------------------------------------- Rubber chicken pet

	private void rollPet()
	{
		rollPet(RUBBER_CHICKEN_CHANCE);
	}

	private void rollPet(double chance)
	{
		if (state.rubberChicken || random.nextDouble() >= chance)
		{
			return;
		}
		state.rubberChicken = true;
		announce("You have a funny feeling like you're being followed.");
		dialogs.addFirst(new Dialog("Pet drop!", Arrays.asList(
			"You have a funny feeling like you're being followed...",
			"A Rubber chicken joined your farm!"),
			"Squeak!", null, null).image(Sprites.RUBBER_CHICKEN));
