	}

	@Getter
	private long lastSqueakMillis;

	void squeak()
	{
		if (state == null || !state.rubberChicken)
		{
			return;
		}
		lastSqueakMillis = System.currentTimeMillis();
		popup("Squeak!", new Color(255, 230, 140), Anchor.PET, 0);
		playSqueak();
	}

	private void playSqueak()
	{
		int volume = config.squeakVolume();
		if (volume > 0)
		{
			// Volume 1-100 as decibels: 100 is full volume, every halving is about -6 dB
			playSound("squeak.wav", (float) (20 * Math.log10(volume / 100.0)));
		}
	}

	void playEventSound()
	{
		if (config.eventSound())
		{
			playSound("event.wav", EVENT_SOUND_GAIN);
		}
	}

	private void playSound(String resource, float gain)
	{
		// Loading and opening the sound line is blocking IO, so keep it off the client thread
		executor.execute(() ->
		{
			try
			{
				audioPlayer.play(EggscapePlugin.class, resource, gain);
			}
			catch (Exception e)
			{
				log.debug("Unable to play {}", resource, e);
			}
		});
	}

	// ---------------------------------------------------------------- achievements

	private void checkAchievements()
	{
		for (Achievement a : Achievement.values())
		{
			if (state.achievements.contains(a.name()) || a.progress(this) < a.getTarget())
			{
				continue;
			}
			state.achievements.add(a.name());
			giveEgg(EggType.PLAIN, a.getReward());
			popup("+" + a.getReward(), EGG_COLOR, Anchor.EGG_BAR, EggType.PLAIN.ordinal());
			addFarmXp(ACHIEVEMENT_XP, true);
			showToast("Achievement: " + a.getDisplayName());
			chat("Achievement unlocked: " + a.getDisplayName() + "! (+" + a.getReward() + " eggs)");
		}

		for (AchievementTrack track : AchievementTrack.values())
		{
			int tier = trackTier(track);
			long progress = track.progress(this);
			while (tier < track.getTargets().length && progress >= track.getTargets()[tier])
			{
				AchievementTier reached = AchievementTier.values()[tier];
				tier++;
				state.trackTiers.put(track.name(), tier);
				giveEgg(EggType.PLAIN, reached.getRewardEggs());
				popup("+" + reached.getRewardEggs(), EGG_COLOR, Anchor.EGG_BAR, EggType.PLAIN.ordinal());
				addFarmXp(reached.getRewardXp(), true);
				showToast(reached.getDisplayName() + " " + track.getDisplayName() + "!");
				trophyTrack = track;
				trophyTier = reached;
				trophyUntil = System.currentTimeMillis() + LEVEL_BANNER_MS;
				chat("Achievement unlocked: " + track.getDisplayName() + " (" + reached.getDisplayName() + ")! (+"
						+ reached.getRewardEggs() + " eggs)");
			}
		}
	}

	boolean isAchieved(Achievement achievement)
	{
		return state.achievements.contains(achievement.name());
	}

	/**
	 * Tiers reached on a track: 0 = none, 1 = Bronze ... 7 = Dragon.
	 */
	int trackTier(AchievementTrack track)
	{
		return state.trackTiers.getOrDefault(track.name(), 0);
	}

	// ---------------------------------------------------------------- prestige

	int feathersForPrestige()
	{
		return (int) Math.floor(Math.sqrt(state.runEggs / 50.0));
	}

	boolean canPrestige()
	{
		return farmLevel() >= LEVEL_PRESTIGE && feathersForPrestige() >= 1;
	}

	void requestPrestige()
	{
		if (state == null)
		{
			return;
		}
		if (!canPrestige())
		{
			showToast(farmLevel() < LEVEL_PRESTIGE ? "Needs Farm level " + LEVEL_PRESTIGE : "Grow your farm a bit more first");
			return;
		}
		int gain = feathersForPrestige();
		dialogs.addFirst(new Dialog("Sell the farm?", Arrays.asList(
			"You get " + gain + " Golden Feather" + (gain == 1 ? "" : "s") + ": +" + gain * 10 + "% laying forever.",
			"Upgrades, plain eggs and brown hens reset.",
			"Rare eggs, rare hens and shinies stay.",
			"Then everything runs 2x as fast for an hour."),
			"Sell farm", "Cancel", this::prestige));
	}

	private void prestige()
	{
		if (state == null || !canPrestige())
		{
			return;
		}
		int gain = feathersForPrestige();
		state.feathers += gain;
		state.feathersEarned += gain;
		state.prestiges++;
		state.resetFarm();
		state.freshStartTicks = FRESH_START_TICKS;
		visitors.clear();
		announce("You sold your farm for " + gain + " Golden Feathers! Laying is now permanently +" + state.feathersEarned * 10 + "%.");

		// A new look is switched on straight away, so the new farm looks different from the old one
		prestigeTheme = null;
		for (FarmTheme theme : FarmTheme.values())
		{
			if (theme.getPrestiges() == state.prestiges)
			{
				prestigeTheme = theme;
				state.theme = theme.ordinal();
			}
		}
		prestigeGain = gain;
		prestigeUntil = System.currentTimeMillis() + PRESTIGE_BANNER_MS;
		showFarmPending = true;
		save();
	}

	void buyFeatherUpgrade(FeatherUpgrade upgrade)
	{
		if (state == null)
		{
			return;
		}
		int level = featherLevel(upgrade);
		if (level >= upgrade.getMaxLevel())
		{
			return;
		}
		int cost = upgrade.cost(level);
		if (state.feathers < cost)
		{
			showToast("Not enough Golden Feathers");
			return;
		}
		state.feathers -= cost;
		state.featherUpgrades[upgrade.ordinal()]++;
		showToast(upgrade.getDisplayName() + " level " + (level + 1) + "!");
		save();
	}

	int featherLevel(FeatherUpgrade upgrade)
	{
		return state.featherUpgrades[upgrade.ordinal()];
	}

	double featherMultiplier()
	{
		return 1 + 0.1 * state.feathersEarned;
	}

	private double offlineRate()
	{
		return BASE_OFFLINE_RATE + 0.1 * featherLevel(FeatherUpgrade.NIGHT_SHIFT);
	}

	// ---------------------------------------------------------------- egg exchange and looks

	void exchange(ExchangeOffer offer)
	{
		if (state == null)
		{
			return;
		}
		if (state.eggs[offer.getGive().ordinal()] < offer.getGiveAmount())
		{
			showToast("You need " + offer.getGiveAmount() + " " + offer.getGive().getDisplayName().toLowerCase() + (offer.getGiveAmount() == 1 ? "" : "s"));
			return;
		}
		state.eggs[offer.getGive().ordinal()] -= offer.getGiveAmount();
		state.eggs[offer.getGet().ordinal()] += offer.getGetAmount();
		if (offer.getGet() != EggType.PLAIN)
		{
			state.eggsObtained[offer.getGet().ordinal()] += offer.getGetAmount();
		}
		EggType get = offer.getGet();
		popup("+" + offer.getGetAmount(), get == EggType.PLAIN ? EGG_COLOR : get.getColor(), Anchor.EGG_BAR, get.ordinal());
		save();
	}

	boolean isThemeUnlocked(FarmTheme theme)
	{
		return state.prestiges >= theme.getPrestiges() && farmLevel() >= theme.getFarmLevel();
	}

	FarmTheme theme()
	{
		FarmTheme theme = FarmTheme.values()[state.theme];
		return isThemeUnlocked(theme) ? theme : FarmTheme.CLASSIC;
	}

	void setTheme(FarmTheme theme)
	{
		if (state != null && isThemeUnlocked(theme))
		{
			state.theme = theme.ordinal();
			save();
		}
	}

	// ---------------------------------------------------------------- player actions (from the overlay)

	void collectNest()
	{
		if (state == null)
		{
			return;
		}
		int total = nestCount();
		if (total == 0)
		{
			showToast("The nest box is empty");
			return;
		}
		for (int i = 0; i < state.nest.length; i++)
		{
			state.eggs[i] += state.nest[i];
			state.nest[i] = 0;
		}
		daily.progress(TaskType.COLLECT_NEST, total);
		popup("+" + total, EGG_COLOR, Anchor.NEST, 0);
		addFarmXp(total * COLLECT_XP, true);
	}

	void selectEgg(EggType egg)
	{
		if (state != null)
		{
			state.selectedEgg = egg.ordinal();
		}
	}

	void placeEgg(int slot)
	{
		if (state == null || slot < 0 || slot >= state.incubators.size())
		{
			return;
		}
		FarmState.Incubator inc = state.incubators.get(slot);
		if (inc.egg >= 0)
		{
			return;
		}
		EggType egg = EggType.values()[state.selectedEgg];
		if (state.eggs[egg.ordinal()] <= 0)
		{
			showToast("You have no " + egg.getDisplayName().toLowerCase() + "s");
			return;
		}
		state.eggs[egg.ordinal()]--;
		inc.egg = egg.ordinal();
		inc.progress = 0;
		save();
	}

	void buy(Upgrade upgrade)
	{
		if (state == null)
		{
			return;
		}
		int level = level(upgrade);
		if (level >= upgrade.getMaxLevel())
		{
			return;
		}
		if (farmLevel() < upgrade.getMinFarmLevel())
		{
			showToast("Needs Farm level " + upgrade.getMinFarmLevel());
			return;
		}
		long cost = upgrade.cost(level);
		if (state.eggs[EggType.PLAIN.ordinal()] < cost)
		{
			showToast("Not enough eggs");
			return;
		}
		state.eggs[EggType.PLAIN.ordinal()] -= cost;
		state.upgrades[upgrade.ordinal()]++;
		state.normalize();
		showToast(upgrade.getDisplayName() + " level " + (level + 1) + "!");
		save();
	}

	void setCollapsed(boolean collapsed)
	{
		if (state != null)
		{
			state.collapsed = collapsed;
		}
	}

	Dialog currentDialog()
	{
		return dialogs.peekFirst();
	}

	void confirmDialog()
	{
		Dialog dialog = dialogs.pollFirst();
		if (dialog != null && dialog.onConfirm != null)
		{
			dialog.onConfirm.run();
		}
	}

	void cancelDialog()
	{
		dialogs.pollFirst();
	}

	// ---------------------------------------------------------------- derived values

	int level(Upgrade upgrade)
	{
		return state.upgrades[upgrade.ordinal()];
	}

	int henCount()
	{
		int n = 0;
		for (int c : state.hens)
		{
			n += c;
		}
		return n;
	}

	int henCapacity()
	{
		return BASE_HEN_CAPACITY + HENS_PER_COOP * level(Upgrade.COOP);
	}

	int nestCount()
	{
		int n = 0;
		for (int c : state.nest)
		{
			n += c;
		}
		return n;
	}

	int nestCapacity()
	{
		return 12 + 15 * level(Upgrade.NEST_BOX);
	}

	double layRatePerHour()
	{
		return layRatePerHour(true);
	}

	/**
	 * @param online whether the rooster's blessing and the fresh start boost apply (they only last while you play)
	 */
	private double layRatePerHour(boolean online)
	{
		double rate = 0;
		for (HenType hen : HenType.values())
		{
			rate += henLayRate(hen);
		}
		if (online && state.blessingTicks > 0)
		{
			rate *= 2;
		}
		return rate * freshStartMultiplier(online);
	}

	private double freshStartMultiplier(boolean online)
	{
		return online && state.freshStartTicks > 0 ? 2 : 1;
	}

	/**
	 * Eggs per hour from all hens of one type, with feed and feather bonuses but without the rooster.
	 */
	private double henLayRate(HenType hen)
	{
		return layingHens(hen) * hen.getEggsPerHour() * (1 + 0.25 * level(Upgrade.FEED)) * featherMultiplier()
			* (1 + mastery(hen) * MASTERY_BONUS_PERCENT / 100.0);
	}

	double shinyChance()
	{
		return SHINY_CHANCE * (1 + 0.25 * featherLevel(FeatherUpgrade.SHINY_CHARM));
	}

	double hatchSpeedMultiplier()
	{
		return hatchSpeedMultiplier(true);
	}

	private double hatchSpeedMultiplier(boolean online)
	{
		return (1 + 0.2 * level(Upgrade.HEAT_LAMP)) * freshStartMultiplier(online);
	}

	double twinChance()
	{
		return 0.04 * level(Upgrade.LUCKY_STRAW);
	}

	private double betterHenChance()
	{
		return BETTER_HEN_CHANCE + 0.02 * featherLevel(FeatherUpgrade.LUCKY_CHARM);
	}

	/**
	 * Seconds of logged-in play until the egg in this incubator hatches.
	 */
	long secondsLeft(FarmState.Incubator inc)
	{
		if (inc.egg < 0)
		{
			return 0;
		}
		double left = EggType.values()[inc.egg].getHatchSeconds() - inc.progress;
		return (long) Math.ceil(Math.max(0, left) / hatchSpeedMultiplier());
	}

	long colouredEggTypesObtained()
	{
		long n = 0;
		for (EggType egg : EggType.values())
		{
			if (egg != EggType.PLAIN && state.eggsObtained[egg.ordinal()] > 0)
			{
				n++;
			}
		}
		return n;
	}

	long eventsCompleted()
	{
		long n = 0;
		for (int wins : state.eventWins)
		{
			n += wins;
		}
		return n;
	}

	long maxedUpgrades()
	{
		long n = 0;
		for (Upgrade u : Upgrade.values())
		{
			if (level(u) >= u.getMaxLevel())
			{
				n++;
			}
		}
		return n;
	}

	long shiniesObtained()
	{
		long n = 0;
		for (long c : state.shinyObtained)
		{
			n += c;
		}
		return n;
	}

	long collectionProgress()
	{
		long n = state.eventWins[FarmEvent.GOLDEN_EGG.ordinal()] > 0 ? 1 : 0;
		n += state.rubberChicken ? 1 : 0;
		for (int i = 0; i < HenType.values().length; i++)
		{
			n += state.hensObtained[i] > 0 ? 1 : 0;
			n += state.shinyObtained[i] > 0 ? 1 : 0;
		}
		for (long c : state.eggsObtained)
		{
			n += c > 0 ? 1 : 0;
		}
		return n;
	}

	/**
	 * Everything in the Shop the player can buy right now, as "upgrade:level" keys, so the panel can tell
	 * which of them are new since the Shop was last opened.
	 */
	Set<String> affordable()
	{
		Set<String> keys = new HashSet<>();
		if (state == null)
		{
			return keys;
		}
		long eggs = state.eggs[EggType.PLAIN.ordinal()];
		for (Upgrade u : Upgrade.values())
		{
			int level = level(u);
			if (level < u.getMaxLevel() && farmLevel() >= u.getMinFarmLevel() && eggs >= u.cost(level))
			{
				keys.add(u.name() + ":" + level);
			}
		}
		for (FeatherUpgrade u : FeatherUpgrade.values())
		{
			int level = featherLevel(u);
			if (level < u.getMaxLevel() && state.feathers >= u.cost(level))
			{
				keys.add(u.name() + ":" + level);
			}
		}
		if (canPrestige())
		{
			keys.add("PRESTIGE:" + state.prestiges);
		}
		return keys;
	}

	/**
	 * Something on the farm wants the player's attention (used to blink the minimised panel).
	 */
	boolean needsAttention()
	{
		return visitors.getActive() != null || !dialogs.isEmpty() || daily.hasClaimable();
	}

	// ---------------------------------------------------------------- visitors and daily rewards (for the panel)

	FarmVisitors.ActiveEvent getActiveEvent()
	{
		return visitors.getActive();
	}

	void clickEvent()
	{
		visitors.click();
	}

	void clickBush(int bush)
	{
		visitors.clickBush(bush);
	}

	void updateChallenge()
	{
		visitors.updateChallenge();
	}

	/**
	 * Starts a farm visitor right away (developer mode only, see EggscapePlugin).
	 */
	void debugSpawnEvent(FarmEvent type)
	{
		if (state != null)
		{
			visitors.spawn(type);
		}
	}

	boolean hasClaimableTask()
	{
		return daily.hasClaimable();
	}

	EggscapeConfig getConfig()
	{
		return config;
	}

	void showDialog(Dialog dialog)
	{
		dialogs.add(dialog);
	}

	/**
	 * Shows a card before any others that are waiting, for big moments like rare drops.
	 */
	void showDialogFirst(Dialog dialog)
	{
		dialogs.addFirst(dialog);
	}

	// ---------------------------------------------------------------- what the player can see
	// New players start with just the field; parts of the panel appear once they mean something.

	boolean isTabUnlocked(EggscapeOverlay.Tab tab)
	{
		switch (tab)
		{
			case SHOP:
				// After the first hatch there is something to spend eggs on
				return state.hatchedTotal > 0 || state.prestiges > 0;
			case GOALS:
				return farmLevel() >= LEVEL_ACHIEVEMENTS;
			case LOG:
				return farmLevel() >= LEVEL_COLLECTION_LOG;
			case TASKS:
				return farmLevel() >= LEVEL_DAILY_TASKS;
			case FARM:
			default:
				return true;
		}
	}

	boolean isTabSeen(String tab)
	{
		// The farm is where everyone starts, so it is never "new"
		return tab.equals(EggscapeOverlay.Tab.FARM.name()) || state.seenTabs.contains(tab);
	}

	void markTabSeen(String tab)
	{
		state.seenTabs.add(tab);
	}

	boolean isTradeUnlocked()
	{
		return colouredEggTypesObtained() > 0;
	}

	boolean isFeathersUnlocked()
	{
		return farmLevel() >= LEVEL_PRESTIGE || state.feathersEarned > 0;
	}

	boolean isLooksUnlocked()
	{
		int unlocked = 0;
		for (FarmTheme theme : FarmTheme.values())
		{
			unlocked += isThemeUnlocked(theme) ? 1 : 0;
		}
		return unlocked > 1;
	}

	// ---------------------------------------------------------------- feedback

	void popup(String text, Color color, Anchor anchor, int index)
	{
		popups.add(new Popup(text, color, anchor, index, System.currentTimeMillis()));
		while (popups.size() > MAX_POPUPS)
		{
			popups.remove(0);
		}
	}

	void showToast(String text)
	{
		toast = text;
		toastUntil = System.currentTimeMillis() + TOAST_MS;
	}

	boolean isToastVisible()
	{
		return toast != null && System.currentTimeMillis() < toastUntil;
	}

	/**
	 * Everyday news (hatches, visitors, achievements): only when chat messages are set to All.
	 */
	void chat(String text)
	{
		if (config.chatMessages() == EggscapeConfig.ChatMessages.ALL)
		{
			sendChat(text);
		}
	}

	/**
	 * Big moments (rare eggs, level ups, pets): unless chat messages are turned off.
	 */
	void announce(String text)
	{
		if (config.chatMessages() != EggscapeConfig.ChatMessages.OFF)
		{
			sendChat(text);
		}
	}

	private void sendChat(String text)
	{
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Eggscape] ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(msg)
			.build());
	}

	static String formatDuration(long seconds)
	{
		if (seconds >= 3600)
		{
			return seconds / 3600 + "h " + (seconds % 3600) / 60 + "m";
		}
		if (seconds >= 60)
		{
			return seconds / 60 + "m " + seconds % 60 + "s";
		}
		return seconds + "s";
	}
}

package com.eggscape;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Everything that is saved per OSRS account. Serialized with Gson, so fields stay plain.
 */
public class FarmState
{
	static final int FIRST_EVENT_TICKS = 1000;
	static final int TASKS_PER_DAY = 3;

	// ---- The current farm (reset when you prestige)
	public long[] eggs = new long[EggType.values().length];
	public int[] hens = new int[HenType.values().length];
	/**
	 * How many of {@link #hens} are shiny, per type.
	 */
	public int[] shiny = new int[HenType.values().length];
	public int[] nest = new int[EggType.values().length];
	public int[] upgrades = new int[Upgrade.values().length];
	public List<Incubator> incubators = new ArrayList<>();
	public double xpPool;
	public double layProgress;
	public double autoCollectProgress;
	/**
	 * Ticks left on the rooster's double laying blessing.
	 */
	public int blessingTicks;
	/**
	 * Ticks left on the double speed boost after selling the farm.
	 */
	public int freshStartTicks;
	/**
	 * Eggs gained on this farm, which decides the Golden Feathers you get for selling it.
	 */
	public long runEggs;

	// ---- Kept forever
	public int selectedEgg;
	public boolean collapsed;
	/**
	 * Tabs the player has opened at least once; new ones blink until then. Null in saves from before tabs unlocked.
	 */
	public Set<String> seenTabs;
	/**
	 * {@link FarmTheme} ordinal.
	 */
	public int theme;
	/**
	 * Wall clock time (epoch millis) of the last logged-in game tick, used for offline progress.
	 */
	public long lastSeen;
	public int nextEventTicks = FIRST_EVENT_TICKS;

	public long farmXp;
	/**
	 * Highest Farm level whose reward has been handed out.
	 */
	public int levelRewarded;
	/**
	 * Eggs laid per kind of hen over all farms, for Hen Mastery.
	 */
	public long[] henEggsLaid = new long[HenType.values().length];

	public long hatchedTotal;
	public long eggsFound;
	public long[] eggsObtained = new long[EggType.values().length];
	public long[] hensObtained = new long[HenType.values().length];
	public long[] shinyObtained = new long[HenType.values().length];
	public int[] eventWins = new int[FarmEvent.values().length];
	public long chickensKilled;
	/**
	 * The Rubber chicken pet (1 in 1,000 chicken kills).
	 */
	public boolean rubberChicken;
	public long twinsHatched;
	public Set<String> achievements = new HashSet<>();
	/**
	 * Tiers reached per {@link AchievementTrack} name: 0 = none, 1 = Bronze ... 7 = Dragon.
	 */
	public Map<String, Integer> trackTiers = new HashMap<>();

	/**
	 * {@link java.time.LocalDate#toEpochDay()} of the last claimed daily reward.
	 */
	public long lastDailyDay;
	public int streak;
	public int bestStreak;

	public long taskDay;
	public List<DailyTask> tasks = new ArrayList<>();
	public boolean taskChestClaimed;
	public long tasksCompleted;

	/**
	 * Unspent Golden Feathers.
	 */
	public int feathers;
	/**
	 * All feathers ever earned; each one boosts laying permanently, even after spending it.
	 */
	public int feathersEarned;
	public int prestiges;
	public int[] featherUpgrades = new int[FeatherUpgrade.values().length];

	public static class Incubator
	{
		/**
		 * {@link EggType} ordinal, or -1 when empty.
		 */
		public int egg = -1;
		/**
		 * Hatch progress in base seconds (already multiplied by speed bonuses).
		 */
		public double progress;
	}

	public static class DailyTask
	{
		/**
		 * {@link TaskType} ordinal.
		 */
		public int type;
		public long target;
		public long progress;
		public boolean claimed;

		TaskType taskType()
		{
			return TaskType.values()[type];
		}

		boolean isComplete()
		{
			return progress >= target;
		}
	}

	static FarmState newFarm()
	{
		FarmState s = new FarmState();
		s.eggs[EggType.PLAIN.ordinal()] = 2;
		s.hens[HenType.BROWN.ordinal()] = 2;
		s.lastSeen = System.currentTimeMillis();
		s.levelRewarded = 1;
		s.normalize();
		return s;
	}

	/**
	 * Clears the current farm for a prestige: plain eggs, brown hens and upgrades go. Rare eggs (also those in
	 * the nest and incubators), rare hens and shinies stay, as do levels, collection log, achievements and feathers.
	 */
	void resetFarm()
	{
		long[] keptEggs = new long[EggType.values().length];
		for (int i = 0; i < keptEggs.length; i++)
		{
			keptEggs[i] = eggs[i] + nest[i];
		}
		for (Incubator inc : incubators)
		{
			if (inc.egg >= 0)
			{
				keptEggs[inc.egg]++;
			}
		}
		keptEggs[EggType.PLAIN.ordinal()] = 0;
		int[] keptHens = hens.clone();
		keptHens[HenType.BROWN.ordinal()] = shiny[HenType.BROWN.ordinal()];

		eggs = keptEggs;
		hens = keptHens;
		nest = new int[EggType.values().length];
		upgrades = new int[Upgrade.values().length];
		incubators = new ArrayList<>();
		xpPool = 0;
		layProgress = 0;
		autoCollectProgress = 0;
		blessingTicks = 0;
		runEggs = 0;
		selectedEgg = 0;

		int headStart = featherUpgrades[FeatherUpgrade.HEAD_START.ordinal()];
		eggs[EggType.PLAIN.ordinal()] = 2 + 25L * headStart;
		hens[HenType.BROWN.ordinal()] += 2 + 2 * headStart;
		upgrades[Upgrade.INCUBATOR.ordinal()] = featherUpgrades[FeatherUpgrade.WARM_START.ordinal()];
		// Keep the coop big enough for the hens you keep, with room to hatch a couple more
		int henCount = Arrays.stream(hens).sum();
		int coop = (int) Math.ceil(Math.max(0, henCount + 2 - FarmManager.BASE_HEN_CAPACITY) / (double) FarmManager.HENS_PER_COOP);
		upgrades[Upgrade.COOP.ordinal()] = Math.min(Upgrade.COOP.getMaxLevel(), coop);
		normalize();
	}

	/**
	 * Repairs data from older versions or hand-edited configs so the rest of the code can trust it.
	 */
	void normalize()
	{
		eggs = resize(eggs, EggType.values().length);
		hens = resize(hens, HenType.values().length);
		shiny = resize(shiny, HenType.values().length);
		nest = resize(nest, EggType.values().length);
		upgrades = resize(upgrades, Upgrade.values().length);
		featherUpgrades = resize(featherUpgrades, FeatherUpgrade.values().length);
		for (Upgrade u : Upgrade.values())
		{
			upgrades[u.ordinal()] = Math.max(0, Math.min(u.getMaxLevel(), upgrades[u.ordinal()]));
		}
		for (FeatherUpgrade u : FeatherUpgrade.values())
		{
			featherUpgrades[u.ordinal()] = Math.max(0, Math.min(u.getMaxLevel(), featherUpgrades[u.ordinal()]));
		}
		for (int i = 0; i < eggs.length; i++)
		{
			eggs[i] = Math.max(0, eggs[i]);
			nest[i] = Math.max(0, nest[i]);
		}
		for (int i = 0; i < hens.length; i++)
		{
			hens[i] = Math.max(0, hens[i]);
			shiny[i] = Math.max(0, Math.min(hens[i], shiny[i]));
		}

		eggsObtained = resize(eggsObtained, EggType.values().length);
		hensObtained = resize(hensObtained, HenType.values().length);
		shinyObtained = resize(shinyObtained, HenType.values().length);
		eventWins = resize(eventWins, FarmEvent.values().length);
		henEggsLaid = resize(henEggsLaid, HenType.values().length);
		// Farms from before the collection log already own some things; count them
		for (int i = 0; i < eggs.length; i++)
		{
			eggsObtained[i] = Math.max(eggsObtained[i], eggs[i] + nest[i]);
		}
		for (int i = 0; i < hens.length; i++)
		{
			hensObtained[i] = Math.max(hensObtained[i], hens[i]);
			shinyObtained[i] = Math.max(shinyObtained[i], shiny[i]);
		}
		if (achievements == null)
		{
			achievements = new HashSet<>();
		}
		if (trackTiers == null)
		{
			trackTiers = new HashMap<>();
		}
		if (seenTabs == null)
		{
			// Players from before tabs unlocked one by one already know every tab
			seenTabs = new HashSet<>();
			if (hatchedTotal > 0)
			{
				for (EggscapeOverlay.Tab tab : EggscapeOverlay.Tab.values())
				{
					seenTabs.add(tab.name());
				}
			}
		}
		for (AchievementTrack track : AchievementTrack.values())
		{
			Integer tier = trackTiers.get(track.name());
			if (tier == null)
			{
				tier = legacyTier(track);
			}
			trackTiers.put(track.name(), Math.max(0, Math.min(AchievementTier.values().length, tier)));
		}
		if (nextEventTicks <= 0)
		{
			nextEventTicks = FIRST_EVENT_TICKS;
		}
		blessingTicks = Math.max(0, blessingTicks);
		freshStartTicks = Math.max(0, freshStartTicks);
		farmXp = Math.max(0, farmXp);
		feathers = Math.max(0, feathers);
		feathersEarned = Math.max(feathers, feathersEarned);

		if (tasks == null)
		{
			tasks = new ArrayList<>();
		}
		tasks.removeIf(t -> t == null || t.type < 0 || t.type >= TaskType.values().length || t.target <= 0);
		while (tasks.size() > TASKS_PER_DAY)
		{
			tasks.remove(tasks.size() - 1);
		}

		if (incubators == null)
		{
			incubators = new ArrayList<>();
		}
		incubators.removeIf(inc -> inc == null);
		int slots = 1 + upgrades[Upgrade.INCUBATOR.ordinal()];
		while (incubators.size() < slots)
		{
			incubators.add(new Incubator());
		}
		while (incubators.size() > slots)
		{
			incubators.remove(incubators.size() - 1);
		}
		for (Incubator inc : incubators)
		{
			if (inc.egg < -1 || inc.egg >= EggType.values().length || Double.isNaN(inc.progress))
			{
				inc.egg = -1;
				inc.progress = 0;
			}
		}

		if (selectedEgg < 0 || selectedEgg >= EggType.values().length)
		{
			selectedEgg = 0;
		}
		if (theme < 0 || theme >= FarmTheme.values().length)
		{
			theme = 0;
		}
		xpPool = clean(xpPool);
		layProgress = clean(layProgress);
		autoCollectProgress = clean(autoCollectProgress);
	}

	/**
	 * Tiers already paid for through the old one-off achievements that a track replaced.
	 */
	private int legacyTier(AchievementTrack track)
	{
		int tier = 0;
		Object[] legacy = track.getLegacy();
		for (int i = 0; i + 1 < legacy.length; i += 2)
		{
			if (!achievements.contains((String) legacy[i]))
			{
				continue;
			}
			long value = ((Number) legacy[i + 1]).longValue();
			int t = 0;
			while (t < track.getTargets().length && track.getTargets()[t] <= value)
			{
				t++;
			}
			tier = Math.max(tier, t);
		}
		return tier;
	}

	private static double clean(double d)
	{
		return Double.isNaN(d) || d < 0 ? 0 : d;
	}

	private static long[] resize(long[] a, int len)
	{
		return a == null ? new long[len] : Arrays.copyOf(a, len);
	}

	private static int[] resize(int[] a, int len)
	{
		return a == null ? new int[len] : Arrays.copyOf(a, len);
	}
}

package com.eggscape;

import java.awt.Color;
import lombok.Getter;
