/**
 * The Farm tab: the field with the flock, the coop (nest box), visitors and the incubators.
 */
@Singleton
class FarmView extends PanelPart
{
	private static final float HEN_SPEED = 14f;

	private final EggscapeConfig config;
	private final EventView events;

	private final Random random = new Random();
	private final int[][] tufts;
	private final List<HenSprite> flock = new ArrayList<>();
	private long lastFrameNanos;

	/**
	 * What clicking the locked incubator slot does (opens the shop).
	 */
	@Setter
	private Runnable openShop = () ->
	{
	};

	private static class HenSprite
	{
		HenType type;
		boolean shiny;
		float x, y, targetX, targetY;
		boolean facingRight;
		long pauseUntil;
		int peckPhase;
	}

	@Inject
	FarmView(FarmManager farm, Sprites sprites, TooltipManager tooltipManager, EggscapeConfig config, EventView events)
	{
		super(farm, sprites, tooltipManager);
		this.config = config;
		this.events = events;

		// Fixed grass tufts so the field doesn't flicker
		Random seeded = new Random(42);
		tufts = new int[40][2];
		for (int[] t : tufts)
		{
			t[0] = FIELD.x + 3 + seeded.nextInt(FIELD.width - 6);
			t[1] = FIELD.y + 16 + seeded.nextInt(FIELD.height - 18);
		}
	}

	void render(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		renderField(g, s, mouse, boxes);
		renderIncubators(g, s, mouse, boxes);
	}

	// ---------------------------------------------------------------- field

	private void renderField(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		Shape oldClip = g.getClip();
		g.clip(FIELD);
		FarmTheme theme = farm.theme();
		drawGround(g, theme);

		// During a challenge (bunny hunt, Evil Chicken fight) the farm clears out so only the challenge is on screen
		FarmVisitors.ActiveEvent active = farm.getActiveEvent();
		if (active != null && active.isEngaged())
		{
			drawNight(g, theme);
			events.render(g, mouse, boxes);
			g.setClip(oldClip);
			return;
		}

		renderNest(g, s, mouse, boxes);
		renderPet(g, s, mouse, boxes);
		renderHens(g, s);
		drawNight(g, theme);
		renderLabels(g, s, mouse);
		events.render(g, mouse, boxes);
		renderToast(g);
		g.setClip(oldClip);
	}

	/**
	 * Grass, tufts and a fence along the back, coloured by the chosen farm look.
	 */
	private void drawGround(Graphics2D g, FarmTheme theme)
	{
		g.setColor(theme.getGrass());
		g.fill(FIELD);
		g.setColor(theme.getBackdrop());
		g.fillRect(FIELD.x, FIELD.y, FIELD.width, 14);
		if (theme.isNight())
		{
			g.setColor(new Color(255, 255, 220));
			for (int i = 0; i < 9; i++)
			{
				g.fillRect(FIELD.x + 7 + i * 25 + (i * 7) % 11, FIELD.y + 1 + (i * 5) % 3, 1, 1);
			}
		}
		g.setColor(theme.getTufts());
		for (int[] t : tufts)
		{
			g.drawLine(t[0], t[1], t[0] - 1, t[1] - 3);
			g.drawLine(t[0], t[1], t[0] + 1, t[1] - 3);
		}
		g.setColor(theme.getFence());
		g.fillRect(FIELD.x, FIELD.y + 4, FIELD.width, 2);
		g.fillRect(FIELD.x, FIELD.y + 9, FIELD.width, 2);
		for (int x = FIELD.x + 4; x < FIELD.x + FIELD.width; x += 18)
		{
			g.setColor(theme.getFence());
			g.fillRect(x, FIELD.y + 1, 3, 13);
			g.setColor(theme.getFenceDark());
			g.fillRect(x + 2, FIELD.y + 1, 1, 13);
		}
	}

	/**
	 * Moonlight over everything for the night look.
	 */
	private static void drawNight(Graphics2D g, FarmTheme theme)
	{
		if (theme.isNight())
		{
			g.setColor(new Color(10, 20, 60, 70));
			g.fill(FIELD);
		}
	}

	/**
	 * Flock counter and the rooster's blessing, top left of the field.
	 */
	private void renderLabels(Graphics2D g, FarmState s, Point mouse)
	{
		Rectangle flockLabel = pill(g, "Flock " + farm.henCount() + "/" + farm.henCapacity(), FIELD.x + 3, FIELD.y + 2);
		if (flockLabel.contains(mouse))
		{
			StringBuilder tip = new StringBuilder();
			for (HenType hen : HenType.values())
			{
				int n = s.hens[hen.ordinal()];
				if (n > 0)
				{
					tip.append(hen.getDisplayName()).append(" x").append(n);
					if (s.shiny[hen.ordinal()] > 0)
					{
						tip.append(" (").append(s.shiny[hen.ordinal()]).append(" shiny)");
					}
					tip.append("</br>");
				}
			}
			tip.append(String.format(Locale.ROOT, "%.1f eggs/hour", farm.layRatePerHour()));
			tooltip(tip.toString());
		}
		int pillY = FIELD.y + 17;
		if (s.freshStartTicks > 0)
		{
			long secs = Math.round(s.freshStartTicks * FarmManager.TICK_SECONDS);
			Rectangle fresh = pill(g, "2x speed " + FarmManager.formatDuration(secs), FIELD.x + 3, pillY);
			if (fresh.contains(mouse))
			{
				tooltip("Fresh start: hens lay and eggs hatch twice as fast");
			}
			pillY += fresh.height + 2;
		}
		if (s.blessingTicks > 0)
		{
			long secs = Math.round(s.blessingTicks * FarmManager.TICK_SECONDS);
			Rectangle blessing = pill(g, "2x laying " + FarmManager.formatDuration(secs), FIELD.x + 3, pillY);
			if (blessing.contains(mouse))
			{
				tooltip("Rooster's blessing: hens lay twice as fast");
			}
		}
	}

	private void renderToast(Graphics2D g)
	{
		if (!farm.isToastVisible())
		{
			return;
		}
		g.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics fm = g.getFontMetrics();
		String toast = farm.getToast();
		int w = fm.stringWidth(toast) + 10;
		int x = FIELD.x + (FIELD.width - 46 - w) / 2;
		int y = FIELD.y + FIELD.height - 17;
		g.setColor(new Color(0, 0, 0, 170));
		g.fillRoundRect(x, y, w, 14, 6, 6);
		text(g, toast, x + 5, y + 11, YELLOW);
	}

	// ---------------------------------------------------------------- coop (nest box)

	private void renderNest(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		int count = farm.nestCount();
		int cap = farm.nestCapacity();
		boolean hover = NEST.contains(mouse);

		if (count > 0)
		{
			// Gentle pulse to say "come collect me", faster when full
			double speed = count >= cap ? 120.0 : 250.0;
			float pulse = (float) (0.35 + 0.25 * Math.sin(System.currentTimeMillis() / speed));
			g.setColor(count >= cap ? new Color(1f, 0.5f, 0.2f, pulse) : new Color(1f, 1f, 0.4f, pulse));
			g.fillRoundRect(NEST.x - 2, NEST.y - 2, NEST.width + 4, 34, 8, 8);
		}
		BufferedImage coop = farm.theme().isGoldenCoop() ? sprites.goldenCoop() : sprites.coop();
		g.drawImage(coop, NEST.x, NEST.y, null);
		if (hover)
		{
			Composite old = g.getComposite();
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.25f));
			g.drawImage(coop, NEST.x, NEST.y, null);
			g.setComposite(old);
		}

		// Up to two eggs on each of the coop's shelves
		int[][] spots = {{3, 13}, {11, 13}, {25, 14}, {33, 14}};
		int shown = 0;
		for (EggType egg : EggType.inDisplayOrder())
		{
			for (int i = 0; i < s.nest[egg.ordinal()] && shown < spots.length; i++, shown++)
			{
				g.drawImage(sprites.smallEgg(egg), NEST.x + spots[shown][0], NEST.y + spots[shown][1], null);
			}
		}

		g.setFont(FontManager.getRunescapeSmallFont());
		String label = count >= cap ? "FULL" : count + "/" + cap;
		int w = g.getFontMetrics().stringWidth(label);
		int lx = NEST.x + (NEST.width - w) / 2;
		int ly = NEST.y + 32;
		g.setColor(new Color(0, 0, 0, 140));
		g.fillRoundRect(lx - 3, ly, w + 6, 13, 6, 6);
		text(g, label, lx, ly + 10, count >= cap ? YELLOW : TEXT);

		boxes.add(new HitBox(NEST, farm::collectNest));
		if (hover)
		{
			tooltip("Collect eggs" + (count >= cap ? "</br>Full: hens stop laying" : ""));
		}
	}

	private void renderPet(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		if (!s.rubberChicken)
		{
			return;
		}
		// Squash and bounce for a moment after a squeeze
		long since = System.currentTimeMillis() - farm.getLastSqueakMillis();
		int squash = since < 300 ? (int) (3 * Math.sin(since / 300.0 * Math.PI)) : 0;
		BufferedImage img = sprites.rubberChicken();
		g.setColor(new Color(0, 0, 0, 45));
		g.fillOval(PET.x + 1, PET.y + PET.height - 5, PET.width - 2, 5);
		g.drawImage(img, PET.x - squash / 2, PET.y + squash, img.getWidth() + squash, img.getHeight() - squash, null);
		boxes.add(new HitBox(PET, farm::squeak));
		if (PET.contains(mouse))
		{
			tooltip("Rubber chicken");
		}
	}

	// ---------------------------------------------------------------- flock

	private void renderHens(Graphics2D g, FarmState s)
	{
		syncFlock(s);

		long nowNanos = System.nanoTime();
		float dt = lastFrameNanos == 0 ? 0 : Math.min(0.1f, (nowNanos - lastFrameNanos) / 1e9f);
		lastFrameNanos = nowNanos;
		long now = System.currentTimeMillis();

		for (HenSprite hen : flock)
		{
			if (now < hen.pauseUntil)
			{
				continue;
			}
			float dx = hen.targetX - hen.x;
			float dy = hen.targetY - hen.y;
			float dist = (float) Math.sqrt(dx * dx + dy * dy);
			float step = HEN_SPEED * dt;
			if (dist <= step)
			{
				hen.x = hen.targetX;
				hen.y = hen.targetY;
				hen.pauseUntil = now + 1000 + random.nextInt(3500);
				pickTarget(hen);
			}
			else
			{
				hen.x += dx / dist * step;
				hen.y += dy / dist * step;
				hen.facingRight = dx > 0;
			}
		}

		List<HenSprite> sorted = new ArrayList<>(flock);
		sorted.sort(Comparator.comparingDouble(h -> h.y));
		for (HenSprite hen : sorted)
		{
			// Pecking bob while standing still
			int bob = now < hen.pauseUntil && ((now / 160 + hen.peckPhase) % 5 == 0) ? 1 : 0;
			BufferedImage img = sprites.hen(hen.type, hen.facingRight);
			int x = Math.round(hen.x);
			int y = Math.round(hen.y) + bob;
			g.setColor(new Color(0, 0, 0, 50));
			g.fillOval(x + 4, Math.round(hen.y) + HEN_H - 4, HEN_W - 6, 5);
			if (hen.shiny)
			{
				g.setColor(new Color(1f, 0.95f, 0.5f, 0.25f));
				g.fillOval(x - 2, y + 4, HEN_W + 4, HEN_H - 4);
			}
			g.drawImage(img, x, y, null);
			if (hen.shiny)
			{
				sparkles(g, x + HEN_W / 2, y + HEN_H / 2, 14, hen.peckPhase);
			}
		}
	}

	/**
	 * Keeps the drawn hens in line with the flock, shinies and best hens first, without resetting the ones already walking.
	 */
	private void syncFlock(FarmState s)
	{
		int types = HenType.values().length;
		int budget = config.maxHensDrawn();
		// index = type * 2 + (shiny ? 1 : 0)
		int[] wanted = new int[types * 2];
		for (int t = types - 1; t >= 0 && budget > 0; t--)
		{
			wanted[t * 2 + 1] = Math.min(budget, s.shiny[t]);
			budget -= wanted[t * 2 + 1];
		}
		for (int t = types - 1; t >= 0 && budget > 0; t--)
		{
			wanted[t * 2] = Math.min(budget, s.hens[t] - s.shiny[t]);
			budget -= wanted[t * 2];
		}

		int[] have = new int[wanted.length];
		for (HenSprite hen : flock)
		{
			have[key(hen)]++;
		}
		for (int k = 0; k < wanted.length; k++)
		{
			while (have[k] > wanted[k])
			{
				for (int i = flock.size() - 1; i >= 0; i--)
				{
					if (key(flock.get(i)) == k)
					{
						flock.remove(i);
						break;
					}
				}
				have[k]--;
			}
			while (have[k] < wanted[k])
			{
				HenSprite hen = new HenSprite();
				hen.type = HenType.values()[k / 2];
				hen.shiny = k % 2 == 1;
				hen.x = minX() + random.nextFloat() * (maxX() - minX());
				hen.y = minY() + random.nextFloat() * (maxY() - minY());
				hen.peckPhase = random.nextInt(5);
				hen.facingRight = random.nextBoolean();
				hen.pauseUntil = System.currentTimeMillis() + random.nextInt(2000);
				pickTarget(hen);
				flock.add(hen);
				have[k]++;
			}
		}
	}

	private static int key(HenSprite hen)
	{
		return hen.type.ordinal() * 2 + (hen.shiny ? 1 : 0);
	}

	private void pickTarget(HenSprite hen)
	{
		hen.targetX = Math.max(minX(), Math.min(maxX(), hen.x + (random.nextFloat() - 0.5f) * 90));
		hen.targetY = Math.max(minY(), Math.min(maxY(), hen.y + (random.nextFloat() - 0.5f) * 30));
	}

	// ---------------------------------------------------------------- incubators

	private void renderIncubators(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		EggType selected = EggType.values()[s.selectedEgg];
		for (int i = 0; i < MAX_SLOTS; i++)
		{
			Rectangle slot = slotRect(i);
			boolean hover = slot.contains(mouse);

			if (i >= s.incubators.size())
			{
				// Only point at the shop once there is a shop to point at
				boolean hint = i == s.incubators.size() && farm.isTabUnlocked(EggscapeOverlay.Tab.SHOP);
				renderLockedSlot(g, slot, hint, hover, boxes);
				continue;
			}

			FarmState.Incubator inc = s.incubators.get(i);
			g.setColor(hover ? BUTTON : INSET);
			g.fill(slot);
			g.setColor(PANEL_EDGE);
			g.drawRect(slot.x, slot.y, slot.width - 1, slot.height - 1);

			if (inc.egg < 0)
			{
				// Empty: a ghost of the selected egg shows what a click will put in
				Composite old = g.getComposite();
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, hover ? 0.8f : 0.3f));
				g.drawImage(sprites.egg(selected), slot.x + (SLOT_W - 15) / 2, slot.y + 3, null);
				g.setComposite(old);
				centeredAt(g, "Empty", slot.x + slot.width / 2, slot.y + 33, TEXT_DIM);
				final int index = i;
				boxes.add(new HitBox(slot, () -> farm.placeEgg(index)));
				if (hover)
				{
					tooltip("Incubate " + selected.getDisplayName().toLowerCase() + " (" + s.eggs[selected.ordinal()] + ")");
				}
				continue;
			}

			EggType egg = EggType.values()[inc.egg];
			double pct = Math.min(1, inc.progress / egg.getHatchSeconds());
			// Wobbles more and more as it gets close to hatching
			int wobble = pct > 0.85 && (System.currentTimeMillis() / 120) % 4 == 0 ? 1 : 0;
			if (pct > 0.95)
			{
				wobble = (int) Math.round(Math.sin(System.currentTimeMillis() / 50.0) * 1.5);
			}
			g.drawImage(sprites.egg(egg), slot.x + 4 + wobble, slot.y + 4, null);
			text(g, shortDuration(farm.secondsLeft(inc)), slot.x + 21, slot.y + 17, TEXT);

			Rectangle bar = new Rectangle(slot.x + 3, slot.y + SLOT_H - 9, SLOT_W - 6, 5);
			g.setColor(new Color(20, 16, 12));
			g.fill(bar);
			g.setColor(egg.getColor());
			g.fillRect(bar.x, bar.y, (int) (bar.width * pct), bar.height);

			// Swallow clicks on a busy slot
			boxes.add(new HitBox(slot, () ->
			{
			}));
		}
	}

	private void renderLockedSlot(Graphics2D g, Rectangle slot, boolean nextToUnlock, boolean hover, List<HitBox> boxes)
	{
		g.setColor(new Color(30, 26, 20, 200));
		g.fill(slot);
		g.setColor(PANEL_EDGE);
		g.drawRect(slot.x, slot.y, slot.width - 1, slot.height - 1);
		if (!nextToUnlock)
		{
			return;
		}
		int cx = slot.x + slot.width / 2;
		centeredAt(g, "Locked", cx, slot.y + 16, TEXT_DIM);
		centeredAt(g, "see Shop", cx, slot.y + 28, TEXT_DIM);
		boxes.add(new HitBox(slot, openShop));
		if (hover)
		{
			tooltip("Unlock in the Shop");
		}
	}
}

package com.eggscape;

import static com.eggscape.FarmManager.EGG_COLOR;
import java.awt.Color;
import java.time.LocalTime;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import lombok.Getter;

/**
 * Visitors that show up on the farm while you play, including the two challenges:
 * the Easter Bunny hunt and the Evil Chicken fight. Runs on the client thread.
 */
class FarmVisitors
{
	private static final int EVENT_MIN_TICKS = 1500;
	private static final int EVENT_EXTRA_TICKS = 1500;
	private static final int BLESSING_TICKS = 1000;
	private static final int EVENT_XP = 60;
	private static final double EASTER_BONUS_CHANCE = 0.03;

	static final int EVIL_CHICKEN_HP = 5;
	static final long EVIL_FIGHT_MS = 15_000;
	static final int HUNT_BUSHES = 5;
	static final int HUNT_CATCHES = 5;
	static final long HUNT_MS = 25_000;
	/**
	 * Title card with a 3-2-1 countdown before a challenge starts.
	 */
	static final long CHALLENGE_INTRO_MS = 3_000;

	private final FarmManager farm;
	private final Random random = new Random();

	@Getter
	private ActiveEvent active;

	/**
	 * The Easter Bunny minigame: it pops out of one bush at a time and you have to click it in time.
	 */
	static class Hunt
	{
		final long start;
		int catches;
		int peekBush = -1;
		int lastBush = -1;
		long peekStart;
		long peekMs;
		long nextPeek;

		/**
		 * @param start when the play part begins (after the intro)
		 */
		Hunt(long start)
		{
			this.start = start;
			this.nextPeek = start + 300;
		}
	}

	static class ActiveEvent
	{
		final FarmEvent type;
		/**
		 * Only for the Easter Bunny, once the hunt has started.
		 */
		Hunt hunt;
		/**
		 * When the player clicked to start the challenge (bunny hunt or Evil Chicken fight), 0 before that.
		 * The intro card shows first; the challenge itself starts at {@link #playStart()}.
		 */
		long engagedAt;
		/**
		 * Position in the field as a fraction (0-1) of the walkable area.
		 */
		float x, y;
		int ticksLeft;
		int duration;
		int hp;

		ActiveEvent(FarmEvent type)
		{
			this.type = type;
		}

		boolean isEngaged()
		{
			return engagedAt > 0;
		}

		long playStart()
		{
			return engagedAt + CHALLENGE_INTRO_MS;
		}

		boolean inIntro(long now)
		{
			return isEngaged() && now < playStart();
		}
	}

	FarmVisitors(FarmManager farm)
	{
		this.farm = farm;
	}

	/**
	 * Visitors leave when you log out; they are never saved.
	 */
	void clear()
	{
		active = null;
	}

	/**
	 * Once per game tick: counts down to the next visitor, or the current visitor's patience.
	 */
	void tick(FarmState state)
	{
		if (active != null)
		{
			if (active.isEngaged())
			{
				// A running challenge has its own clock (see updateChallenge)
				return;
			}
			if (--active.ticksLeft <= 0)
			{
				expire();
			}
			return;
		}
		if (!farm.getConfig().randomEvents() || --state.nextEventTicks > 0)
		{
			return;
		}
		double whistle = 1 - 0.15 * farm.featherLevel(FeatherUpgrade.BIRD_WHISTLE);
		state.nextEventTicks = (int) ((EVENT_MIN_TICKS + random.nextInt(EVENT_EXTRA_TICKS)) * whistle);

		ActiveEvent event = spawn(FarmEvent.roll(random, LocalTime.now().getHour()));
		event.x = random.nextFloat();
		event.y = random.nextFloat();
		event.duration = (int) (event.type.getDurationTicks() * (1 + 0.25 * farm.featherLevel(FeatherUpgrade.PATIENT_VISITORS)));
		event.ticksLeft = event.duration;
		farm.showToast(event.type.getDisplayName() + "!");
	}

	/**
	 * Starts a visitor right away (also used by the developer test command).
	 */
	ActiveEvent spawn(FarmEvent type)
	{
		ActiveEvent event = new ActiveEvent(type);
		event.x = 0.4f;
		event.y = 0.5f;
		event.duration = type.getDurationTicks();
		event.ticksLeft = event.duration;
		event.hp = type == FarmEvent.EVIL_CHICKEN ? EVIL_CHICKEN_HP : 1;
		active = event;
		farm.playEventSound();
		farm.chat(type.getSpawnMessage());
		return event;
	}

	void click()
	{
		ActiveEvent event = active;
		FarmState state = farm.getState();
		if (state == null || event == null)
		{
			return;
		}

		String message;
		switch (event.type)
		{
			case GOLDEN_EGG:
			{
				if (random.nextDouble() < EASTER_BONUS_CHANCE)
				{
					farm.giveEgg(EggType.EASTER, 1);
					farm.gotEasterEgg("inside the golden egg");
					message = "The golden egg cracked open. There was an Easter egg inside!";
					break;
				}
				EggType egg = farm.rollColouredEgg(0.07, 0.28);
				farm.giveEgg(egg, 1);
				farm.popup("+1", egg.getColor(), FarmManager.Anchor.EGG_BAR, egg.ordinal());
				message = "The golden egg cracked open. There was a " + egg.getDisplayName().toLowerCase() + " inside!";
				break;
			}
			case EASTER_BASKET:
			{
				StringBuilder found = new StringBuilder();
				for (int i = 0; i < 3; i++)
				{
					EggType egg = farm.rollColouredEgg(0.15, 0.35);
					farm.giveEgg(egg, 1);
					farm.popup("+1", egg.getColor(), FarmManager.Anchor.EGG_BAR, egg.ordinal());
					found.append(i == 0 ? "" : i == 2 ? " and a " : ", a ").append(egg.getDisplayName().toLowerCase());
				}
				message = "The Easter basket held a " + found + "!";
				if (random.nextDouble() < 0.15)
				{
					farm.giveEgg(EggType.EASTER, 1);
					farm.gotEasterEgg("in the Easter basket");
					message += " And at the bottom... an Easter egg!";
				}
				break;
			}
			case EASTER_BUNNY:
			{
				if (!event.isEngaged())
				{
					event.engagedAt = System.currentTimeMillis();
					event.hunt = new Hunt(event.playStart());
				}
				return;
			}
			case UNDEAD_CHICKEN:
			{
				farm.giveEgg(EggType.CURSED, 1);
				farm.popup("+1", EggType.CURSED.getColor(), FarmManager.Anchor.EGG_BAR, EggType.CURSED.ordinal());
				message = "You laid the Undead chicken to rest. It left a Cursed egg behind...";
				break;
			}
			case EGG_BASKET:
			{
				int eggs = eventEggs(5 + random.nextInt(11) + farm.henCount() / 2);
				farm.giveEgg(EggType.PLAIN, eggs);
				farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.FIELD, 0);
				message = "The basket held " + eggs + " eggs!";
				break;
			}
			case ROOSTER:
			{
				state.blessingTicks = BLESSING_TICKS;
				farm.popup("2x laying!", EGG_COLOR, FarmManager.Anchor.FIELD, 0);
				message = "The rooster crows proudly. Your hens lay twice as fast for 10 minutes!";
				if (random.nextDouble() < 0.15)
				{
					String extra = farm.addHen(HenType.SILVER, false);
					message += " A Silver hen followed the rooster and joined your flock!" + (extra != null ? " " + extra : "");
				}
				break;
			}
			case EVIL_CHICKEN:
			{
				long now = System.currentTimeMillis();
				if (!event.isEngaged())
				{
					// First click starts the fight (after the intro card)
					event.engagedAt = now;
					return;
				}
				if (event.inIntro(now))
				{
					return;
				}
				if (--event.hp > 0)
				{
					// It hops away to make you chase it
					event.x = random.nextFloat();
					event.y = random.nextFloat();
					farm.popup("Bok!", new Color(255, 90, 70), FarmManager.Anchor.FIELD, 0);
					return;
				}
				int eggs = eventEggs(10 + random.nextInt(11));
				farm.giveEgg(EggType.PLAIN, eggs);
				farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.FIELD, 0);
				message = "You chased off the Evil Chicken! It dropped " + eggs + " eggs while fleeing.";
				if (random.nextDouble() < 0.2)
				{
					String extra = farm.addHen(HenType.EVIL, false);
					message += " One of its Evil hens decided to stay!" + (extra != null ? " " + extra : "");
				}
				break;
			}
			default:
				return;
		}

		active = null;
		won(state, event.type, EVENT_XP);
		farm.showToast(event.type.getDisplayName() + " complete!");
		farm.chat(message);
		farm.save();
	}

	private void won(FarmState state, FarmEvent type, int xp)
	{
		state.eventWins[type.ordinal()]++;
		farm.getDaily().progress(TaskType.EVENTS, 1);
		farm.addFarmXp(xp, true);
	}

	private void expire()
	{
		FarmEvent type = active.type;
		active = null;
		String message;
		switch (type)
		{
			case GOLDEN_EGG:
				message = "The golden egg rolled away...";
				break;
			case EGG_BASKET:
				message = "Someone else took the egg basket.";
				break;
			case ROOSTER:
				message = "The rooster wandered off.";
				break;
			case EASTER_BASKET:
				message = "The Easter basket vanished as quickly as it appeared...";
				break;
			case UNDEAD_CHICKEN:
				message = "The Undead chicken faded back into the night.";
				break;
			case EASTER_BUNNY:
				message = "The Easter Bunny hopped away before you noticed it.";
				break;
			case EVIL_CHICKEN:
				message = "The Evil Chicken escaped with " + stealEggs() + " of your eggs!";
				break;
			default:
				return;
		}
		farm.chat(message);
	}

	// ---------------------------------------------------------------- challenges

	/**
	 * Moves a running challenge along. Called every frame by the overlay, because the bunny's peeks are
	 * shorter than a game tick.
	 */
	void updateChallenge()
	{
		ActiveEvent event = active;
		if (farm.getState() == null || event == null || !event.isEngaged())
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (event.type == FarmEvent.EVIL_CHICKEN)
		{
			if (now > event.playStart() + EVIL_FIGHT_MS)
			{
				expire();
			}
			return;
		}
		Hunt hunt = event.hunt;
		if (hunt == null || now < hunt.start)
		{
			// Still showing the intro card
			return;
		}
		if (now - hunt.start > HUNT_MS)
		{
			finishHunt(false);
			return;
		}
		if (hunt.peekBush >= 0 && now > hunt.peekStart + hunt.peekMs)
		{
			hunt.peekBush = -1;
			hunt.nextPeek = now + 250 + random.nextInt(450);
		}
		if (hunt.peekBush < 0 && now >= hunt.nextPeek)
		{
			int bush = random.nextInt(HUNT_BUSHES - 1);
			if (bush >= hunt.lastBush && hunt.lastBush >= 0)
			{
				bush++;
			}
			hunt.peekBush = bush;
			hunt.lastBush = bush;
			hunt.peekStart = now;
			// It gets quicker with every catch
			hunt.peekMs = Math.max(550, 1300 - 160L * hunt.catches);
		}
	}

	void clickBush(int bush)
	{
		ActiveEvent event = active;
		if (farm.getState() == null || event == null || event.hunt == null || event.inIntro(System.currentTimeMillis()))
		{
			return;
		}
		Hunt hunt = event.hunt;
		if (hunt.peekBush != bush)
		{
			farm.popup("Too slow!", new Color(200, 200, 200), FarmManager.Anchor.FIELD, 0);
			return;
		}
		hunt.catches++;
		hunt.peekBush = -1;
		hunt.nextPeek = System.currentTimeMillis() + 350;
		farm.popup(hunt.catches >= HUNT_CATCHES ? "Caught!" : "Gotcha! " + hunt.catches + "/" + HUNT_CATCHES, EGG_COLOR,
			FarmManager.Anchor.FIELD, 0);
		if (hunt.catches >= HUNT_CATCHES)
		{
			finishHunt(true);
		}
	}

	private void finishHunt(boolean caught)
	{
		Hunt hunt = active.hunt;
		active = null;
		if (!caught)
		{
			int eggs = eventEggs(hunt.catches * 5);
			if (eggs > 0)
			{
				farm.giveEgg(EggType.PLAIN, eggs);
				farm.popup("+" + eggs, EGG_COLOR, FarmManager.Anchor.EGG_BAR, EggType.PLAIN.ordinal());
			}
			farm.chat("The Easter Bunny got away! You caught it " + hunt.catches + " of " + HUNT_CATCHES + " times"
				+ (eggs > 0 ? " and it dropped " + eggs + " eggs." : "."));
			return;
		}

		won(farm.getState(), FarmEvent.EASTER_BUNNY, EVENT_XP * 2);

		// The prize: a Giant easter egg, cracked open on the spot
		int plain = eventEggs(20 + random.nextInt(21));
		farm.giveEgg(EggType.PLAIN, plain);
		farm.popup("+" + plain, EGG_COLOR, FarmManager.Anchor.EGG_BAR, EggType.PLAIN.ordinal());
		int[] coloured = new int[EggType.values().length];
		int count = 3 + random.nextInt(3);
		for (int i = 0; i < count; i++)
		{
			coloured[farm.rollColouredEgg(0.12, 0.33).ordinal()]++;
		}
		StringBuilder loot = new StringBuilder(plain + " eggs");
		for (EggType egg : EggType.values())
		{
			int n = coloured[egg.ordinal()];
			if (n > 0)
			{
				farm.giveEgg(egg, n);
				farm.popup("+" + n, egg.getColor(), FarmManager.Anchor.EGG_BAR, egg.ordinal());
				loot.append(", ").append(n).append(' ').append(egg.getDisplayName().toLowerCase()).append(n == 1 ? "" : "s");
			}
		}
		boolean easter = random.nextDouble() < 0.12;
		List<String> lines = new ArrayList<>();
		lines.add("You caught the Easter Bunny!");
		lines.add("Inside its Giant easter egg: " + loot + ".");
		if (easter)
		{
			farm.giveEgg(EggType.EASTER, 1);
			lines.add("And an Easter egg!");
		}
		farm.showDialogFirst(new FarmManager.Dialog("Giant easter egg!", lines, "Hooray!", null, null).image(Sprites.GIANT_EASTER_EGG));
		if (easter)
		{
			farm.gotEasterEgg("inside the Giant easter egg");
		}
		farm.save();
	}

	private int eventEggs(int base)
	{
		return (int) Math.round(base * (1 + 0.25 * farm.featherLevel(FeatherUpgrade.BIG_BASKETS)));
	}

	private int stealEggs()
	{
		FarmState state = farm.getState();
		int nest = state.nest[EggType.PLAIN.ordinal()];
		if (nest > 0)
		{
			int stolen = Math.min(nest, 3 + nest / 2);
			state.nest[EggType.PLAIN.ordinal()] -= stolen;
			return stolen;
		}
		int stolen = (int) Math.min(state.eggs[EggType.PLAIN.ordinal()], 5);
		state.eggs[EggType.PLAIN.ordinal()] -= stolen;
		return stolen;
	}
}

package com.eggscape;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Permanent upgrades bought with Golden Feathers; they survive selling the farm. Saved by ordinal.
 */
@Getter
@RequiredArgsConstructor
public enum FeatherUpgrade
{
	HEAD_START("Head start", "New farms start with 2 more hens and 25 eggs", 10, 1, 1.5),
	NIGHT_SHIFT("Night shift", "Offline progress 10% faster", 5, 2, 1.6),
	BIRD_WHISTLE("Bird whistle", "Farm events show up 15% more often", 4, 2, 1.7),
	LUCKY_CHARM("Lucky charm", "+2% chance to hatch a better hen", 10, 3, 1.6),
	WARM_START("Warm start", "New farms start with an extra incubator", 3, 4, 2.0),
	SHINY_CHARM("Shiny charm", "Shiny chicks 25% more likely", 4, 5, 1.8),
	PATIENT_VISITORS("Patient visitors", "Farm events stay 25% longer", 4, 3, 1.7),
	BIG_BASKETS("Big baskets", "Eggs from farm events +25%", 4, 3, 1.8);

	private final String displayName;
	private final String description;
	private final int maxLevel;
	private final int baseCost;
	private final double costGrowth;

	public int cost(int level)
	{
		return (int) Math.round(baseCost * Math.pow(costGrowth, level));
	}
}

package com.eggscape;

import static com.eggscape.Layout.ROWS_PER_PAGE;
import static com.eggscape.Layout.listRow;
import static com.eggscape.Layout.pages;
import static com.eggscape.Ui.DONE;
import static com.eggscape.Ui.GOLD;
import static com.eggscape.Ui.INSET;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.compact;
import static com.eggscape.Ui.medal;
import static com.eggscape.Ui.text;
import static com.eggscape.Ui.withAlpha;
import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Achievements: tracks that level up through the OSRS metals, then the one-off goals.
 */
@Singleton
class GoalsTab extends PanelPart
{
	private int page;

	@Inject
	GoalsTab(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	void render(Graphics2D g, Point mouse, List<HitBox> boxes)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		AchievementTrack[] tracks = AchievementTrack.values();
		Achievement[] oneOffs = Achievement.values();
		int items = tracks.length + oneOffs.length;
		int pages = pages(items);
		page = Math.max(0, Math.min(pages - 1, page));

		// Every tier counts as one achievement in the total
		int done = 0;
		for (AchievementTrack t : tracks)
		{
			done += farm.trackTier(t);
		}
		for (Achievement a : oneOffs)
		{
			done += farm.isAchieved(a) ? 1 : 0;
		}
		text(g, done + "/" + (tracks.length * AchievementTier.values().length + oneOffs.length), 6, 56, TEXT);
		pager(g, mouse, boxes, page, pages, 44, p -> page = p);

		for (int i = 0; i < ROWS_PER_PAGE; i++)
		{
			int index = page * ROWS_PER_PAGE + i;
			if (index >= items)
			{
				break;
			}
			Rectangle row = listRow(i);
			if (index < tracks.length)
			{
				renderTrackRow(g, tracks[index], row, mouse);
			}
			else
			{
				renderOneOffRow(g, oneOffs[index - tracks.length], row, mouse);
			}
		}
	}

	private void renderTrackRow(Graphics2D g, AchievementTrack track, Rectangle row, Point mouse)
	{
		AchievementTier[] tiers = AchievementTier.values();
		int tier = farm.trackTier(track);
		boolean maxed = tier >= tiers.length;
		long progress = track.progress(farm);
		AchievementTier current = tier > 0 ? tiers[tier - 1] : null;
		AchievementTier next = maxed ? null : tiers[tier];

		g.setColor(INSET);
		g.fill(row);
		if (!maxed)
		{
			// Progress towards the next metal, in that metal's colour
			long from = tier > 0 ? track.getTargets()[tier - 1] : 0;
			long to = track.getTargets()[tier];
			double pct = Math.max(0, Math.min(1, (progress - from) / (double) (to - from)));
			g.setColor(withAlpha(next.getColor(), 0.35f));
			g.fillRect(row.x, row.y, (int) (row.width * pct), row.height);
		}
		else
		{
			// Dragon: a gold frame around the row
			g.setColor(GOLD);
			g.drawRect(row.x, row.y, row.width - 1, row.height - 1);
		}

		medal(g, row.x + 4, row.y + 4, current);
		text(g, track.getDisplayName(), row.x + 18, row.y + 13, maxed ? YELLOW : TEXT);
		String right = maxed ? "Dragon" : compact(progress) + "/" + compact(track.getTargets()[tier]);
		int rw = g.getFontMetrics().stringWidth(right);
		text(g, right, row.x + row.width - rw - 16, row.y + 13, maxed ? YELLOW : TEXT_DIM);
		if (!maxed)
		{
			medal(g, row.x + row.width - 13, row.y + 4, next);
		}

		if (row.contains(mouse))
		{
			// Every metal at a glance: done in green, next in yellow
			StringBuilder tip = new StringBuilder(track.getDisplayName());
			for (AchievementTier t : tiers)
			{
				boolean got = t.ordinal() < tier;
				tip.append("</br>").append(got ? "<col=00ff00>" : t == next ? "<col=ffff00>" : "<col=a0a0a0>")
					.append(t.getDisplayName()).append(": ").append(track.describe(t)).append("</col>");
			}
			tooltip(tip.toString());
		}
	}

	private void renderOneOffRow(Graphics2D g, Achievement a, Rectangle row, Point mouse)
	{
		boolean achieved = farm.isAchieved(a);
		long progress = a.progress(farm);

		g.setColor(achieved ? DONE : INSET);
		g.fill(row);
		if (!achieved && progress > 0)
		{
			g.setColor(new Color(90, 75, 40, 160));
			g.fillRect(row.x, row.y, (int) (row.width * progress / (double) a.getTarget()), row.height);
		}
		text(g, a.getDisplayName(), row.x + 18, row.y + 13, achieved ? YELLOW : TEXT);
		String right = achieved ? "Done" : progress + "/" + a.getTarget();
		int rw = g.getFontMetrics().stringWidth(right);
		text(g, right, row.x + row.width - rw - 5, row.y + 13, achieved ? YELLOW : TEXT_DIM);
		// One-offs get a little egg instead of a medal
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, achieved ? 1f : 0.35f));
		g.drawImage(sprites.smallEgg(EggType.PLAIN), row.x + 4, row.y + 2, 9, 13, null);
		g.setComposite(old);

		if (row.contains(mouse))
		{
			tooltip(a.getDescription());
		}
	}
}

