package com.eggscape;

import java.awt.Rectangle;

/**
 * Where everything sits in the panel. Coordinates are relative to the content area under the header.
 */
final class Layout
{
	static final int WIDTH = 232;
	static final int HEIGHT = 160;

	static final Rectangle FIELD = new Rectangle(4, 44, 224, 72);
	/**
	 * The coop doubles as the nest box; laid eggs sit on its two shelves.
	 */
	static final Rectangle NEST = new Rectangle(FIELD.x + FIELD.width - 50, FIELD.y + FIELD.height - 49, 48, 49);
	/**
	 * Where the Rubber chicken pet lies in the grass.
	 */
	static final Rectangle PET = new Rectangle(FIELD.x + 128, FIELD.y + FIELD.height - 21, 18, 18);
	/**
	 * Bushes the Easter Bunny hides behind: x, y of the bush's bottom centre.
	 */
	static final int[][] BUSHES = {
		{FIELD.x + 32, FIELD.y + 70}, {FIELD.x + 72, FIELD.y + 70}, {FIELD.x + 112, FIELD.y + 70},
		{FIELD.x + 152, FIELD.y + 70}, {FIELD.x + 192, FIELD.y + 70}
	};
	/**
	 * Everything below the header; a dialog card blocks clicks on all of it.
	 */
	static final Rectangle CONTENT = new Rectangle(0, 21, WIDTH, HEIGHT - 21);

	static final int HEN_W = 25;
	static final int HEN_H = 34;

	static final int SLOT_Y = 120;
	static final int SLOT_W = 53;
	static final int SLOT_H = 36;
	static final int MAX_SLOTS = Upgrade.INCUBATOR.getMaxLevel() + 1;

	static final int ROWS_PER_PAGE = 5;
	private static final int LIST_Y = 61;

	private Layout()
	{
	}

	/**
	 * Egg bar cell {@code index} of {@code count}, spread over the full content width with 2px gaps.
	 */
	static Rectangle eggCell(int index, int count)
	{
		int x = 4 + Math.round(index * (WIDTH - 8 + 2) / (float) count);
		int next = 4 + Math.round((index + 1) * (WIDTH - 8 + 2) / (float) count);
		return new Rectangle(x, 22, next - x - 2, 19);
	}

	static Rectangle slotRect(int index)
	{
		return new Rectangle(4 + index * (SLOT_W + 4), SLOT_Y, SLOT_W, SLOT_H);
	}

	static int pages(int items)
	{
		return Math.max(1, (items + ROWS_PER_PAGE - 1) / ROWS_PER_PAGE);
	}

	/**
	 * Row {@code i} of a list (shop, goals).
	 */
	static Rectangle listRow(int i)
	{
		return new Rectangle(4, LIST_Y + i * 19, WIDTH - 8, 18);
	}

	/**
	 * The button on the right of a list row.
	 */
	static Rectangle buyButton(Rectangle row)
	{
		return new Rectangle(row.x + row.width - 64, row.y + 1, 62, 16);
	}

	/**
	 * Collection log tile; eight fit in a row.
	 */
	static Rectangle logTileRect(int index, int y)
	{
		return new Rectangle(4 + index * 28, y, 26, 44);
	}

	// Walkable area of the field (hens and visitors stay left of the coop)

	static float minX()
	{
		return FIELD.x + 2;
	}

	static float maxX()
	{
		return NEST.x - HEN_W - 2;
	}

	static float minY()
	{
		return FIELD.y + 4;
	}

	static float maxY()
	{
		return FIELD.y + FIELD.height - HEN_H - 1;
	}
}

