/**
 * The collection log: hens and eggs on page 1, shinies, the pet and stats on page 2.
 */
@Singleton
class LogTab extends PanelPart
{
	private int page;

	@Inject
	LogTab(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	void render(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		page = Math.max(0, Math.min(1, page));
		if (page == 0)
		{
			renderCollection(g, s, mouse);
		}
		else
		{
			renderExtras(g, s, mouse);
		}
		pager(g, mouse, boxes, page, 2, 140, p -> page = p);
	}

	private void renderCollection(Graphics2D g, FarmState s, Point mouse)
	{
		for (HenType hen : HenType.values())
		{
			Rectangle tile = logTileRect(hen.ordinal(), 44);
			long count = s.hensObtained[hen.ordinal()];
			int mastery = farm.mastery(hen);
			long next = FarmManager.masteryTarget(mastery);
			tile(g, tile, sprites.tileHen(hen, count > 0), count, false, mouse,
				count > 0 ? hen.getDisplayName() + "</br>" + (int) hen.getEggsPerHour() + " eggs/hour"
					+ (mastery > 0 ? "</br>Mastery " + mastery + ": +" + mastery * FarmManager.MASTERY_BONUS_PERCENT + "% laying" : "")
					+ (next > 0 ? "</br>Next mastery: " + QuantityFormatter.formatNumber(s.henEggsLaid[hen.ordinal()])
					+ "/" + QuantityFormatter.formatNumber(next) + " eggs" : "")
					: "???</br>" + howToGet(hen));
			if (mastery > 0)
			{
				// Small mastery star in the corner; the details live in the tooltip
				g.setFont(FontManager.getRunescapeSmallFont());
				masteryStar(g, tile.x + 2, tile.y + 2, mastery >= 10);
				text(g, String.valueOf(mastery), tile.x + 11, tile.y + 11, mastery >= 10 ? GOLD : TEXT);
			}
		}
		for (EggType egg : EggType.inDisplayOrder())
		{
			Rectangle tile = logTileRect(egg.displayIndex(), 91);
			long count = s.eggsObtained[egg.ordinal()];
			tile(g, tile, sprites.tileEgg(egg, count > 0), count, egg == EggType.EASTER && count > 0, mouse,
				count > 0 ? egg.getDisplayName() : "???</br>" + (egg == EggType.EASTER ? "Super rare"
					: egg == EggType.CURSED ? "Undead chickens drop these" : "Find one while playing"));
		}
		long golden = s.eventWins[FarmEvent.GOLDEN_EGG.ordinal()];
		tile(g, logTileRect(EggType.values().length, 91), sprites.goldenEgg(golden > 0), golden, false, mouse,
			golden > 0 ? "Golden egg" : "???</br>A farm visitor");

		// How much of the log is filled
		Rectangle summary = logTileRect(EggType.values().length + 1, 91);
		g.setColor(INSET);
		g.fill(summary);
		long have = farm.collectionProgress();
		g.setFont(FontManager.getRunescapeBoldFont());
		String n = String.valueOf(have);
		text(g, n, summary.x + (summary.width - g.getFontMetrics().stringWidth(n)) / 2, summary.y + 18,
			have >= FarmManager.COLLECTION_SIZE ? YELLOW : TEXT);
		g.setFont(FontManager.getRunescapeSmallFont());
		String total = "of " + FarmManager.COLLECTION_SIZE;
		text(g, total, summary.x + (summary.width - g.getFontMetrics().stringWidth(total)) / 2, summary.y + 33, TEXT_DIM);
	}

	private void renderExtras(Graphics2D g, FarmState s, Point mouse)
	{
		for (HenType hen : HenType.values())
		{
			Rectangle tile = logTileRect(hen.ordinal(), 44);
			long count = s.shinyObtained[hen.ordinal()];
			tile(g, tile, sprites.tileHen(hen, count > 0), count, count > 0, mouse,
				count > 0 ? "Shiny " + hen.getDisplayName() : "???</br>A rare shiny hen");
		}
		// The pet gets its own tile, the stats sit next to it
		tile(g, logTileRect(0, 91), sprites.rubberChicken(s.rubberChicken), s.rubberChicken ? 1 : 0, s.rubberChicken, mouse,
			s.rubberChicken ? "Rubber chicken (pet)" : "???</br>A rare pet from killing chickens");

		long eggsTotal = 0;
		for (long c : s.eggsObtained)
		{
			eggsTotal += c;
		}
		// Kept short so the lines stay clear of the pager in the bottom right
		int x = 36;
		text(g, "Farm level " + farm.farmLevel() + "  (" + QuantityFormatter.formatNumber(s.farmXp) + " xp)", x, 102, TEXT);
		text(g, "Eggs: " + compact(eggsTotal) + "   Kills: " + s.chickensKilled + "   Events: " + farm.eventsCompleted(), x, 114, TEXT_DIM);
		text(g, "Hatched: " + compact(s.hatchedTotal) + "   Tasks: " + s.tasksCompleted, x, 126, TEXT_DIM);
		text(g, "Streak: " + s.bestStreak + "   Feathers: " + s.feathersEarned, x, 138, TEXT_DIM);
		text(g, "Prestige: " + s.prestiges, x, 150, TEXT_DIM);
	}

	private static String howToGet(HenType hen)
	{
		switch (hen)
		{
			case EVIL:
			case SILVER:
				return "Joins through a farm visitor";
			case EASTER:
				return "Hatches from an Easter egg";
			case UNDEAD:
				return "Hatches from a Cursed egg";
			default:
				return "Hatch it from an egg";
		}
	}

	private void tile(Graphics2D g, Rectangle tile, BufferedImage img, long count, boolean shiny, Point mouse, String tip)
	{
		boolean hover = tile.contains(mouse);
		g.setColor(hover ? BUTTON : INSET);
		g.fill(tile);
		g.setColor(count > 0 ? (shiny ? GOLD : PANEL_INNER) : PANEL_EDGE);
		g.drawRect(tile.x, tile.y, tile.width - 1, tile.height - 1);
		g.drawImage(img, tile.x + (tile.width - img.getWidth()) / 2, tile.y + 3, null);
		if (shiny)
		{
			sparkles(g, tile.x + tile.width / 2, tile.y + 16, 11, tile.x);
		}
		String label = count > 0 ? QuantityFormatter.quantityToStackSize(count) : "?";
		text(g, label, tile.x + (tile.width - g.getFontMetrics().stringWidth(label)) / 2, tile.y + tile.height - 4,
			count > 0 ? YELLOW : TEXT_DIM);
		if (hover)
		{
			tooltip(tip);
		}
	}
}

package com.eggscape;

import static com.eggscape.Layout.WIDTH;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.arrowButton;
import static com.eggscape.Ui.text;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import java.util.function.IntConsumer;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * Base for the parts of the panel (farm view, tabs, dialogs): access to the farm, sprites and tooltips.
 */
abstract class PanelPart
{
	protected final FarmManager farm;
	protected final Sprites sprites;
	private final TooltipManager tooltipManager;

	PanelPart(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		this.farm = farm;
		this.sprites = sprites;
		this.tooltipManager = tooltipManager;
	}

	protected void tooltip(String text)
	{
		tooltipManager.add(new Tooltip(text));
	}

	/**
	 * Golden Feather icon, 9x13.
	 */
	protected void drawFeather(Graphics2D g, int x, int y)
	{
		g.drawImage(sprites.feather(), x, y, null);
	}

	/**
	 * Page arrows with "1/3" between them, in the top right of a list.
	 */
	protected void pager(Graphics2D g, Point mouse, List<HitBox> boxes, int page, int pages, int y, IntConsumer setPage)
	{
		if (pages <= 1)
		{
			return;
		}
		Rectangle prev = new Rectangle(WIDTH - 74, y, 16, 14);
		Rectangle next = new Rectangle(WIDTH - 20, y, 16, 14);
		arrowButton(g, prev, true, prev.contains(mouse), page > 0);
		arrowButton(g, next, false, next.contains(mouse), page < pages - 1);
		g.setFont(FontManager.getRunescapeSmallFont());
		String label = (page + 1) + "/" + pages;
		text(g, label, WIDTH - 39 - g.getFontMetrics().stringWidth(label) / 2, y + 12, TEXT_DIM);
		boxes.add(new HitBox(prev, () -> setPage.accept(Math.max(0, page - 1))));
		boxes.add(new HitBox(next, () -> setPage.accept(Math.min(pages - 1, page + 1))));
	}
}

package com.eggscape;

import static com.eggscape.Layout.ROWS_PER_PAGE;
import static com.eggscape.Layout.buyButton;
import static com.eggscape.Layout.listRow;
import static com.eggscape.Layout.pages;
import static com.eggscape.Ui.BUTTON;
import static com.eggscape.Ui.BUTTON_ACTIVE;
import static com.eggscape.Ui.BUTTON_HOVER;
import static com.eggscape.Ui.GOLD;
import static com.eggscape.Ui.INSET;
import static com.eggscape.Ui.PANEL_EDGE;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.buttonLabel;
import static com.eggscape.Ui.buyButtonBack;
import static com.eggscape.Ui.compact;
import static com.eggscape.Ui.text;
import java.awt.Color;
