import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * The Shop tab: upgrades for eggs, and later the egg trade, Golden Feathers and farm looks.
 */
@Singleton
class ShopTab extends PanelPart
{
	@RequiredArgsConstructor
	enum Page
	{
		UPGRADES("Upgrades"),
		TRADE("Egg trade"),
		FEATHERS("Golden Feathers"),
		LOOKS("Farm looks");

		private final String title;
	}

	private Page page = Page.UPGRADES;
	private int listPage;

	@Inject
	ShopTab(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	/**
	 * Opens the shop on its upgrades (used by the locked incubator slot).
	 */
	void showUpgrades()
	{
		page = Page.UPGRADES;
		listPage = 0;
	}

	void render(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		List<Page> pages = availablePages();
		if (!pages.contains(page))
		{
			page = Page.UPGRADES;
		}

		// Icon buttons for the shop's pages, only once there is more than one
		if (pages.size() > 1)
		{
			for (int i = 0; i < pages.size(); i++)
			{
				Page p = pages.get(i);
				Rectangle r = new Rectangle(4 + i * 22, 44, 20, 14);
				g.setColor(page == p ? BUTTON_ACTIVE : r.contains(mouse) ? BUTTON_HOVER : BUTTON);
				g.fill(r);
				g.setColor(PANEL_EDGE);
				g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
				pageIcon(g, p, r.x + 5, r.y + 1);
				boxes.add(new HitBox(r, () ->
				{
					page = p;
					listPage = 0;
				}));
				if (r.contains(mouse))
				{
					tooltip(p.title);
				}
			}
		}
		int titleX = pages.size() > 1 ? 6 + pages.size() * 22 : 6;
		if (page == Page.FEATHERS)
		{
			// Wallet instead of a title, the pager needs the room on the right
			drawFeather(g, titleX, 44);
			text(g, compact(s.feathers), titleX + 12, 55, GOLD);
		}
		else
		{
			text(g, page.title, titleX, 55, TEXT);
		}

		switch (page)
		{
			case UPGRADES:
				renderUpgrades(g, s, mouse, boxes);
				break;
			case TRADE:
				renderTrade(g, s, mouse, boxes);
				break;
			case FEATHERS:
				renderFeathers(g, s, mouse, boxes);
				break;
			case LOOKS:
				renderLooks(g, mouse, boxes);
				break;
		}
	}

	private List<Page> availablePages()
	{
		List<Page> pages = new ArrayList<>();
		pages.add(Page.UPGRADES);
		if (farm.isTradeUnlocked())
		{
			pages.add(Page.TRADE);
		}
		if (farm.isFeathersUnlocked())
		{
			pages.add(Page.FEATHERS);
		}
		if (farm.isLooksUnlocked())
		{
			pages.add(Page.LOOKS);
		}
		return pages;
	}

	private void pageIcon(Graphics2D g, Page p, int x, int y)
	{
		switch (p)
		{
			case UPGRADES:
				g.drawImage(sprites.smallEgg(EggType.PLAIN), x - 1, y - 1, 10, 13, null);
				break;
			case FEATHERS:
				g.drawImage(sprites.feather(), x, y - 1, 9, 13, null);
				break;
			case TRADE:
				g.drawImage(sprites.smallEgg(EggType.GREEN), x - 3, y + 1, 8, 11, null);
				g.drawImage(sprites.smallEgg(EggType.BLUE), x + 4, y - 1, 8, 11, null);
				break;
			case LOOKS:
				g.drawImage(sprites.smallHen(), x - 2, y - 2, 11, 15, null);
				break;
		}
	}

	// ---------------------------------------------------------------- upgrades

	private void renderUpgrades(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		// Upgrades that need a higher Farm level stay hidden until then
		List<Upgrade> all = new ArrayList<>();
		for (Upgrade u : Upgrade.values())
		{
			if (farm.farmLevel() >= u.getMinFarmLevel())
			{
				all.add(u);
			}
		}
		int pages = pages(all.size());
		listPage = Math.max(0, Math.min(pages - 1, listPage));
		pager(g, mouse, boxes, listPage, pages, 44, p -> listPage = p);

		long eggs = s.eggs[EggType.PLAIN.ordinal()];
		for (int i = 0; i < ROWS_PER_PAGE; i++)
		{
			int index = listPage * ROWS_PER_PAGE + i;
			if (index >= all.size())
			{
				break;
			}
			Upgrade upgrade = all.get(index);
			Rectangle row = listRow(i);
			g.setColor(INSET);
			g.fill(row);
			int level = farm.level(upgrade);
			boolean maxed = level >= upgrade.getMaxLevel();
			long cost = maxed ? 0 : upgrade.cost(level);
			boolean affordable = !maxed && eggs >= cost;

			text(g, upgrade.getDisplayName(), row.x + 5, row.y + 13, TEXT);
			text(g, "Lv " + level + "/" + upgrade.getMaxLevel(), row.x + 92, row.y + 13, TEXT_DIM);

			Rectangle buy = buyButton(row);
			buyButtonBack(g, buy, mouse, maxed, affordable);
			if (maxed)
			{
				buttonLabel(g, buy, "MAX", YELLOW);
			}
			else
			{
				g.drawImage(sprites.smallEgg(EggType.PLAIN), buy.x + 4, buy.y + 1, null);
				text(g, compact(cost), buy.x + 19, buy.y + 12, affordable ? TEXT : TEXT_DIM);
				boxes.add(new HitBox(buy, () -> farm.buy(upgrade)));
			}

			if (row.contains(mouse))
			{
				tooltip(upgrade.getDescription() + "</br>Now: " + currentEffect(upgrade));
			}
		}
	}

	private String currentEffect(Upgrade upgrade)
	{
		switch (upgrade)
		{
			case INCUBATOR:
				return (1 + farm.level(upgrade)) + " slot(s)";
			case COOP:
				return farm.henCapacity() + " hens";
			case NEST_BOX:
				return farm.nestCapacity() + " eggs";
			case FEED:
				return String.format(Locale.ROOT, "%.1f eggs/hour", farm.layRatePerHour());
			case HEAT_LAMP:
				return "+" + 20 * farm.level(upgrade) + "% hatch speed";
			case LUCKY_STRAW:
				return 4 * farm.level(upgrade) + "% twins";
			case AUTO_COLLECTOR:
				return 12 * farm.level(upgrade) + " eggs/hour";
			default:
				return "";
		}
	}

	// ---------------------------------------------------------------- egg trade

	private void renderTrade(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		ExchangeOffer[] all = ExchangeOffer.values();
		for (int i = 0; i < all.length && i < ROWS_PER_PAGE; i++)
		{
			ExchangeOffer offer = all[i];
			Rectangle row = listRow(i);
			g.setColor(INSET);
			g.fill(row);

			// "[egg] x5  ->  [egg] x1"
			g.drawImage(sprites.smallEgg(offer.getGive()), row.x + 6, row.y + 1, null);
			text(g, "x" + offer.getGiveAmount(), row.x + 19, row.y + 13, TEXT);
			text(g, "->", row.x + 46, row.y + 13, TEXT_DIM);
			g.drawImage(sprites.smallEgg(offer.getGet()), row.x + 64, row.y + 1, null);
			text(g, "x" + offer.getGetAmount(), row.x + 77, row.y + 13, YELLOW);
			text(g, "have " + compact(s.eggs[offer.getGive().ordinal()]), row.x + 110, row.y + 13, TEXT_DIM);

			Rectangle trade = buyButton(row);
			boolean can = s.eggs[offer.getGive().ordinal()] >= offer.getGiveAmount();
			buyButtonBack(g, trade, mouse, false, can);
			buttonLabel(g, trade, offer.getGet() == EggType.PLAIN ? "Sell" : "Trade", can ? TEXT : TEXT_DIM);
			boxes.add(new HitBox(trade, () -> farm.exchange(offer)));
		}
	}

	// ---------------------------------------------------------------- Golden Feathers

	private void renderFeathers(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		// The list is "sell the farm" followed by every permanent upgrade
		FeatherUpgrade[] all = FeatherUpgrade.values();
		int items = all.length + 1;
		int pages = pages(items);
		listPage = Math.max(0, Math.min(pages - 1, listPage));
		pager(g, mouse, boxes, listPage, pages, 44, p -> listPage = p);

		for (int i = 0; i < ROWS_PER_PAGE; i++)
		{
			int index = listPage * ROWS_PER_PAGE + i;
			if (index >= items)
			{
				break;
			}
			Rectangle row = listRow(i);
			if (index == 0)
			{
				renderSellRow(g, row, mouse, boxes);
				continue;
			}

			FeatherUpgrade upgrade = all[index - 1];
			g.setColor(INSET);
			g.fill(row);
			int level = farm.featherLevel(upgrade);
			boolean maxed = level >= upgrade.getMaxLevel();
			int cost = maxed ? 0 : upgrade.cost(level);
			boolean affordable = !maxed && s.feathers >= cost;
			text(g, upgrade.getDisplayName(), row.x + 5, row.y + 13, TEXT);
			text(g, "Lv " + level + "/" + upgrade.getMaxLevel(), row.x + 104, row.y + 13, TEXT_DIM);

			Rectangle buy = buyButton(row);
			buyButtonBack(g, buy, mouse, maxed, affordable);
			if (maxed)
			{
				buttonLabel(g, buy, "MAX", YELLOW);
			}
			else
			{
				drawFeather(g, buy.x + 5, buy.y + 1);
				text(g, String.valueOf(cost), buy.x + 19, buy.y + 12, affordable ? TEXT : TEXT_DIM);
				boxes.add(new HitBox(buy, () -> farm.buyFeatherUpgrade(upgrade)));
			}
			if (row.contains(mouse))
			{
				tooltip(upgrade.getDescription() + "</br>Permanent");
			}
		}
	}

	private void renderSellRow(Graphics2D g, Rectangle row, Point mouse, List<HitBox> boxes)
	{
		g.setColor(new Color(70, 52, 20, 230));
		g.fill(row);
		text(g, "Sell the farm", row.x + 5, row.y + 13, GOLD);
		Rectangle sell = buyButton(row);
		boolean can = farm.canPrestige();
		buyButtonBack(g, sell, mouse, !can, can);
		drawFeather(g, sell.x + 5, sell.y + 1);
		text(g, "+" + farm.feathersForPrestige(), sell.x + 19, sell.y + 12, can ? TEXT : TEXT_DIM);
		boxes.add(new HitBox(sell, farm::requestPrestige));
		if (row.contains(mouse))
		{
			tooltip("Start over for Golden Feathers</br>Each feather: +10% laying, forever");
		}
	}

	// ---------------------------------------------------------------- farm looks

	private void renderLooks(Graphics2D g, Point mouse, List<HitBox> boxes)
	{
		FarmTheme[] all = FarmTheme.values();
		int pages = pages(all.length);
		listPage = Math.max(0, Math.min(pages - 1, listPage));
		pager(g, mouse, boxes, listPage, pages, 44, p -> listPage = p);
		FarmTheme current = farm.theme();

		for (int i = 0; i < ROWS_PER_PAGE; i++)
		{
			int index = listPage * ROWS_PER_PAGE + i;
			if (index >= all.length)
			{
				break;
			}
			FarmTheme theme = all[index];
			Rectangle row = listRow(i);
			g.setColor(INSET);
			g.fill(row);
			// Little colour swatch of the look
			g.setColor(theme.getBackdrop());
			g.fillRect(row.x + 4, row.y + 3, 14, 5);
			g.setColor(theme.getGrass());
			g.fillRect(row.x + 4, row.y + 8, 14, 7);
			g.setColor(theme.getFence());
			g.fillRect(row.x + 4, row.y + 7, 14, 2);

			boolean unlocked = farm.isThemeUnlocked(theme);
			text(g, theme.getDisplayName(), row.x + 23, row.y + 13, unlocked ? TEXT : TEXT_DIM);
			Rectangle use = buyButton(row);
			if (theme == current)
			{
				buyButtonBack(g, use, mouse, true, false);
				buttonLabel(g, use, "Active", YELLOW);
			}
			else if (unlocked)
			{
				buyButtonBack(g, use, mouse, false, true);
				buttonLabel(g, use, "Use", TEXT);
				boxes.add(new HitBox(use, () -> farm.setTheme(theme)));
			}
			else
			{
				buyButtonBack(g, use, mouse, true, false);
				buttonLabel(g, use, theme.requirement(), TEXT_DIM);
			}
		}
	}
}

package com.eggscape;

