@Singleton
class Sprites
{
	static final String GIANT_EASTER_EGG = "giant_easter_egg.png";
	static final String RUBBER_CHICKEN = "rubber_chicken_big.png";

	private final BufferedImage[] hens = new BufferedImage[HenType.values().length];
	private final BufferedImage[] hensFlipped = new BufferedImage[HenType.values().length];
