	private final BufferedImage[] eggsLocked = new BufferedImage[EggType.values().length];
	private final BufferedImage[] smallEggs = new BufferedImage[EggType.values().length];
	private final BufferedImage smallHen;
	private final BufferedImage goldenEgg;
	private final BufferedImage goldenEggLocked;
	private final BufferedImage evilChicken;
	private final BufferedImage evilChickenFlipped;
	private final BufferedImage rooster;
	private final BufferedImage roosterFlipped;
	private final BufferedImage basket;
	private final BufferedImage easterBasket;
	private final BufferedImage coop;
	private final BufferedImage farmer;
	private final BufferedImage undeadChicken;
	private final BufferedImage undeadChickenFlipped;
	private final BufferedImage feather;
	private final BufferedImage goldenCoop;
	private final BufferedImage[] bigTrophies = new BufferedImage[AchievementTier.values().length];
	private final Map<EggscapeOverlay.Tab, BufferedImage> tabIcons = new EnumMap<>(EggscapeOverlay.Tab.class);
	private final BufferedImage bunny;
	private final BufferedImage bunnyFlipped;
	private final BufferedImage rubberChicken;
	private final BufferedImage rubberChickenLocked;
	private final BufferedImage bush;
	private final BufferedImage bushHover;
	private final Map<String, BufferedImage> dialogImages = new HashMap<>();

	Sprites()
	{
		for (HenType hen : HenType.values())
		{
			BufferedImage img = load(hen.getSprite());
			hens[hen.ordinal()] = img;
			hensFlipped[hen.ordinal()] = ImageUtil.flipImage(img, true, false);
			tileHens[hen.ordinal()] = ImageUtil.resizeImage(img, 20, 27);
			tileHensLocked[hen.ordinal()] = silhouette(tileHens[hen.ordinal()]);
		}
		for (EggType egg : EggType.values())
		{
			BufferedImage img = load(egg.getSprite());
			eggs[egg.ordinal()] = img;
			eggsLocked[egg.ordinal()] = silhouette(img);
			smallEggs[egg.ordinal()] = ImageUtil.resizeImage(img, 11, 15);
		}
		smallHen = ImageUtil.resizeImage(hens[HenType.BROWN.ordinal()], 12, 16);
		goldenEgg = load("egg_golden.png");
		goldenEggLocked = silhouette(goldenEgg);
		evilChicken = load("evil_chicken.png");
		evilChickenFlipped = ImageUtil.flipImage(evilChicken, true, false);
		rooster = load("rooster.png");
		roosterFlipped = ImageUtil.flipImage(rooster, true, false);
		basket = load("basket.png");
		easterBasket = load("easter_basket.png");
		coop = load("coop.png");
		farmer = load("farmer.png");
		undeadChicken = load("undead_chicken.png");
		undeadChickenFlipped = ImageUtil.flipImage(undeadChicken, true, false);
		feather = load("feather.png");
		goldenCoop = gild(coop);
		for (AchievementTier tier : AchievementTier.values())
		{
			bigTrophies[tier.ordinal()] = load("trophy_" + tier.name().toLowerCase() + "_big.png");
		}
		// OSRS items as tab icons: a hen, coins, a flyer, the collection log and the holy grail
		tabIcons.put(EggscapeOverlay.Tab.FARM, ImageUtil.resizeImage(hens[HenType.BROWN.ordinal()], 10, 14));
		tabIcons.put(EggscapeOverlay.Tab.SHOP, load("tab_shop.png"));
		tabIcons.put(EggscapeOverlay.Tab.TASKS, load("tab_tasks.png"));
		tabIcons.put(EggscapeOverlay.Tab.LOG, load("tab_log.png"));
		tabIcons.put(EggscapeOverlay.Tab.GOALS, load("tab_goals.png"));
		bunny = load("bunny.png");
		bunnyFlipped = ImageUtil.flipImage(bunny, true, false);
		rubberChicken = load("rubber_chicken.png");
		rubberChickenLocked = silhouette(rubberChicken);
		bush = load("bush.png");
		// A lighter bush for mouse-over; alpha is left alone
		bushHover = new RescaleOp(new float[]{1.3f, 1.3f, 1.3f, 1f}, new float[]{12, 12, 12, 0}, null).filter(bush, null);
		dialogImages.put(GIANT_EASTER_EGG, load(GIANT_EASTER_EGG));
		dialogImages.put(RUBBER_CHICKEN, load(RUBBER_CHICKEN));
	}

	/**
	 * Golden version of the wooden coop for the Royal farm look.
	 */
	private static BufferedImage gild(BufferedImage src)
	{
		BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		float[] hsb = new float[3];
		for (int y = 0; y < src.getHeight(); y++)
		{
			for (int x = 0; x < src.getWidth(); x++)
			{
				int argb = src.getRGB(x, y);
				int alpha = argb >>> 24;
				Color.RGBtoHSB((argb >> 16) & 0xff, (argb >> 8) & 0xff, argb & 0xff, hsb);
				int rgb = Color.HSBtoRGB(46f / 360f, 0.8f, Math.min(1f, hsb[2] * 1.7f));
				out.setRGB(x, y, alpha << 24 | (rgb & 0xffffff));
			}
		}
		return out;
	}

	private static BufferedImage load(String name)
	{
		return ImageUtil.loadImageResource(EggscapePlugin.class, name);
	}

	/**
	 * Dark shape used in the collection log for things you haven't found yet.
	 */
	private static BufferedImage silhouette(BufferedImage src)
	{
		BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < src.getHeight(); y++)
		{
			for (int x = 0; x < src.getWidth(); x++)
			{
				int alpha = src.getRGB(x, y) >>> 24;
				out.setRGB(x, y, (alpha * 3 / 4) << 24 | 0x14110d);
			}
		}
		return out;
	}

	BufferedImage hen(HenType hen, boolean facingRight)
	{
		return facingRight ? hensFlipped[hen.ordinal()] : hens[hen.ordinal()];
