		return basket;
	}

	BufferedImage easterBasket()
	{
		return easterBasket;
	}

	BufferedImage coop()
	{
		return coop;
	}

	BufferedImage farmer()
	{
		return farmer;
	}

	BufferedImage undeadChicken(boolean facingRight)
	{
		return facingRight ? undeadChickenFlipped : undeadChicken;
	}

	BufferedImage feather()
