package com.eggscape;

import java.util.Random;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.client.util.QuantityFormatter;

/**
 * Daily task templates. Saved by ordinal, so only ever add new ones at the end.
 */
@Getter
@RequiredArgsConstructor
public enum TaskType
{
	HATCH("Hatch %s chickens", 4, 10, 1),
	KILL_CHICKENS("Kill %s chickens", 5, 15, 1),
	KILL_MONSTERS("Kill %s monsters", 20, 50, 5),
	GAIN_XP("Gain %s XP in any skill", 10_000, 50_000, 5_000),
	FIND_EGGS("Find %s eggs while playing", 10, 30, 5),
	COLLECT_NEST("Collect %s eggs from the nest", 20, 60, 5),
	EVENTS("Complete %s farm events", 1, 3, 1);

	private final String format;
	private final int min;
	private final int max;
	private final int step;

	long rollTarget(Random random)
	{
		int steps = (max - min) / step;
		return min + (long) random.nextInt(steps + 1) * step;
	}

	String describe(long target)
	{
		return String.format(format, QuantityFormatter.quantityToStackSize(target));
	}
}

package com.eggscape;

import static com.eggscape.Layout.WIDTH;
import static com.eggscape.Ui.BUY;
import static com.eggscape.Ui.BUY_HOVER;
import static com.eggscape.Ui.DONE;
import static com.eggscape.Ui.INSET;
import static com.eggscape.Ui.PANEL_EDGE;
import static com.eggscape.Ui.TEXT;
import static com.eggscape.Ui.TEXT_DIM;
import static com.eggscape.Ui.YELLOW;
import static com.eggscape.Ui.blink;
import static com.eggscape.Ui.buttonLabel;
import static com.eggscape.Ui.centered;
import static com.eggscape.Ui.compact;
import static com.eggscape.Ui.text;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

/**
 * The Tasks tab: three daily tasks, the bonus chest and the login streak.
 */
@Singleton
class TasksTab extends PanelPart
{
	@Inject
	TasksTab(FarmManager farm, Sprites sprites, TooltipManager tooltipManager)
	{
		super(farm, sprites, tooltipManager);
	}

	void render(Graphics2D g, FarmState s, Point mouse, List<HitBox> boxes)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		text(g, "Streak: " + s.streak + (s.streak == 1 ? " day" : " days"), 6, 55, s.streak >= 7 ? YELLOW : TEXT);
		String reset = "New in " + FarmManager.formatDuration(DailyRewards.secondsUntilReset());
		text(g, reset, WIDTH - 6 - g.getFontMetrics().stringWidth(reset), 55, TEXT_DIM);
		if (new Rectangle(4, 44, 110, 14).contains(mouse))
		{
			EggType bonus = DailyRewards.dailyBonusEgg(s.streak + 1);
			tooltip("Log in daily to grow your streak</br>Tomorrow: " + DailyRewards.dailyEggs(s.streak + 1) + " eggs"
				+ (bonus != null ? " + " + bonus.getDisplayName().toLowerCase() : ""));
		}

		long reward = farm.getDaily().taskRewardEggs();
		for (int i = 0; i < s.tasks.size(); i++)
		{
			FarmState.DailyTask task = s.tasks.get(i);
			Rectangle row = new Rectangle(4, 60 + i * 27, WIDTH - 8, 25);
			g.setColor(task.claimed ? DONE : INSET);
			g.fill(row);
			TaskType type = task.taskType();
			text(g, type.describe(task.target), row.x + 5, row.y + 11, task.claimed ? YELLOW : TEXT);

			Rectangle bar = new Rectangle(row.x + 5, row.y + 15, 108, 6);
			g.setColor(new Color(20, 16, 12));
			g.fill(bar);
			g.setColor(task.isComplete() ? new Color(90, 200, 60) : new Color(200, 160, 50));
			g.fillRect(bar.x, bar.y, (int) (bar.width * Math.min(1, task.progress / (double) task.target)), bar.height);
			text(g, compact(task.progress) + "/" + compact(task.target), bar.x + bar.width + 4, row.y + 22, TEXT_DIM);

			Rectangle claim = new Rectangle(row.x + row.width - 54, row.y + 4, 50, 17);
			if (task.claimed)
			{
				buttonLabel(g, claim, "Done", YELLOW);
			}
			else if (task.isComplete())
			{
				g.setColor(claim.contains(mouse) ? BUY_HOVER : BUY);
				g.fill(claim);
				g.setColor(blink() ? YELLOW : PANEL_EDGE);
				g.drawRect(claim.x, claim.y, claim.width - 1, claim.height - 1);
				buttonLabel(g, claim, "Claim", TEXT);
				final int index = i;
				boxes.add(new HitBox(claim, () -> farm.getDaily().claimTask(index)));
			}
			else
			{
				// The reward, so it's clear what the task is worth
				g.drawImage(sprites.smallEgg(EggType.PLAIN), claim.x + 4, claim.y + 1, null);
				text(g, String.valueOf(reward), claim.x + 18, claim.y + 12, TEXT_DIM);
			}
		}

		// Bonus chest for finishing all three
		Rectangle chest = new Rectangle(4, 142, WIDTH - 8, 14);
		boolean claimable = farm.getDaily().isChestClaimable();
		g.setColor(claimable ? (chest.contains(mouse) ? BUY_HOVER : BUY) : INSET);
		g.fill(chest);
		String label = s.taskChestClaimed ? "Bonus chest opened" : claimable ? "Open your bonus chest!" : "All 3 done: bonus chest";
		centered(g, label, chest.y + 11, claimable ? (blink() ? YELLOW : TEXT) : s.taskChestClaimed ? YELLOW : TEXT_DIM);
		if (claimable)
		{
			boxes.add(new HitBox(chest, farm.getDaily()::claimChest));
		}
	}
}

package com.eggscape;

import java.awt.Color;
