import net.runelite.client.ui.FontManager;

/**
 * Colours and small drawing helpers shared by every part of the panel.
 */
final class Ui
{
	static final Color PANEL = new Color(62, 53, 41, 235);
	static final Color PANEL_EDGE = new Color(28, 24, 18);
	static final Color PANEL_INNER = new Color(110, 95, 72);
	static final Color INSET = new Color(40, 34, 26, 220);
	static final Color BUTTON = new Color(92, 78, 58);
	static final Color BUTTON_HOVER = new Color(120, 102, 74);
	static final Color BUTTON_ACTIVE = new Color(150, 110, 40);
	static final Color BUTTON_DISABLED = new Color(60, 54, 46);
	static final Color BUY = new Color(56, 110, 40);
	static final Color BUY_HOVER = new Color(72, 140, 52);
	static final Color TITLE = new Color(255, 152, 31);
	static final Color TEXT = new Color(255, 255, 255);
	static final Color TEXT_DIM = new Color(170, 160, 140);
	static final Color YELLOW = new Color(255, 255, 0);
	static final Color DOT = new Color(230, 40, 30);
	static final Color GOLD = new Color(255, 200, 40);
	static final Color GOLD_DARK = new Color(170, 120, 20);
	static final Color DONE = new Color(46, 80, 34, 230);

	private Ui()
	{
	}

	// ---------------------------------------------------------------- text

	/**
	 * Text with a drop shadow, like OSRS interface text.
	 */
	static void text(Graphics2D g, String s, int x, int y, Color color)
	{
		g.setColor(new Color(0, 0, 0, color.getAlpha()));
		g.drawString(s, x + 1, y + 1);
		g.setColor(color);
		g.drawString(s, x, y);
	}

	/**
	 * Text with a full black outline, readable on any background.
	 */
	static void outlined(Graphics2D g, String s, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					g.drawString(s, x + dx, y + dy);
				}
			}
		}
		g.drawString(s, x + 1, y + 2);
		g.setColor(color);
		g.drawString(s, x, y);
	}

	static void centered(Graphics2D g, String s, int y, Color color)
	{
		centeredAt(g, s, Layout.WIDTH / 2, y, color);
	}

	static void centeredAt(Graphics2D g, String s, int centerX, int y, Color color)
	{
		int w = g.getFontMetrics().stringWidth(s);
		text(g, s, centerX - w / 2, y, color);
	}

	/**
	 * Baseline that puts the visible glyphs of {@code s} exactly centred on {@code centerY}.
	 */
	static int baselineCentredOn(Graphics2D g, String s, double centerY)
	{
		Rectangle2D glyphs = g.getFont().createGlyphVector(g.getFontRenderContext(), s).getVisualBounds();
		return (int) Math.round(centerY - (glyphs.getY() + glyphs.getHeight() / 2));
	}

	static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (fm.stringWidth(candidate) > maxWidth && line.length() > 0)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(candidate);
			}
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	/**
	 * Short number for tight spaces: 950, 7.4K, 20K, 1.2M.
	 */
	static String compact(long n)
	{
		if (n < 1000)
		{
			return String.valueOf(n);
		}
		if (n < 1_000_000)
		{
			return n < 10_000 && n % 1000 != 0 ? String.format(Locale.ROOT, "%.1fK", n / 1000.0) : n / 1000 + "K";
		}
		return String.format(Locale.ROOT, "%.1fM", n / 1_000_000.0);
	}

	/**
	 * Like {@link #compact} but without decimals, for when that doesn't fit: 1K, 20K, 1M.
	 */
	static String compactShort(long n)
	{
		if (n < 1000)
		{
			return String.valueOf(n);
		}
		return n < 1_000_000 ? n / 1000 + "K" : n / 1_000_000 + "M";
	}

	/**
	 * Duration that fits next to an egg in an incubator slot: 1h 5m, 43m, 4m 12s, 9s.
	 */
	static String shortDuration(long seconds)
	{
		if (seconds >= 600 && seconds < 3600)
		{
			return seconds / 60 + "m";
		}
		return FarmManager.formatDuration(seconds);
	}

	// ---------------------------------------------------------------- colours

	static Color withAlpha(Color c, float alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, (int) (alpha * 255))));
	}

	static Color blend(Color a, Color b, float t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) (a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) (a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) (a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	static boolean blink()
	{
		return (System.currentTimeMillis() / 400) % 2 == 0;
	}

	// ---------------------------------------------------------------- boxes and buttons

	static void panel(Graphics2D g, Rectangle r)
	{
		g.setColor(PANEL);
		g.fill(r);
		g.setColor(PANEL_EDGE);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		g.setColor(PANEL_INNER);
		g.drawRect(r.x + 1, r.y + 1, r.width - 3, r.height - 3);
	}

	static void button(Graphics2D g, Rectangle r, String label, boolean active, boolean hover, boolean enabled)
	{
		g.setColor(!enabled ? BUTTON_DISABLED : active ? BUTTON_ACTIVE : hover ? BUTTON_HOVER : BUTTON);
		g.fill(r);
		g.setColor(PANEL_EDGE);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
		Font old = g.getFont();
		g.setFont(FontManager.getRunescapeSmallFont());
		buttonLabel(g, r, label, enabled ? TEXT : TEXT_DIM);
		g.setFont(old);
	}

	/**
	 * Text centred in a button.
	 */
	static void buttonLabel(Graphics2D g, Rectangle r, String label, Color color)
	{
		FontMetrics fm = g.getFontMetrics();
		text(g, label, r.x + (r.width - fm.stringWidth(label)) / 2, r.y + (r.height + fm.getAscent()) / 2 - 1, color);
	}

	/**
	 * Background of a buy/claim button: green when it can be used, grey when it can't.
	 */
	static void buyButtonBack(Graphics2D g, Rectangle r, Point mouse, boolean disabled, boolean good)
	{
		boolean hover = r.contains(mouse);
		g.setColor(disabled ? BUTTON_DISABLED : good ? (hover ? BUY_HOVER : BUY) : (hover ? BUTTON_HOVER : BUTTON));
		g.fill(r);
		g.setColor(PANEL_EDGE);
		g.drawRect(r.x, r.y, r.width - 1, r.height - 1);
	}

	/**
	 * Button with a drawn triangle, so the arrow sits exactly in the middle (font glyphs don't).
	 */
	static void arrowButton(Graphics2D g, Rectangle r, boolean left, boolean hover, boolean enabled)
	{
		button(g, r, "", false, hover, enabled);
		int cx = r.x + r.width / 2;
		int cy = r.y + r.height / 2;
		int[] xs = left ? new int[]{cx + 2, cx + 2, cx - 2} : new int[]{cx - 2, cx - 2, cx + 2};
		int[] ys = {cy - 4, cy + 4, cy};
		g.setColor(Color.BLACK);
		g.fillPolygon(new int[]{xs[0] + 1, xs[1] + 1, xs[2] + 1}, new int[]{ys[0] + 1, ys[1] + 1, ys[2] + 1}, 3);
		g.setColor(enabled ? TEXT : TEXT_DIM);
		g.fillPolygon(xs, ys, 3);
	}

	/**
	 * Small dark label with text, e.g. the flock counter.
	 */
	static Rectangle pill(Graphics2D g, String label, int x, int y)
	{
		g.setFont(FontManager.getRunescapeSmallFont());
		int w = g.getFontMetrics().stringWidth(label) + 8;
		g.setColor(new Color(0, 0, 0, 120));
		g.fillRoundRect(x, y, w, 13, 6, 6);
		text(g, label, x + 4, y + 10, TEXT);
		return new Rectangle(x, y, w, 13);
	}

	/**
	 * Red notification dot in the top-right corner of a button: something to claim or buy there.
	 */
	static void dot(Graphics2D g, Rectangle r)
	{
		g.setColor(Color.BLACK);
		g.fillOval(r.x + r.width - 6, r.y - 2, 7, 7);
		g.setColor(DOT);
		g.fillOval(r.x + r.width - 5, r.y - 1, 5, 5);
	}

	// ---------------------------------------------------------------- little decorations

	/**
	 * Twinkling four-point stars around a centre point, for shinies and golden things.
	 */
	static void sparkles(Graphics2D g, int cx, int cy, int radius, int seed)
	{
		long now = System.currentTimeMillis();
		for (int i = 0; i < 3; i++)
		{
			double a = now / 400.0 + i * 2.1 + seed;
			int sx = cx + (int) (Math.cos(a) * radius);
			int sy = cy + (int) (Math.sin(a * 1.3) * radius);
			float alpha = (float) (0.5 + 0.5 * Math.sin(now / 150.0 + i * 1.7 + seed));
			g.setColor(new Color(1f, 1f, 0.75f, alpha));
			g.drawLine(sx - 2, sy, sx + 2, sy);
			g.drawLine(sx, sy - 2, sx, sy + 2);
		}
	}

	/**
	 * Tiny 7x7 star, gold when fully mastered.
	 */
	static void masteryStar(Graphics2D g, int x, int y, boolean max)
	{
		int[] xs = {x + 3, x + 4, x + 7, x + 5, x + 6, x + 3, x, x + 1, x - 1, x + 2};
		int[] ys = {y, y + 2, y + 2, y + 4, y + 7, y + 5, y + 7, y + 4, y + 2, y + 2};
		g.setColor(Color.BLACK);
		g.drawPolygon(xs, ys, xs.length);
		g.setColor(max ? GOLD : new Color(230, 230, 230));
		g.fillPolygon(xs, ys, xs.length);
	}

	/**
	 * A small round medal in a metal's colour; an empty ring when no tier is reached yet.
	 */
	static void medal(Graphics2D g, int x, int y, AchievementTier tier)
	{
		Graphics2D m = (Graphics2D) g.create();
		m.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		if (tier == null)
		{
			m.setColor(new Color(90, 80, 66));
			m.drawOval(x, y, 9, 9);
			m.dispose();
			return;
		}
		m.setColor(Color.BLACK);
		m.fillOval(x - 1, y - 1, 11, 11);
		m.setColor(tier.getColor());
		m.fillOval(x, y, 9, 9);
		m.setColor(blend(tier.getColor(), Color.WHITE, 0.55f));
		m.fillOval(x + 2, y + 2, 3, 3);
		if (tier == AchievementTier.DRAGON)
		{
			m.setColor(GOLD);
			m.drawOval(x, y, 9, 9);
		}
		m.dispose();
	}
}

package com.eggscape;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * Upgrades bought with plain eggs. Saved by ordinal, so only ever add new ones at the end.
 */
@Getter
@RequiredArgsConstructor
public enum Upgrade
{
	INCUBATOR("Incubator", "Adds an extra incubator slot", 3, 20, 5.0, 1),
	COOP("Bigger coop", "Room for 4 more hens", 20, 15, 1.55, 1),
	NEST_BOX("Nest box", "Holds 15 more laid eggs", 10, 10, 1.7, 1),
	FEED("Corn feed", "Hens lay 25% faster", 10, 25, 1.9, 1),
	HEAT_LAMP("Heat lamp", "Eggs hatch 20% faster", 8, 30, 2.0, 1),
	LUCKY_STRAW("Lucky straw", "+4% chance to hatch twins", 10, 60, 2.1, 1),
	AUTO_COLLECTOR("Auto-collector", "Gathers 12 eggs/hour from your nest box", 5, 150, 2.5, FarmManager.LEVEL_AUTO_COLLECTOR);

	private final String displayName;
	private final String description;
	private final int maxLevel;
	private final int baseCost;
	private final double costGrowth;
	/**
	 * Farm level needed before this upgrade can be bought.
	 */
	private final int minFarmLevel;

	/**
	 * Cost in plain eggs to go from {@code level} to {@code level + 1}.
	 */
	public long cost(int level)
	{
		return Math.round(baseCost * Math.pow(costGrowth, level));
	}
}

